                        <div className="text-right">
                          <div className="font-bold text-indigo-600">Bs {Number(prod.precio).toFixed(2)}</div>
                          <div className="mt-1 text-xs text-slate-500">ID: {prod.user_id ?? prod.id}</div>
                        </div>
                      </div>

                      <div className="mt-3">
                        <StockHumanCard prod={prod} compact />
                      </div>

                      <div className="mt-3 flex flex-wrap items-center gap-2">
                        <span className="text-xs text-slate-500">{categoryName}</span>
                        <span className={"inline-flex items-center rounded-full px-2 py-1 text-[11px] font-bold " + getStockColor(prod)}>
                          {getStockLabel(prod)}
                        </span>
                      </div>

                      <div className="mt-1 text-xs text-slate-600">
                        Colores: {getColorStockDisplay(prod)}
                      </div>

                      <div className="mt-3 flex justify-end">
                        <button
                          type="button"
                          onClick={() => sendWhatsappAlerta(prod)}
                          disabled={sendingAlertId === pid}
                          className="inline-flex items-center gap-2 rounded-md bg-amber-500 px-3 py-1 text-sm font-semibold text-white hover:bg-amber-600 disabled:bg-amber-300"
                        >
                          {sendingAlertId === pid ? "Enviando..." : "Alerta"}
                        </button>
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>

            <div className="mt-6 flex items-center justify-between gap-3 rounded-xl border border-slate-200 bg-white p-4 shadow">
              <button
                type="button"
                disabled={page === 0}
                onClick={() => setPage((prev) => Math.max(0, prev - 1))}
                className="rounded-md border border-slate-300 px-4 py-2 text-sm font-semibold text-slate-700 disabled:opacity-50"
              >
                Anterior
              </button>
              <span className="text-sm text-slate-600">Pagina {page + 1} de {totalPages}</span>
              <button
                type="button"
                disabled={page + 1 >= totalPages}
                onClick={() => setPage((prev) => prev + 1)}
                className="rounded-md border border-slate-300 px-4 py-2 text-sm font-semibold text-slate-700 disabled:opacity-50"
              >
                Siguiente
              </button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

"use client";

import React, { useEffect, useState } from "react";
import { supabase } from "../../../../lib/SupabaseClient";
import { Card, CardHeader, CardTitle, CardContent, CardDescription } from "../../../../components/ui/card";
import { PieChart, Pie, Cell, Tooltip as PieTooltip, ResponsiveContainer, LineChart, Line, XAxis, YAxis, Tooltip as LineTooltip } from "recharts";

function formatAmount(v) {
  const num = Number(v) || 0;
  return `Bs ${num.toLocaleString('es-BO', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
}

const normalizeMetodo = (m) => {
  const map = {
    efectivo: "cash",
    tarjeta: "card",
    transferencia: "transfer",
    qr: "qr",
  };
  return map[m?.toLowerCase()] || "other";
};

const METODOS = [
  { key: "cash", label: "Efectivo", color: "#004080" },
  { key: "qr", label: "QR", color: "#4a0f0f" },
  { key: "card", label: "Tarjeta", color: "#0a7b83" },
  { key: "transfer", label: "Transferencia", color: "#7b3f00" },
  { key: "other", label: "Otro", color: "#666" },
];

export default function PagosEstadisticaPage() {
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    async function fetchStats() {
      setLoading(true);
      setError(null);
      try {
        // Rango: últimos 30 días
        const today = new Date();
        const start = new Date(today);
        start.setDate(today.getDate() - 29);
        const startDate = start.toISOString().slice(0, 10);
        const endDate = today.toISOString().slice(0, 10);

        // Traer resumen de caja (incluye ventas y movimientos manuales)
        const { getCashSummary } = await import("../../../../services/cash.service.js");
        const summary = await getCashSummary(supabase, {
          start_date: startDate,
          end_date: endDate,
        });

        // Totales por método y tipo
        const totales = {};
        METODOS.forEach(m => {
          totales[m.key] = {
            sistema: 0,
            manual: 0,
            countSistema: 0,
            countManual: 0,
          };
        });
        (summary.sales || []).forEach(s => {
          const metodo = normalizeMetodo(s.modo_pago);
          if (totales[metodo]) {
            totales[metodo].sistema += Number(s.total || 0);
            totales[metodo].countSistema += 1;
          }
        });
        (summary.movements || []).forEach(m => {
          if (m && m.type === "income") {
            const metodo = normalizeMetodo(m.payment_method);
            if (totales[metodo]) {
              totales[metodo].manual += Number(m.amount || 0);
              totales[metodo].countManual += 1;
            }
          }
        });

        // Flujo por día
        const flujoPorDia = {};
        (summary.sales || []).forEach(s => {
          const date = s.fecha?.slice(0, 10);
          if (!date) return;
          flujoPorDia[date] = (flujoPorDia[date] || 0) + Number(s.total || 0);
        });
        (summary.movements || []).forEach(m => {
          if (m && m.type === "income") {
            const date = m.date?.slice(0, 10);
            if (!date) return;
            flujoPorDia[date] = (flujoPorDia[date] || 0) + Number(m.amount || 0);
          }
        });
        const lineData = Object.entries(flujoPorDia)
          .map(([date, total]) => ({ date, total }))
          .sort((a, b) => new Date(a.date) - new Date(b.date));

        setStats({ totales, lineData });
      } catch (err) {
        setError("Error cargando estadísticas generales de pagos");
      } finally {
        setLoading(false);
      }
    }
    fetchStats();
  }, []);

  // --- UI ---
  const totalGeneral = stats
    ? METODOS.reduce(
        (acc, m) => acc + (stats.totales[m.key]?.sistema || 0) + (stats.totales[m.key]?.manual || 0),
        0
      )
    : 0;

  const pieData = stats
    ? METODOS.map(m => ({
        name: m.label,
        value: (stats.totales[m.key]?.sistema || 0) + (stats.totales[m.key]?.manual || 0),
      }))
    : [];

  const topMetodo = stats
    ? METODOS.reduce(
        (max, m) => {
          const total = (stats.totales[m.key]?.sistema || 0) + (stats.totales[m.key]?.manual || 0);
          return total > max.total ? { key: m.label, total } : max;
        },
        { key: null, total: 0 }
      )
    : { key: null, total: 0 };

  return (
    <div style={{ maxWidth: 900, margin: "0 auto", padding: 24 }}>
      {/* HEADER KPI PRINCIPAL */}
      <div style={{ marginBottom: 24 }}>
        <h1 style={{ fontSize: 32, margin: 0, color: "#222" }}>{formatAmount(totalGeneral)}</h1>
        <p style={{ color: "#222", fontWeight: 500 }}>Ingresos totales (últimos 30 días)</p>
      </div>

      <Card style={{ marginBottom: 32 }}>
        <CardHeader>
          <CardTitle style={{ color: "#222" }}>Distribución por método</CardTitle>
          <CardDescription style={{ color: "#444" }}>¿Cómo se distribuyen los ingresos?</CardDescription>
        </CardHeader>
        <CardContent>
          {loading ? (
            <div>Cargando...</div>
          ) : error ? (
            <div style={{ color: "red" }}>{error}</div>
          ) : (
            <div style={{ width: "100%", height: 300 }}>
              <ResponsiveContainer>
                <PieChart>
                  <Pie
                    data={pieData}
                    dataKey="value"
                    nameKey="name"
                    outerRadius={100}
                    label
                  >
                    {pieData.map((entry, index) => (
                      <Cell key={index} fill={METODOS[index].color} />
                    ))}
                  </Pie>
                  <PieTooltip formatter={v => formatAmount(v)} />
                </PieChart>
              </ResponsiveContainer>
            </div>
          )}
        </CardContent>
      </Card>

      <Card style={{ marginBottom: 32 }}>
        <CardHeader>
          <CardTitle style={{ color: "#222" }}>Flujo de ingresos</CardTitle>
          <CardDescription style={{ color: "#444" }}>¿Cómo evolucionaron los ingresos?</CardDescription>
        </CardHeader>
        <CardContent>
          {loading ? (
            <div>Cargando...</div>
          ) : error ? (
            <div style={{ color: "red" }}>{error}</div>
          ) : (
            <div style={{ width: "100%", height: 300 }}>
              <ResponsiveContainer>
                <LineChart data={stats.lineData}>
                  <XAxis dataKey="date" tick={{ fill: "#222" }} />
                  <YAxis tick={{ fill: "#222" }} />
                  <LineTooltip formatter={v => formatAmount(v)} />
                  <Line type="monotone" dataKey="total" stroke="#004080" strokeWidth={2} />
                </LineChart>
              </ResponsiveContainer>
            </div>
          )}
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle style={{ color: "#222" }}>Detalle por método</CardTitle>
          <CardDescription style={{ color: "#444" }}>Desglose profesional por método de pago</CardDescription>
        </CardHeader>
        <CardContent>
          {loading ? (
            <div>Cargando...</div>
          ) : error ? (
            <div style={{ color: "red" }}>{error}</div>
          ) : (
            <div style={{ display: "flex", gap: 32, flexWrap: "wrap", marginBottom: 32 }}>
              {METODOS.map(m => {
                const metodoTotal = (stats.totales[m.key]?.sistema || 0) + (stats.totales[m.key]?.manual || 0);
                const porcentaje = totalGeneral ? (metodoTotal / totalGeneral) * 100 : 0;
                return (
                  <div key={m.key} style={{ minWidth: 180, flex: 1, border: "1px solid #eee", borderRadius: 12, padding: 16, background: "#fff" }}>
                    <div style={{ fontWeight: 600, color: m.color, fontSize: 18 }}>{m.label}</div>
                    <div style={{ fontSize: 22, color: m.color, fontWeight: 700 }}>{formatAmount(metodoTotal)}</div>
                    <div style={{ fontSize: 13, color: "#222" }}>Sistema: {formatAmount(stats.totales[m.key]?.sistema)} ({stats.totales[m.key]?.countSistema} pagos)</div>
                    <div style={{ fontSize: 13, color: "#222" }}>Manual: {formatAmount(stats.totales[m.key]?.manual)} ({stats.totales[m.key]?.countManual} pagos)</div>
                    <div style={{ fontSize: 12, color: "#888" }}>{porcentaje.toFixed(1)}% del total</div>
                  </div>
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>

      {/* INSIGHT AUTOMÁTICO */}
      {!loading && !error && topMetodo.key && (
        <div style={{ marginTop: 20, padding: 12, background: "#f9fafb", borderRadius: 8, color: "#222" }}>
          Método dominante: <strong>{topMetodo.key}</strong>
        </div>
      )}
    </div>
  );
}

"use client";
import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { supabase } from "../../../lib/SupabaseClient";
import { useSucursalActiva } from "../../../components/admin/SucursalContext";

export default function PedidosPage() {
  const [carritos, setCarritos] = useState([]);
  const router = useRouter();
  const { activePaisId, activeSucursalId } = useSucursalActiva();

  useEffect(() => {
    if (!activePaisId || !activeSucursalId) return;
    fetchCarritos();
  }, [activePaisId, activeSucursalId]);

  async function fetchCarritos() {
    let query = supabase
      .from("carritos_pendientes")
      .select("id, cliente_nombre, cliente_telefono, usuario_email, productos, fecha, confirmado_pago, estado, pais_id, sucursal_id")
      .order("fecha", { ascending: false });
    if (activePaisId) query = query.eq("pais_id", activePaisId);
    if (activeSucursalId) query = query.eq("sucursal_id", activeSucursalId);
    const { data, error } = await query;
    
    if (!error && data) {
      const currentDate = new Date();

      // Elimina los carritos que han pasado más de 5 días sin confirmación de pago
      const carritosActualizados = data.filter(carrito => {
        const carritoDate = new Date(carrito.fecha);
        const diferenciaEnDias = (currentDate - carritoDate) / (1000 * 3600 * 24); // Diferencia en días
        return diferenciaEnDias <= 5 && !carrito.confirmado_pago && (carrito.estado || "pendiente") === "pendiente";
      });

      setCarritos(carritosActualizados);

      // Los pedidos vencidos permanecen en la base para trazabilidad; no se borran desde el navegador.
    }
  }

  async function eliminarCarrito(id) {
    const reason = window.prompt("Motivo para retirar el pedido de pendientes (permanecerá en auditoría):");
    if (!reason?.trim()) return;
    const { data: sessionData } = await supabase.auth.getSession();
    const token = sessionData?.session?.access_token;
    if (!token) return window.alert("Sesión no disponible");
    const response = await fetch("/api/admin/pedidos/descartar", {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
      body: JSON.stringify({ orderId: Number(id), paisId: activePaisId, sucursalId: activeSucursalId, reason: reason.trim() }),
    });
    const payload = await response.json();
    if (!response.ok || !payload?.success) return window.alert(payload?.error || "No se pudo descartar el pedido");
    fetchCarritos();
  }

  function efectivizarVenta(carrito) {
    // Guardar el pedido en sessionStorage y redirigir a ventas/nueva
    sessionStorage.setItem('pedido_a_efectivizar', JSON.stringify(carrito));
    router.push('/admin/ventas/nueva');
  }

  return (
    <div className="min-h-screen w-full flex flex-col items-center justify-start py-8 px-2 bg-gray-100">
      <h1 className="text-3xl font-extrabold mb-8 text-gray-900 w-full text-center">Pedidos Pendientes</h1>
      <div className="w-full max-w-5xl grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-6">
        {carritos.length === 0 ? (
          <div className="text-gray-900 mb-4 col-span-full">No hay pedidos pendientes.</div>
        ) : (
          carritos.map(c => (
            <div key={c.id} className="bg-white rounded-xl shadow-xl border border-gray-900 p-4 flex flex-col gap-2">
              <div className="font-bold text-lg text-blue-900 mb-1">Pedido #{c.id}</div>
              <div className="text-gray-900 font-semibold">Cliente: {c.cliente_nombre || `Pedido #${c.id}`}</div>
              <div className="text-gray-700 text-sm mb-1">NIT/CI: {c.cliente_telefono || '-'}</div>
              <div className="text-gray-700 text-sm mb-1">Email: {c.usuario_email || '-'}</div>
              <div className="text-gray-900 text-sm mb-1">Fecha: {new Date(c.fecha).toLocaleString()}</div>
              <div className="mb-2">
                <div className="font-bold text-gray-800">Productos:</div>
                <ul className="list-disc pl-4">
                  {Array.isArray(c.productos) ? c.productos.map((p, i) => (
                    <li key={i} className="text-gray-900">
                      {p.nombre || p.producto_id} {p.color ? `(${p.color})` : ''} {p.cantidad} {p.unidad || 'unidad'} (Bs {Number(p.precio_unitario).toFixed(2)})
                    </li>
                  )) : null}
                </ul>
              </div>
              <div className="flex gap-2 mt-auto">
                <button
                  onClick={() => efectivizarVenta(c)}
                  className="flex-1 bg-blue-700 hover:bg-blue-800 text-white px-3 py-2 rounded font-bold disabled:opacity-60"
                >
                  Efectivizar venta
                </button>
                <button onClick={() => eliminarCarrito(c.id)} className="flex-1 bg-red-700 hover:bg-red-800 text-white px-3 py-2 rounded font-bold">Eliminar</button>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

"use client";
import dynamic from "next/dynamic";
import { resolveStorageImageUrl } from '../../../lib/storageImageUrl.mjs';
const SafeImage = dynamic(() => import("../../../components/SafeImage"), { ssr: false });
const PerfilForm = dynamic(() => import("../../../components/PerfilForm.client"), { ssr: false });
import { useEffect, useState } from "react";
import { supabase } from "../../../lib/SupabaseClient";
import { useRouter } from "next/navigation";

export default function PerfilPage() {
  const [user, setUser] = useState(null);
  const [perfil, setPerfil] = useState(null);
  const [loading, setLoading] = useState(true);
  const [editando, setEditando] = useState(false);
  const [authorized, setAuthorized] = useState(false);
  const router = useRouter();

  useEffect(() => {
    const getUser = async () => {
      try {
        // 1. Verificar que el usuario esté autenticado
        const { data: { session }, error: sessionError } = await supabase.auth.getSession();
        
        if (sessionError || !session?.user) {
          router.push('/login');
          return;
        }

        const currentUser = session.user;
        setUser(currentUser);

        // 2. SEGURIDAD: Solo permitir acceso a SU PROPIO perfil
        // Verificar que no pueda editar otros perfiles
        const { data: perfilData, error: perfilError } = await supabase
          .from('perfiles')
          .select('*')
          .eq('id', currentUser.id) // CRÍTICO: Solo SU perfil
          .single();
        
        if (perfilError && perfilError.code !== 'PGRST116') { // PGRST116 = no rows
          console.error('❌ Error cargando perfil:', perfilError);
          router.push('/');
          return;
        }

        // 3. Establecer datos seguros
        const finalPerfil = perfilData || {
          id: currentUser.id,
          email: currentUser.email,
          nombre: '',
          telefono: '',
          nit_ci: '',
          rol: 'cliente', // Por defecto cliente
          foto_url: null
        };
        
        setPerfil(finalPerfil);
        setAuthorized(true);
        
      } catch (error) {
        console.error('❌ Error de autorización:', error);
        router.push('/login');
      } finally {
        setLoading(false);
      }
    };
    
    getUser();
  }, [router]);

  const recargarPerfil = async () => {
    if (user && authorized) {
      // SEGURIDAD: Solo permitir recargar SU PROPIO perfil
      const { data: perfilData } = await supabase
        .from('perfiles')
        .select('*')
        .eq('id', user.id) // CRÍTICO: Solo SU perfil
        .single();
      
      setPerfil(perfilData);
      setEditando(false);
    }
  };

  // SEGURIDAD: Loading state
  if (loading) {
    return (
      <div className="flex justify-center items-center min-h-[60vh]">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto mb-4"></div>
          <p className="text-gray-600">Verificando permisos...</p>
        </div>
      </div>
    );
  }

  // SEGURIDAD: Bloquear acceso no autorizado
  if (!user || !authorized) {
    return (
      <div className="flex justify-center items-center min-h-[60vh]">
        <div className="text-center p-8">
          <div className="text-red-600 text-6xl mb-4">🔒</div>
          <h2 className="text-2xl font-bold text-gray-800 mb-2">Acceso Denegado</h2>
          <p className="text-gray-600 mb-4">No tienes permisos para acceder a esta página.</p>
          <button 
            onClick={() => router.push('/login')}
            className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg"
          >
            Iniciar Sesión
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto p-6">
      {/* Header */}
      <div className="bg-gradient-to-r from-blue-600 to-purple-600 text-white rounded-lg p-6 mb-6">
        <div className="flex items-center gap-4">
          <div className="bg-white/20 rounded-full p-3">
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
            </svg>
          </div>
          <div>
            <h1 className="text-2xl font-bold">Mi Perfil</h1>
            <p className="text-blue-100">
              {editando ? "Editando información personal" : "Información personal"}
            </p>
          </div>
        </div>
      </div>

      <div className="bg-white rounded-lg shadow-sm border p-6">
        {!editando ? (
          // MODO VISUALIZACIÓN - Mostrar datos actuales
          <div className="space-y-6">
            <div className="flex items-center justify-between">
              <h2 className="text-lg font-semibold text-gray-800 flex items-center gap-2">
                <svg className="w-5 h-5 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
                </svg>
                Mi Información Personal
              </h2>
              <button
                onClick={() => setEditando(true)}
                className="bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded-lg font-medium transition-colors flex items-center gap-2"
              >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" />
                </svg>
                Editar Perfil
              </button>
            </div>

            {/* Información actual del perfil */}
            <div className="grid md:grid-cols-2 gap-8">
              {/* Foto de perfil */}
              <div className="text-center">
                <h3 className="text-sm font-medium text-gray-700 mb-3">Foto de Perfil</h3>
                {perfil?.foto_perfil ? (
                  <SafeImage
                    src={resolveStorageImageUrl(perfil.foto_perfil)}
                    alt="Foto de perfil"
                    width={128}
                    height={128}
                    className="w-32 h-32 rounded-full mx-auto object-cover border-4 border-blue-200 shadow-lg"
                  />
                ) : (
                  <div className="w-32 h-32 rounded-full mx-auto bg-gray-200 flex items-center justify-center border-4 border-gray-300">
                    <svg className="w-16 h-16 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
                    </svg>
                  </div>
                )}
                <p className="text-sm text-gray-500 mt-2">
                  {perfil?.foto_perfil ? "Foto actual" : "Sin foto de perfil"}
                </p>
              </div>

              {/* Información personal */}
              <div className="space-y-6">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Nombre Completo
                  </label>
                  <div className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-lg text-gray-900">
                    {perfil?.nombre || "No especificado"}
                  </div>
                </div>
                
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    NIT/CI
                  </label>
                  <div className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-lg text-gray-900">
                    {perfil?.nit_ci || "No especificado"}
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Email
                  </label>
                  <div className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-lg text-gray-900">
                    {user?.email || "No especificado"}
                  </div>
                  <p className="text-xs text-gray-500 mt-1">
                    El email se gestiona desde la configuración de cuenta
                  </p>
                </div>
              </div>
            </div>
          </div>
        ) : (
          // MODO EDICIÓN - Formulario editable
          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <h2 className="text-lg font-semibold text-gray-800 flex items-center gap-2">
                <svg className="w-5 h-5 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" />
                </svg>
                Editando Mi Perfil
              </h2>
              <button
                onClick={() => setEditando(false)}
                className="bg-gray-500 hover:bg-gray-600 text-white px-4 py-2 rounded-lg font-medium transition-colors flex items-center gap-2"
              >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
                Cancelar
              </button>
            </div>
            
            <PerfilForm 
              userId={user.id} 
              perfilActual={perfil} 
              onSave={recargarPerfil}
            />
          </div>
        )}
      </div>

      {/* Link a administración de perfiles (solo para admin) */}
      {perfil?.rol === 'admin' && (
        <div className="mt-6 p-4 bg-orange-50 border border-orange-200 rounded-lg">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="bg-orange-500 text-white rounded-full p-2">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197m13.5-9a2.5 2.5 0 11-5 0 2.5 2.5 0 015 0z" />
                </svg>
              </div>
              <div>
                <h3 className="font-semibold text-orange-800">Panel de Administración</h3>
                <p className="text-orange-600 text-sm">Gestiona todos los perfiles de usuarios</p>
              </div>
            </div>
            <a 
              href="/admin/perfiles" 
              className="bg-orange-500 hover:bg-orange-600 text-white px-4 py-2 rounded-lg font-medium transition-colors"
            >
              Ir a Perfiles
            </a>
          </div>
        </div>
      )}
    </div>
  );
}

