"use client";

import { useEffect, useMemo, useState } from "react";
import { resolveStorageImageUrl } from '../../../../lib/storageImageUrl.mjs';
import { supabase } from "@/lib/SupabaseClient";

import Toast, { showToast } from '../../../../components/ui/Toast';


import { registrarMovimientoStock } from "@/lib/stockMovimientos";
import { registrarHistorialProducto } from "@/lib/productosHistorial";
import { sincronizarStockProducto } from "@/lib/utils";
import { productMatchesSearch } from "@/lib/searchMatching";
import { useSucursalActiva } from "@/components/admin/SucursalContext";

export function StockControlPage({ operation = "increase" }) {
  const isReductionMode = operation === "reduce";
  const { activePaisId, activeSucursal } = useSucursalActiva();
  const effectiveSucursalId = activeSucursal?.id || "";
  const QZ_PRINTER_NAME = "POS-80C";
  const ENABLE_QZ_DIRECT_LABEL_PRINT = true;

  const [productos, setProductos] = useState([]);
  const [variantesByProducto, setVariantesByProducto] = useState({});
  const [imagenPrincipalByProducto, setImagenPrincipalByProducto] = useState({});
  const [loading, setLoading] = useState(true);
  const [savingKey, setSavingKey] = useState(null);
  const [increments, setIncrements] = useState({});
  const [incrementUnits, setIncrementUnits] = useState({});
  const [reductionReasons, setReductionReasons] = useState({});
  const [pendingReduction, setPendingReduction] = useState(null);
  const [search, setSearch] = useState("");
  const [categoryFilter, setCategoryFilter] = useState("all");

  useEffect(() => {
    if (!activePaisId || !effectiveSucursalId) return;
    fetchData();
  }, [activePaisId, effectiveSucursalId]);

  const loadQzTray = () =>
    new Promise((resolve, reject) => {
      if (!ENABLE_QZ_DIRECT_LABEL_PRINT) {
        reject(new Error("QZ Tray desactivado"));
        return;
      }

      if (window.qz) {
        resolve(window.qz);
        return;
      }

      const existing = document.getElementById("qz-tray-script");
      if (existing) {
        existing.addEventListener("load", () => resolve(window.qz));
        existing.addEventListener("error", () => reject(new Error("No se pudo cargar QZ Tray.")));
        return;
      }
      // Ya no se carga por CDN, solo se usa window.qz global
      reject(new Error("QZ Tray no está disponible"));
    });

  const ensureQzConnection = async () => {
    const qz = await loadQzTray();
    if (!qz) throw new Error("QZ Tray no disponible");

    if (qz.security) {
      qz.security.setCertificatePromise((resolve) => resolve(null));
      qz.security.setSignaturePromise(() => (resolve) => resolve(""));
    }

    if (!qz.websocket.isActive()) {
      await qz.websocket.connect({ retries: 1, delay: 0 });
    }

    return qz;
  };

  // QZ se verifica solo al momento de imprimir para evitar ruido visual al entrar.

  function escapeHtml(value) {
    return String(value || "")
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/\"/g, "&quot;")
      .replace(/'/g, "&#039;");
  }

  function getBarcodeImageUrl(code) {
    return `https://bwipjs-api.metafloor.com/?bcid=code128&text=${encodeURIComponent(String(code || ""))}&scale=2&height=10&includetext=true`;
  }

  async function printLabels({ code, label, copies }) {
    const safeCode = String(code || "").trim();
    const safeLabel = String(label || "").trim();
    const safeCopies = Number(copies || 0);

    if (!safeCode || safeCopies <= 0) {
      showToast("No hay datos para imprimir etiquetas", "info");
      return;
    }

    const barcodeUrl = getBarcodeImageUrl(safeCode);
    const buildSingleLabelHtml = () => `
      <html>
        <head>
          <style>
            @page { size: 70mm 22mm; margin: 0; }
            html, body { margin: 0; padding: 0; width: 70mm; height: 22mm; font-family: Arial, sans-serif; }
            .label { width: 70mm; height: 22mm; box-sizing: border-box; border: 1px solid #000; display: flex; }
            .left { width: 48mm; display: flex; flex-direction: column; align-items: center; justify-content: center; }
            .left img { width: 100%; max-height: 12mm; object-fit: contain; }
            .code { font-size: 8pt; line-height: 1; }
            .right { flex: 1; display: flex; align-items: center; justify-content: center; text-align: center; font-size: 8pt; padding: 1mm; }
          </style>
        </head>
        <body>
          <div class="label">
            <div class="left">
              <img src="${barcodeUrl}" alt="${escapeHtml(safeCode)}" />
              <div class="code">${escapeHtml(safeCode)}</div>
            </div>
            <div class="right">${escapeHtml(safeLabel)}</div>
          </div>
        </body>
      </html>
    `;

    const labelHtml = buildSingleLabelHtml();

    if (ENABLE_QZ_DIRECT_LABEL_PRINT) {
      try {
        const qz = await ensureQzConnection();
        const printer = await qz.printers.find(QZ_PRINTER_NAME);
        if (!printer) throw new Error(`No se encontró la impresora ${QZ_PRINTER_NAME}.`);

        const config = qz.configs.create(printer);
        for (let i = 0; i < safeCopies; i++) {
          await qz.print(config, [{
            type: "pixel",
            format: "html",
            flavor: "plain",
            data: labelHtml,
          }]);
          if (i < safeCopies - 1) {
            await new Promise((resolve) => setTimeout(resolve, 120));
          }
        }

        showToast(`Etiquetas enviadas por QZ Tray (${safeCopies})`);
        return;
      } catch (err) {
        console.warn("QZ Tray no disponible, se usa impresión del navegador:", err);
      }
    }

    const popup = window.open("", "_blank", "width=900,height=700");
    if (!popup) {
      showToast("El navegador bloqueó la ventana de impresión", "error");
      return;
    }

    const labelsHtml = Array.from({ length: safeCopies })
      .map(() => `
        <div class="label">
          <div class="title">${escapeHtml(safeLabel)}</div>
          <img src="${barcodeUrl}" alt="${escapeHtml(safeCode)}" />
          <div class="code">${escapeHtml(safeCode)}</div>
        </div>
      `)
      .join("");

    popup.document.write(`
      <html>
        <head>
          <title>Etiquetas - ${escapeHtml(safeLabel)}</title>
          <style>
            @page { size: auto; margin: 8mm; }
            body { font-family: Arial, sans-serif; margin: 0; padding: 0; }
            .grid {
              display: grid;
              grid-template-columns: repeat(auto-fill, minmax(230px, 1fr));
              gap: 10px;
              padding: 10px;
            }
            .label {
              border: 1px solid #d1d5db;
              border-radius: 8px;
              padding: 8px;
              text-align: center;
              break-inside: avoid;
            }
            .title {
              font-size: 12px;
              font-weight: bold;
              color: #111827;
              margin-bottom: 6px;
              min-height: 28px;
            }
            img {
              width: 100%;
              max-height: 78px;
              object-fit: contain;
            }
            .code {
              margin-top: 4px;
              font-size: 11px;
              color: #374151;
              word-break: break-all;
            }
          </style>
        </head>
        <body>
          <div class="grid">${labelsHtml}</div>
          <script>
            window.onload = function () { window.print(); };
          </script>
        </body>
      </html>
    `);
    popup.document.close();
  }

  async function fetchData() {
    setLoading(true);

    let productosQuery = supabase
      .from("productos")
      .select(`
        user_id,
        nombre,
        stock,
        imagen_url,
        codigo_barra,
        category_id,
        unidad_base,
        unidades_alternativas,
        factor_conversion,
        categorias (categori)
      `)
      .eq("archivado", false)
      .order("nombre", { ascending: true })
      .limit(1200);
    if (activePaisId) productosQuery = productosQuery.eq("pais_id", activePaisId);
    if (effectiveSucursalId) productosQuery = productosQuery.eq("sucursal_id", effectiveSucursalId);
    const { data: prods, error: prodsError } = await productosQuery;

    if (prodsError) {
      console.error("Error cargando productos:", prodsError);
      showToast("No se pudieron cargar productos", "error");
      setLoading(false);
      return;
    }

    const productosData = prods || [];
    setProductos(productosData);

    const productIds = productosData.map((p) => p.user_id).filter(Boolean);
    const imageMap = {};
    productosData.forEach((product) => {
      const pid = String(product?.user_id ?? "");
      if (pid && product?.imagen_url) imageMap[pid] = product.imagen_url;
    });

    if (productIds.length > 0) {
      let imagenesQuery = supabase
        .from("producto_imagenes")
        .select("producto_id, imagen_url")
        .in("producto_id", productIds);
      if (activePaisId) imagenesQuery = imagenesQuery.eq("pais_id", activePaisId);
      if (effectiveSucursalId) imagenesQuery = imagenesQuery.eq("sucursal_id", effectiveSucursalId);
      const { data: imagenesData } = await imagenesQuery;
      (imagenesData || []).forEach((image) => {
        const pid = String(image?.producto_id ?? "");
        if (pid && image?.imagen_url && !imageMap[pid]) imageMap[pid] = image.imagen_url;
      });
    }
    setImagenPrincipalByProducto(imageMap);

    // Filtrar y convertir a número solo IDs válidos antes de consultar variantes
    const validProductIds = productIds
      .map(id => Number(id))
      .filter(id => Number.isFinite(id) && id > 0);

    // Limitar la cantidad de IDs por petición para evitar error 400
    const CHUNK_SIZE = 80;
    let allVars = [];
    if (validProductIds.length > 0) {
      for (let i = 0; i < validProductIds.length; i += CHUNK_SIZE) {
        const chunk = validProductIds.slice(i, i + CHUNK_SIZE);
        let vars = [];
        let withActiveQuery = supabase
          .from("producto_variantes")
          .select("id, producto_id, color, stock, stock_decimal, activo, sku")
          .in("producto_id", chunk)
          .eq("activo", true)
          .order("color", { ascending: true });
        if (activePaisId) withActiveQuery = withActiveQuery.eq("pais_id", activePaisId);
        if (effectiveSucursalId) withActiveQuery = withActiveQuery.eq("sucursal_id", effectiveSucursalId);
        const withActive = await withActiveQuery;
        if (withActive.error) {
          let fallbackWithoutActiveQuery = supabase
            .from("producto_variantes")
            .select("id, producto_id, color, stock, stock_decimal, sku")
            .in("producto_id", chunk)
            .order("color", { ascending: true });
          if (activePaisId) fallbackWithoutActiveQuery = fallbackWithoutActiveQuery.eq("pais_id", activePaisId);
          if (effectiveSucursalId) fallbackWithoutActiveQuery = fallbackWithoutActiveQuery.eq("sucursal_id", effectiveSucursalId);
          const fallbackWithoutActive = await fallbackWithoutActiveQuery;
          if (fallbackWithoutActive.error) {
            let minimalFallbackQuery = supabase
              .from("producto_variantes")
              .select("id, producto_id, color, stock")
              .in("producto_id", chunk)
              .order("color", { ascending: true });
            if (activePaisId) minimalFallbackQuery = minimalFallbackQuery.eq("pais_id", activePaisId);
            if (effectiveSucursalId) minimalFallbackQuery = minimalFallbackQuery.eq("sucursal_id", effectiveSucursalId);
            const minimalFallback = await minimalFallbackQuery;
            if (minimalFallback.error) {
              console.warn("Variantes no disponibles en este esquema:", minimalFallback.error);
              vars = [];
            } else {
              vars = (minimalFallback.data || []).map((row) => ({
                ...row,
                sku: null,
              }));
            }
          } else {
            vars = fallbackWithoutActive.data;
          }
        } else {
          vars = withActive.data;
        }
        allVars = allVars.concat(vars || []);
      }
      // Agrupar resultados
      const grouped = {};
      (allVars || []).forEach((v) => {
        const pid = String(v.producto_id);
        if (!grouped[pid]) grouped[pid] = [];
        grouped[pid].push(v);
      });
      setVariantesByProducto(grouped);
      setProductos((prev) => prev.map((prod) => {
        const pid = String(prod.user_id ?? "");
        const variants = grouped[pid] || [];
        if (!Array.isArray(variants) || variants.length === 0) return prod;
        return { ...prod, variantes: variants, stock: getBaseStock(prod, variants) };
      }));
    } else {
      setVariantesByProducto({});
    }

    setLoading(false);
  }

  function getCategoryName(prod) {
    return String(prod?.categorias?.categori || prod?.categoria || prod?.category_id || "Sin categoria");
  }

  function formatQuantity(value) {
    const parsed = Number(value || 0);
    if (!Number.isFinite(parsed)) return "0";
    return Number(parsed.toFixed(3)).toString();
  }

  function getEffectiveVariantStock(variant) {
    const decimal = Number(variant?.stock_decimal);
    const legacy = Number(variant?.stock);
    const hasDecimal = variant?.stock_decimal !== null && variant?.stock_decimal !== undefined && variant?.stock_decimal !== "";
    return Math.max(0, hasDecimal && Number.isFinite(decimal) ? decimal : legacy || 0);
  }

  function getUnitInfo(prod) {
    const unidadBase = String(prod?.unidad_base || "unidad").trim() || "unidad";
    const alternativas = Array.isArray(prod?.unidades_alternativas)
      ? prod.unidades_alternativas.map((u) => String(u || "").trim()).filter(Boolean)
      : [];
    const unidadAlternativa = alternativas.find((u) => u && u !== unidadBase);
    const factor = Number(prod?.factor_conversion || 0);
    const hasConversion = Boolean(unidadAlternativa && Number.isFinite(factor) && factor > 0);
    return { unidadBase, unidadAlternativa, factor, hasConversion };
  }

  function getSelectableUnits(prod) {
    const { unidadBase, unidadAlternativa, hasConversion } = getUnitInfo(prod);
    return hasConversion ? [unidadBase, unidadAlternativa] : [unidadBase];
  }

  function normalizeUnitName(unit) {
    return String(unit || "")
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .toLowerCase()
      .trim();
  }

  function isDiscreteUnit(unit) {
    return ["unidad", "unidades", "pieza", "piezas", "pza", "pzas", "par", "pares", "item", "items", "articulo", "articulos"].includes(normalizeUnitName(unit));
  }

  function getQuantityStep(unit) {
    return isDiscreteUnit(unit) ? 1 : 0.01;
  }

  function normalizeIncrementValue(rawValue, unit) {
    const cleaned = String(rawValue || "").replace(",", ".").replace(/[^\d.]/g, "");
    const parsed = Number(cleaned);
    if (!Number.isFinite(parsed) || parsed <= 0) return 0;
    return isDiscreteUnit(unit) ? Math.floor(parsed) : parsed;
  }

  function getSelectedUnit(prod, key) {
    const units = getSelectableUnits(prod);
    const selected = incrementUnits[key];
    return units.includes(selected) ? selected : units[0];
  }

  function getBaseStock(prod, variants = null) {
    const productStock = Math.max(0, Number(prod?.stock || 0));
    const list = Array.isArray(variants) ? variants : [];
    if (list.length > 0) {
      const variantStock = list.reduce((sum, v) => sum + getEffectiveVariantStock(v), 0);
      return variantStock > 0 || productStock <= 0 ? variantStock : productStock;
    }
    return productStock;
  }

  function getReadableStockText(prod, stockInput = null) {
    const { unidadBase, unidadAlternativa, factor, hasConversion } = getUnitInfo(prod);
    const stockBase = Math.max(0, Number(stockInput ?? prod?.stock ?? 0) || 0);
    if (!hasConversion) return `${formatQuantity(stockBase)} ${unidadBase}`;

    const completos = Math.floor(stockBase + 0.000001);
    const metrosSueltos = Math.max(0, (stockBase - completos) * factor);
    const totalAlt = stockBase * factor;
    if (completos > 0 && metrosSueltos > 0) {
      return `${completos} ${unidadBase}${completos === 1 ? "" : "s"} + ${formatQuantity(metrosSueltos)} ${unidadAlternativa}`;
    }
    if (completos > 0) {
      return `${completos} ${unidadBase}${completos === 1 ? "" : "s"} (${formatQuantity(totalAlt)} ${unidadAlternativa})`;
    }
    return `Solo ${formatQuantity(totalAlt)} ${unidadAlternativa}`;
  }

  function getBaseIncrease(prod, key) {
    const rawAmount = Number(increments[key] || 0);
    const { unidadBase, factor, hasConversion } = getUnitInfo(prod);
    const selectedUnit = getSelectedUnit(prod, key);
    if (!hasConversion || selectedUnit === unidadBase) return rawAmount;
    return rawAmount / factor;
  }

  function setIncrementValue(key, rawValue, unit) {
    const value = normalizeIncrementValue(rawValue, unit);
    setIncrements((prev) => ({ ...prev, [key]: value }));
  }

  function setIncrementUnit(key, unit) {
    setIncrementUnits((prev) => ({ ...prev, [key]: unit }));
    setIncrements((prev) => ({ ...prev, [key]: normalizeIncrementValue(prev[key], unit) }));
  }

  async function aumentarStockApi(payload) {
    const { data: sessionData } = await supabase.auth.getSession();
    const token = sessionData?.session?.access_token;
    const response = await fetch("/api/admin/productos/aumentar-stock", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        ...(token ? { Authorization: `Bearer ${token}` } : {}),
      },
      body: JSON.stringify(payload),
    });
    const result = await response.json();
    if (!response.ok || !result.success) {
      throw new Error(result.error || "No se pudo aumentar stock");
    }
    return result;
  }

  async function aumentarStockProducto(prod, shouldPrint = false) {
    if (!activePaisId || !effectiveSucursalId) {
      showToast("Selecciona pais y sucursal antes de aumentar stock", "error");
      return;
    }

    const pid = prod.user_id;
    const key = `p-${pid}`;
    const increaseBy = getBaseIncrease(prod, key);
    const displayIncrease = Number(increments[key] || 0);
    const selectedUnit = getSelectedUnit(prod, key);

    if (increaseBy <= 0) {
      showToast("Ingresa una cantidad mayor a 0", "info");
      return;
    }

    const currentStock = Number(prod.stock || 0);
    const newStock = currentStock + increaseBy;

    try {
      setSavingKey(key);

      const result = await aumentarStockApi({
        mode: "product",
        productId: pid,
        paisId: activePaisId,
        sucursalId: effectiveSucursalId,
        baseIncrease: increaseBy,
        displayIncrease,
        selectedUnit,
      });
      const apiTotalStock = Number(result.totalStock || newStock);
      setProductos((prev) =>
        prev.map((p) => (p.user_id === pid ? { ...p, stock: apiTotalStock } : p))
      );
      setIncrements((prev) => ({ ...prev, [key]: 0 }));

      if (shouldPrint) {
        const barcode = String(prod.codigo_barra || "").trim();
        if (!barcode) {
          showToast("No se puede imprimir: el producto no tiene codigo de barras", "error");
          return;
        }
        await printLabels({ code: barcode, label: prod.nombre, copies: Math.max(1, Math.ceil(displayIncrease)) });
      }

      showToast(`Stock actualizado para ${prod.nombre}`);
      return;

      const { error } = await supabase
        .from("productos")
        .update({ stock: newStock })
        .eq("user_id", pid)
        .eq("pais_id", activePaisId)
        .eq("sucursal_id", effectiveSucursalId);

      if (error) throw error;

      // Sincroniza el stock del producto como suma de variantes
      const totalStock = await sincronizarStockProducto(pid, supabase, {
        pais_id: activePaisId,
        sucursal_id: effectiveSucursalId,
      });

      setProductos((prev) =>
        prev.map((p) => (p.user_id === pid ? { ...p, stock: totalStock } : p))
      );
      setIncrements((prev) => ({ ...prev, [key]: 0 }));

      // Registrar movimiento e historial de aumento de stock
      try {
        const user = (await supabase.auth.getUser())?.data?.user;
        // Obtener datos anteriores
        const { data: actual } = await supabase
          .from("productos")
          .select("*")
          .eq("user_id", pid)
          .eq("pais_id", activePaisId)
          .eq("sucursal_id", effectiveSucursalId)
          .single();
        const movimientoPayload = {
          producto_id: Number(pid),
          tipo: 'aumento',
          cantidad: Number(displayIncrease),
          cantidad_base: Number(increaseBy),
          unidad: selectedUnit,
          usuario_id: user?.id || null,
          usuario_email: user?.email || '',
          pais_id: activePaisId || null,
          sucursal_id: effectiveSucursalId || null,
          observaciones: `Aumento de stock desde panel (${formatQuantity(displayIncrease)} ${selectedUnit})`
        };
        await registrarMovimientoStock(movimientoPayload);
        await registrarHistorialProducto({
          producto_id: pid,
          accion: "UPDATE",
          datos_anteriores: actual,
          datos_nuevos: { ...actual, stock: totalStock },
          pais_id: activePaisId || null,
          sucursal_id: effectiveSucursalId || null,
          usuario_email: user?.email || null
        });
      } catch (err) {
        console.warn('No se pudo registrar movimiento/historial de aumento:', err);
      }

      if (shouldPrint) {
        const barcode = String(prod.codigo_barra || "").trim();
        if (!barcode) {
          showToast("No se puede imprimir: el producto no tiene código de barras", "error");
          return;
        }
        await printLabels({ code: barcode, label: prod.nombre, copies: Math.max(1, Math.ceil(displayIncrease)) });
      }

      showToast(`Stock actualizado para ${prod.nombre}`);
    } catch (err) {
      console.error("Error aumentando stock de producto:", err);
      showToast(`No se pudo actualizar el stock: ${err?.message || JSON.stringify(err)}`, "error");
    } finally {
      setSavingKey(null);
    }
  }

  async function aumentarStockVariante(prod, variante, shouldPrint = false) {
    if (!activePaisId || !effectiveSucursalId) {
      showToast("Selecciona pais y sucursal antes de aumentar stock", "error");
      return;
    }

    const pid = prod.user_id;
    const variantId = variante.id;
    const key = `v-${variantId}`;
    const increaseBy = getBaseIncrease(prod, key);
    const displayIncrease = Number(increments[key] || 0);
    const selectedUnit = getSelectedUnit(prod, key);

    if (increaseBy <= 0) {
      showToast("Ingresa una cantidad mayor a 0", "info");
      return;
    }

    const currentVariantStock = getEffectiveVariantStock(variante);
    const nextVariantStock = currentVariantStock + increaseBy;

    try {
      setSavingKey(key);

      const result = await aumentarStockApi({
        mode: "variant",
        productId: pid,
        variantId,
        paisId: activePaisId,
        sucursalId: effectiveSucursalId,
        baseIncrease: increaseBy,
        displayIncrease,
        selectedUnit,
      });
      const apiTotalStock = Number(result.totalStock || 0);
      const savedVariantStock = Number(result.nextVariantStock || nextVariantStock);

      setVariantesByProducto((prev) => ({
        ...prev,
        [String(pid)]: (prev[String(pid)] || []).map((v) =>
          v.id === variantId ? { ...v, stock: Math.floor(savedVariantStock), stock_decimal: savedVariantStock } : v
        ),
      }));

      setProductos((prev) =>
        prev.map((p) => (p.user_id === pid ? { ...p, stock: apiTotalStock } : p))
      );

      setIncrements((prev) => ({ ...prev, [key]: 0 }));

      if (shouldPrint) {
        const barcode = String(variante.codigo_barra || variante.sku || prod.codigo_barra || "").trim();
        if (!barcode) {
          showToast("No se puede imprimir: la variante/producto no tiene codigo de barras", "error");
          return;
        }
        const label = `${prod.nombre} - ${variante.color || "Unico"}`;
        await printLabels({ code: barcode, label, copies: Math.max(1, Math.ceil(displayIncrease)) });
      }

      showToast(`Stock aumentado en ${variante.color || "Unico"}`);
      return;

      const { error: variantError } = await supabase
        .from("producto_variantes")
        .update({
          stock_decimal: nextVariantStock,
          stock: Math.floor(nextVariantStock),
        })
        .eq("id", variantId)
        .eq("pais_id", activePaisId)
        .eq("sucursal_id", effectiveSucursalId);

      if (variantError) throw variantError;


      // Sincroniza el stock del producto como suma de variantes
      const totalStock = await sincronizarStockProducto(pid, supabase, {
        pais_id: activePaisId,
        sucursal_id: effectiveSucursalId,
      });

      // Registrar movimiento e historial de aumento de stock para variante
      try {
        const user = (await supabase.auth.getUser())?.data?.user;
        // Obtener datos anteriores
        const { data: actual } = await supabase
          .from("productos")
          .select("*")
          .eq("user_id", pid)
          .eq("pais_id", activePaisId)
          .eq("sucursal_id", effectiveSucursalId)
          .single();
        const movimientoPayload = {
          producto_id: Number(pid),
          variante_id: Number(variantId),
          tipo: 'aumento',
          cantidad: Number(displayIncrease),
          cantidad_base: Number(increaseBy),
          unidad: selectedUnit,
          usuario_id: user?.id || null,
          usuario_email: user?.email || '',
          pais_id: activePaisId || null,
          sucursal_id: effectiveSucursalId || null,
          observaciones: `Aumento de stock en variante (${variante.color || 'Unico'}) desde panel (${formatQuantity(displayIncrease)} ${selectedUnit})`
        };
        await registrarMovimientoStock(movimientoPayload);
        await registrarHistorialProducto({
          producto_id: pid,
          accion: "UPDATE",
          datos_anteriores: actual,
          datos_nuevos: { ...actual, stock: totalStock },
          pais_id: activePaisId || null,
          sucursal_id: effectiveSucursalId || null,
          usuario_email: user?.email || null
        });
      } catch (err) {
        console.warn('No se pudo registrar movimiento/historial de aumento (variante):', err);
      }

      setVariantesByProducto((prev) => ({
        ...prev,
        [String(pid)]: (prev[String(pid)] || []).map((v) =>
          v.id === variantId ? { ...v, stock: Math.floor(nextVariantStock), stock_decimal: nextVariantStock } : v
        ),
      }));

      setProductos((prev) =>
        prev.map((p) => (p.user_id === pid ? { ...p, stock: totalStock } : p))
      );

      setIncrements((prev) => ({ ...prev, [key]: 0 }));

      if (shouldPrint) {
        const barcode = String(variante.codigo_barra || variante.sku || prod.codigo_barra || "").trim();
        if (!barcode) {
          showToast("No se puede imprimir: la variante/producto no tiene código de barras", "error");
          return;
        }
        const label = `${prod.nombre} - ${variante.color || "Unico"}`;
        await printLabels({ code: barcode, label, copies: Math.max(1, Math.ceil(displayIncrease)) });
      }

      showToast(`Stock aumentado en ${variante.color || "Unico"}`);
    } catch (err) {
      console.error("Error aumentando stock de variante:", err);
      showToast(`No se pudo actualizar el stock de color: ${err?.message || JSON.stringify(err)}`, "error");
    } finally {
      setSavingKey(null);
    }
  }

  async function reducirStock(prod, variante = null) {
    const key = variante ? `v-${variante.id}` : `p-${prod.user_id}`;
    const displayAmount = Number(increments[key] || 0);
    const baseAmount = getBaseIncrease(prod, key);
    const selectedUnit = getSelectedUnit(prod, key);
    const reason = String(reductionReasons[key] || "").trim();
    const currentStock = variante ? getEffectiveVariantStock(variante) : getBaseStock(prod);
    if (displayAmount <= 0 || baseAmount <= 0) return showToast("Ingresa una cantidad mayor a 0", "info");
    if (!reason) return showToast("Selecciona el motivo de la reducción", "error");
    if (baseAmount > currentStock + 0.000001) return showToast("No puedes reducir más que el stock disponible", "error");
    const beforeText = getReadableStockText(prod, currentStock);
    const afterText = getReadableStockText(prod, currentStock - baseAmount);
    setPendingReduction({ prod, variante, key, displayAmount, baseAmount, selectedUnit, reason, beforeText, afterText });
  }

  async function confirmarReduccion() {
    const pending = pendingReduction;
    if (!pending) return;
    const { prod, variante, key, displayAmount, selectedUnit, reason } = pending;
    try {
      setSavingKey(key);
      setPendingReduction(null);
      await aumentarStockApi({
        operation: "reduce",
        mode: variante ? "variant" : "product",
        productId: prod.user_id,
        variantId: variante?.id,
        paisId: activePaisId,
        sucursalId: effectiveSucursalId,
        displayIncrease: displayAmount,
        selectedUnit,
        reason,
      });
      setIncrements((prev) => ({ ...prev, [key]: 0 }));
      setReductionReasons((prev) => ({ ...prev, [key]: "" }));
      await fetchData();
      showToast(`Stock reducido correctamente: ${formatQuantity(displayAmount)} ${selectedUnit}`);
    } catch (error) {
      showToast(error?.message || "No se pudo reducir el stock", "error");
    } finally {
      setSavingKey(null);
    }
  }

  const categories = useMemo(() => {
    return Array.from(new Set(productos.map((p) => getCategoryName(p)))).sort((a, b) => a.localeCompare(b, "es"));
  }, [productos]);

  const productosFiltrados = useMemo(() => {
    const term = search.trim();
    return productos.filter((prod) => {
      const categoryName = getCategoryName(prod);
      const variants = variantesByProducto[String(prod.user_id ?? prod.id ?? "")] || prod.variantes || [];
      const matchesCategory = categoryFilter === "all" || categoryName === categoryFilter;
      const matchesSearch = productMatchesSearch({ ...prod, variantes: variants }, term, [categoryName]);
      return matchesCategory && matchesSearch;
    });
  }, [productos, variantesByProducto, search, categoryFilter]);

  return (
    <div className="w-full min-h-screen bg-gradient-to-b from-white via-slate-50 to-gray-100 px-4 py-8 sm:px-6 lg:px-8">
