"use client";

import { useEffect, useState } from "react";
import { usePathname } from "next/navigation";
import ConfirmModal from "@/components/ConfirmModal";
import ProductCard from "@/components/ProductCard";
import { Toast } from "@/components/ui/Toast";
import { showToast } from "@/components/ui/Toast";
import { supabase } from "@/lib/SupabaseClient";
import { Input } from "@/components/ui/input";
import { registrarMovimientoStock } from "@/lib/stockMovimientos";
import { registrarHistorialProducto } from "@/lib/productosHistorial";
import { sincronizarStockProducto, validarProducto } from "@/lib/utils";
import { getProductViewMeta, normalizeProductView } from "@/lib/productViews";
import { productMatchesSearch } from "@/lib/searchMatching";
import { useSucursalActiva } from "@/components/admin/SucursalContext";
import { optimizeImageForUpload } from "@/lib/imageUploadOptimization";
import { v4 as uuidv4 } from "uuid";

const uploadProductImages = async (files) => {
  const uploadedImages = [];

  for (const file of files) {
    const { file: preparedFile } = await optimizeImageForUpload(file, {
      maxDimension: 2600,
      targetMaxBytes: 2.8 * 1024 * 1024,
      hardMaxBytes: 4.2 * 1024 * 1024,
      preferredQuality: 0.98,
      minQuality: 0.9,
    });
    const extension = preparedFile.name.split(".").pop() || "jpg";
    const filePath = `public/${uuidv4()}.${extension}`;
    const { error: uploadError } = await supabase.storage
      .from("product_images")
      .upload(filePath, preparedFile, { cacheControl: "3600", upsert: false });
    if (uploadError) throw new Error(`No se pudo subir la imagen: ${uploadError.message}`);

    const { data } = supabase.storage.from("product_images").getPublicUrl(filePath);
    if (!data?.publicUrl) throw new Error("No se pudo obtener la URL de la imagen subida");
    uploadedImages.push({ imagen_url: data.publicUrl });
  }

  return uploadedImages;
};

export default function EditarCatalogo() {
    const { activeSucursalId } = useSucursalActiva();
    const pathname = usePathname();
    const currentProductView = normalizeProductView(pathname?.includes('/admin/insumos') ? 'insumos' : 'articulos');
    const currentViewMeta = getProductViewMeta(currentProductView);
    // --- Lógica de edición de productos ---

    // Cargar productos, variantes, imágenes y categorías al montar
    useEffect(() => {
      const fetchData = async () => {
        setLoading(true);
        try {
          // Productos
          let productosQuery = supabase
            .from("productos")
            .select("*")
            .eq("archivado", false)
            .order("nombre", { ascending: true });
          if (activeSucursalId) productosQuery = productosQuery.eq("sucursal_id", activeSucursalId);
          const { data: productosData, error: productosError } = await productosQuery;
          if (productosError) throw productosError;

          // Imágenes
          let imagenesQuery = supabase
            .from("producto_imagenes")
            .select("id, producto_id, imagen_url");
          if (activeSucursalId) imagenesQuery = imagenesQuery.eq("sucursal_id", activeSucursalId);
          const { data: imagenesData, error: imagenesError } = await imagenesQuery;
          if (imagenesError) throw imagenesError;

          // Variantes
          let variantesQuery = supabase
            .from("producto_variantes")
            .select("*");
          if (activeSucursalId) variantesQuery = variantesQuery.eq("sucursal_id", activeSucursalId);
          const { data: variantesData, error: variantesError } = await variantesQuery;
          if (variantesError) throw variantesError;

          // Categorías
          let categoriesQuery = supabase
            .from("categorias")
            .select("id, categori");
          if (activeSucursalId) categoriesQuery = categoriesQuery.eq("sucursal_id", activeSucursalId);
          const { data: categoriesData, error: categoriesError } = await categoriesQuery;
          if (categoriesError) throw categoriesError;

          // Asociar imágenes y variantes a cada producto
          const imgs = {};
          const vars = {};
          (productosData || []).forEach((p) => {
            const key = getProductKey(p);
            imgs[key] = (imagenesData || []).filter(img => img.producto_id === p.user_id);
            vars[key] = (variantesData || []).filter(v => v.producto_id === p.user_id);
          });

          setProductos(productosData || []);
          setImagenes(imgs);
          setVariantes(vars);
          setCategories(categoriesData || []);
        } catch (err) {
          showToast("Error cargando productos: " + (err?.message || err), "error");
        }
        setLoading(false);
      };
      fetchData();
    }, [activeSucursalId]);

    useEffect(() => {
      const handlePrintVariantBarcode = (event) => {
        const { codigoBarras, nombre, copies } = event.detail || {};
        const code = String(codigoBarras || "").trim();
        if (!code) return;
        const safeName = String(nombre || "Etiqueta").replace(/[<>&"]/g, "");
        const safeCopies = Math.max(1, Math.min(200, Number(copies) || 1));
        const barcodeUrl = `https://bwipjs-api.metafloor.com/?bcid=code128&text=${encodeURIComponent(code)}&scale=2&height=10&includetext=true`;
        const labels = Array.from({ length: safeCopies }).map(() => `
          <div class="label">
            <div class="name">${safeName}</div>
            <img src="${barcodeUrl}" />
            <div class="code">${code}</div>
          </div>
        `).join("");
        const popup = window.open("", "_blank", "width=900,height=700");
        if (!popup) {
          showToast("El navegador bloqueo la ventana de impresion", "error");
          return;
        }
        popup.document.write(`
          <html>
            <head>
              <title>${safeName}</title>
              <style>
                @page { margin: 8mm; }
                body { font-family: Arial, sans-serif; margin: 0; padding: 10px; }
                .grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(230px, 1fr)); gap: 10px; }
                .label { border: 1px solid #d1d5db; border-radius: 8px; padding: 8px; text-align: center; break-inside: avoid; }
                .name { font-size: 12px; font-weight: 700; margin-bottom: 6px; }
                img { width: 100%; max-height: 78px; object-fit: contain; }
                .code { margin-top: 4px; font-size: 11px; }
              </style>
            </head>
            <body>
              <div class="grid">${labels}</div>
              <script>window.onload = function(){ window.print(); };</script>
            </body>
          </html>
        `);
        popup.document.close();
      };

      window.addEventListener("printVariantBarcode", handlePrintVariantBarcode);
      return () => window.removeEventListener("printVariantBarcode", handlePrintVariantBarcode);
    }, []);
    // Manejo de cambios en campos del producto
    const setEditDataField = (productKey, field, value) => {
      setEditando((prev) => ({
        ...prev,
        [productKey]: {
          ...prev[productKey],
          [field]: value,
        },
      }));
    };

    // Variantes
    const handleAddVariantRow = (productKey, generatedCode = "") => {
      setEditando((prev) => {
        const current = prev[productKey]?.variantes || variantes[productKey] || [];
        return {
          ...prev,
          [productKey]: {
            ...prev[productKey],
            variantes: [...current, { color: '', stock: 0, sku: generatedCode }],
          },
        };
      });
    };

    const handleVariantFieldChange = (productKey, idx, field, value) => {
      setEditando((prev) => {
        const current = prev[productKey]?.variantes || variantes[productKey] || [];
        const updated = current.map((v, i) =>
          i === idx ? { ...v, [field]: value } : v
        );
        return {
          ...prev,
          [productKey]: {
            ...prev[productKey],
            variantes: updated,
          },
        };
      });
    };

    const handleRemoveVariantRow = (productKey, idx) => {
      setEditando((prev) => {
        const current = prev[productKey]?.variantes || variantes[productKey] || [];
        const updated = current.filter((_, i) => i !== idx);
        return {
          ...prev,
          [productKey]: {
            ...prev[productKey],
            variantes: updated,
          },
        };
      });
    };

    // Imágenes
    const handleAddImages = (productKey, files) => {
      const fileList = Array.isArray(files) ? files : [];
      setImagenes((prev) => ({
        ...prev,
        [productKey]: [...(prev[productKey] || []), ...fileList],
      }));
      setEditando((prev) => ({
        ...prev,
        [productKey]: {
          ...prev[productKey],
          imagenes: [...((prev[productKey]?.imagenes) || imagenes[productKey] || []), ...fileList],
        },
      }));
    };

    const handleRemoveImage = (productKey, idx) => {
      const currentImages = editando[productKey]?.imagenes || imagenes[productKey] || [];
      const nextImages = currentImages.filter((_, i) => i !== idx);
      const removedImage = currentImages[idx];
      setImagenes((prev) => ({
        ...prev,
        [productKey]: nextImages,
      }));
      setEditando((prev) => ({
        ...prev,
        [productKey]: {
          ...prev[productKey],
          imagenes: nextImages,
          ...(
            String(prev[productKey]?.primaryImageId || "") === String(removedImage?.id || "") ||
            String(prev[productKey]?.primaryImageUrl || "") === String(removedImage?.imagen_url || "")
              ? {
                  primaryImageId: nextImages[0]?.id || null,
                  primaryImageUrl: nextImages[0]?.imagen_url || "",
                }
              : {}
          ),
        },
      }));
    };

    const handleReplaceImage = (productKey, idx, file) => {
      const currentImages = editando[productKey]?.imagenes || imagenes[productKey] || [];
      const nextImages = currentImages.map((image, i) => (i === idx ? file : image));
      setImagenes((prev) => {
        return { ...prev, [productKey]: nextImages };
      });
      setEditando((prev) => {
        return {
          ...prev,
          [productKey]: {
            ...prev[productKey],
            imagenes: nextImages,
          },
        };
      });
    };

    const handleReorderImages = (productKey, fromIdx, toIdx) => {
      if (fromIdx === toIdx || fromIdx === null || toIdx === null) return;
      const currentImages = editando[productKey]?.imagenes || imagenes[productKey] || [];
      const nextImages = [...currentImages];
      const [moved] = nextImages.splice(fromIdx, 1);
      if (!moved) return;
      nextImages.splice(toIdx, 0, moved);
      setImagenes((prev) => {
        return { ...prev, [productKey]: nextImages };
      });
      setEditando((prev) => {
        return {
          ...prev,
          [productKey]: {
            ...prev[productKey],
            imagenes: nextImages,
          },
        };
      });
    };

    // Confirmación
    const openConfirm = (productKey) => {
      setModalConfirm({ visible: true, id: productKey });
    };
    const closeConfirm = () => {
      setModalConfirm({ visible: false, id: null });
    };
  const [productos, setProductos] = useState([]);
  const [imagenes, setImagenes] = useState({});
  const [variantes, setVariantes] = useState({});
  const [categories, setCategories] = useState([]);
  const [editando, setEditando] = useState({});
  const [modalConfirm, setModalConfirm] = useState({ visible: false, id: null });
  const [loading, setLoading] = useState(false);
  const [search, setSearch] = useState("");
  const [categoryFilter, setCategoryFilter] = useState("");
  const [sortOrder, setSortOrder] = useState("alphabetical");

  const getProductKey = (product) => product?.id ?? product?.user_id ?? null;

  const clearFilters = () => {
    setSearch("");
    setCategoryFilter("");
    setSortOrder("alphabetical");
  };

  const parseDecimalInput = (value, fallback = null) => {
    if (value === undefined || value === null || value === "") return fallback;
    if (typeof value === "number") return Number.isFinite(value) ? value : fallback;
    const normalized = String(value).replace(/\s/g, "").replace(",", ".");
    const parsed = Number(normalized);
    return Number.isFinite(parsed) ? parsed : fallback;
  };

  const handleConfirmSave = async () => {
    const prodId = modalConfirm.id;
    if (!prodId) return;

    setLoading(true);

    try {
      const cambios = editando[prodId] || {};
      const productoActual = productos.find((p) => getProductKey(p) === prodId);
      const precioNormalizado = parseDecimalInput(
        cambios.precio,
        parseDecimalInput(productoActual?.precio, 0)
      );
      const precioCompraNormalizado = cambios.precio_compra === undefined
        ? parseDecimalInput(productoActual?.precio_compra, 0)
        : parseDecimalInput(cambios.precio_compra, null);
      if (precioCompraNormalizado === null || precioCompraNormalizado < 0) {
        throw new Error('Ingresa un precio de compra valido, mayor o igual a cero.');
      }

      // Variantes e imágenes editadas
      const nuevasVariantes = cambios.variantes !== undefined ? cambios.variantes : variantes[prodId] || [];
      let nuevasImagenes = cambios.imagenes !== undefined ? cambios.imagenes : imagenes[prodId] || [];

      const archivosNuevos = nuevasImagenes.filter((image) => image instanceof File);
      if (archivosNuevos.length > 0) {
        const imagenesSubidas = await uploadProductImages(archivosNuevos);
        let uploadedIndex = 0;
        nuevasImagenes = nuevasImagenes.map((image) =>
          image instanceof File ? imagenesSubidas[uploadedIndex++] : image
        );
      }

      const erroresApi = validarProducto({
        nombre: cambios.nombre ?? productoActual?.nombre,
        descripcion: cambios.descripcion ?? productoActual?.descripcion,
        variantes: nuevasVariantes,
        imagenes: nuevasImagenes,
      }).filter((error) => !String(error || "").toLowerCase().includes("imagen"));

      if (erroresApi.length > 0) {
        showToast(erroresApi.join("\n"), "error");
        setLoading(false);
        return;
      }

      const { data: sessionData } = await supabase.auth.getSession();
      const token = sessionData?.session?.access_token;
      const response = await fetch("/api/admin/productos/editar", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          ...(token ? { Authorization: `Bearer ${token}` } : {}),
        },
        body: JSON.stringify({
          productId: productoActual?.user_id ?? prodId,
          activeSucursalId,
          cambios: {
            ...cambios,
            precio: precioNormalizado,
            precio_compra: precioCompraNormalizado,
          },
          variantes: nuevasVariantes,
          imagenes: nuevasImagenes,
        }),
      });
      const result = await response.json();
      if (!response.ok || !result.success) {
        throw new Error(result.error || "No se pudo guardar el producto");
      }

      showToast("Producto actualizado con exito!");

      if (typeof window !== "undefined") {
        setTimeout(() => {
          window.location.reload();
        }, 900);
      }

      setEditando((prev) => ({ ...prev, [prodId]: undefined }));
      setLoading(false);
      closeConfirm();
      return;

      const errores = validarProducto({
        nombre: cambios.nombre ?? productoActual?.nombre,
        descripcion: cambios.descripcion ?? productoActual?.descripcion,
        variantes: nuevasVariantes,
        imagenes: nuevasImagenes,
      });

      if (errores.length > 0) {
        showToast(errores.join("\n"), "error");
        setLoading(false);
        return;
      }


      // 1. Actualizar producto (campos básicos, stock e imagen principal)
      const stockTotal = nuevasVariantes.reduce((acc, v) => acc + (parseInt(v.stock, 10) || 0), 0);
      // Determinar la imagen principal (primera del array de imágenes)
      let imagenPrincipal = null;
      if (nuevasImagenes.length > 0) {
        const img = nuevasImagenes[0];
        imagenPrincipal = img.imagen_url || img;
      }
      const updatePayload = {
        nombre: cambios.nombre ?? productoActual?.nombre,
        descripcion: cambios.descripcion ?? productoActual?.descripcion,
        precio: precioNormalizado,
        vista_producto: normalizeProductView(cambios.vista_producto ?? productoActual?.vista_producto),
        category_id: cambios.category_id
          ? parseInt(cambios.category_id, 10)
          : productoActual?.category_id ?? null,
        codigo_barra: cambios.codigo_barra ?? productoActual?.codigo_barra,
        stock: stockTotal,
        imagen_url: imagenPrincipal || productoActual?.imagen_url || '/sin-imagen.png',
      };

      let updateQuery = supabase.from("productos").update(updatePayload);
      if (productoActual?.user_id !== undefined && productoActual?.user_id !== null) {
        updateQuery = updateQuery.eq("user_id", productoActual.user_id);
      } else {
        updateQuery = updateQuery.eq("id", prodId);
      }
      if (activeSucursalId) updateQuery = updateQuery.eq("sucursal_id", activeSucursalId);
      const { error: updateError } = await updateQuery;
      if (updateError) throw updateError;

      // 2. Sincronizar variantes
      // Obtener variantes actuales en BD
      const { data: variantesBD } = await supabase
        .from("producto_variantes")
        .select("id, producto_id, color, talla, stock, sku, precio, imagen_url, activo").eq("producto_id", productoActual.user_id);
      // Eliminar variantes quitadas
      for (const vBD of variantesBD || []) {
        if (!nuevasVariantes.some(v => v.id === vBD.id)) {
          await supabase.from("producto_variantes").delete().eq("id", vBD.id);
        }
      }
      // Insertar o actualizar variantes
      for (const v of nuevasVariantes) {
        if (v.id) {
          // Actualizar
          await supabase.from("producto_variantes").update({
            color: v.color,
            talla: v.talla,
            stock: Math.max(0, Math.floor(Number(v.stock) || 0)),
            stock_decimal: Number(v.stock) || 0,
            sku: v.sku,
            precio: parseDecimalInput(v.precio, null),
            imagen_url: v.imagen_url,
            activo: v.activo !== undefined ? v.activo : true,
          }).eq("id", v.id);
        } else {
          // Insertar
          await supabase.from("producto_variantes").insert({
            producto_id: productoActual.user_id,
            sucursal_id: activeSucursalId || null,
            color: v.color,
            talla: v.talla,
            stock: Math.max(0, Math.floor(Number(v.stock) || 0)),
            stock_decimal: Number(v.stock) || 0,
            stock_inicial_decimal: Number(v.stock) || 0,
            sku: v.sku,
            precio: parseDecimalInput(v.precio, null),
            imagen_url: v.imagen_url,
            activo: v.activo !== undefined ? v.activo : true,
          });
        }
      }

      // 3. Sincronizar imágenes
      // Obtener imágenes actuales en BD
      const { data: imagenesBD } = await supabase
        .from("producto_imagenes")
        .select("id, producto_id, imagen_url").eq("producto_id", productoActual.user_id);
      // Eliminar imágenes quitadas
      for (const imgBD of imagenesBD || []) {
        if (!nuevasImagenes.some(img => img.id === imgBD.id || img.imagen_url === imgBD.imagen_url)) {
          await supabase.from("producto_imagenes").delete().eq("id", imgBD.id);
        }
      }
      // Insertar nuevas imágenes
      for (const img of nuevasImagenes) {
        if (!img.id) {
          await supabase.from("producto_imagenes").insert({
            producto_id: productoActual.user_id,
            sucursal_id: activeSucursalId || null,
            imagen_url: img.imagen_url || img,
          });
        }
      }

      showToast("Producto actualizado con éxito!");

      if (typeof window !== "undefined") {
        setTimeout(() => {
          window.location.reload();
        }, 900);
      }

      setEditando((prev) => ({ ...prev, [prodId]: undefined }));
    } catch (err) {
      const msg = err?.message || "Error guardando producto";
      showToast("Error guardando producto: " + msg, "error");
      console.error("Error guardando producto:", err);
    }

    setLoading(false);
    closeConfirm();
  };

  const filteredAndSortedProducts = () => {
    let list = [...productos];

    const normalizedSearch = String(search || "").trim().toLowerCase();
    if (normalizedSearch) {
      list = list.filter((p) => {
        const productKey = getProductKey(p);
        const productVariants = editando[productKey]?.variantes ?? variantes[productKey] ?? [];
        return productMatchesSearch({ ...p, variantes: productVariants }, normalizedSearch);
      });
    }

    if (categoryFilter) {
      const selectedCategory = String(categoryFilter);
      list = list.filter((p) => String(p?.category_id ?? "") === selectedCategory);
    }

    if (sortOrder === "alphabetical") {
      list = list.sort((a, b) => String(a?.nombre || "").localeCompare(String(b?.nombre || "")));
    } else {
      list = list.sort(
        (a, b) => new Date(b?.created_at || 0) - new Date(a?.created_at || 0)
      );
    }
    return list;
  };

  const selectedProduct = productos.find(
    (p) => getProductKey(p) === modalConfirm.id
  );

  return (
    <div className="p-6 max-w-screen-xl mx-auto bg-slate-50 min-h-screen">
      <h1 className="text-4xl text-center font-bold text-indigo-700 mb-8">
        Editar Artículos
      </h1>

      {/* Filtros */}
      <div className="bg-white border border-slate-200 shadow-sm rounded-xl p-4 md:p-5 mb-8 space-y-4">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-3 items-center">
          <Input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Buscar por nombre, color, código o categoría"
            className="w-full"
          />

          <select
            value={categoryFilter}
            onChange={(e) => setCategoryFilter(e.target.value)}
            className="w-full border-slate-300 rounded-lg p-3 bg-white"
          >
            <option value="">Todas las categorías</option>
            {categories.map((cat) => (
              <option key={cat.id} value={cat.id}>
                {cat.categori}
              </option>
            ))}
          </select>

          <select
            value={sortOrder}
            onChange={(e) => setSortOrder(e.target.value)}
            className="w-full border-slate-300 rounded-lg p-3 bg-white"
          >
            <option value="alphabetical">Orden alfabético</option>
            <option value="date">Más recientes primero</option>
          </select>

          <button
            type="button"
            onClick={clearFilters}
            className="w-full px-4 py-3 rounded-lg border border-slate-300 bg-white text-slate-700 hover:bg-slate-100 transition"
          >
            Limpiar filtros
          </button>
        </div>

        <div className="flex items-center justify-start">
          <div className="text-sm text-slate-600">
            Mostrando <span className="font-semibold text-slate-900">{filteredAndSortedProducts().length}</span> de <span className="font-semibold text-slate-900">{productos.length}</span> productos
          </div>
        </div>
      </div>

      {loading && (
        <div className="text-center text-gray-600 mb-4">Cargando...</div>
      )}

      {/* LISTA DE PRODUCTOS */}
      <div className="space-y-8">
        {filteredAndSortedProducts().map((prod) => {
          const productKey = getProductKey(prod);
          return (
          <ProductCard
            key={productKey}
            prod={prod}
            categories={categories}
            editData={{
              originalImages: imagenes[productKey],
              originalVariants: variantes[productKey] || [],
              ...editando[productKey],
            }}
            setEditDataField={setEditDataField}
            onAddVariantRow={handleAddVariantRow}
            onVariantFieldChange={handleVariantFieldChange}
            onRemoveVariantRow={handleRemoveVariantRow}
            handleAddImages={handleAddImages}
            handleRemoveImage={handleRemoveImage}
            handleReplaceImage={handleReplaceImage}
            handleReorderImages={handleReorderImages}
            openConfirm={openConfirm}
          />
        )})}
      </div>

      {/* MODAL CONFIRM */}
      <ConfirmModal
        visible={modalConfirm.visible}
        onCancel={closeConfirm}
        onConfirm={handleConfirmSave}
        title="Guardar cambios del producto"
        message="Se detectaron cambios pendientes en este producto."
        detail={selectedProduct ? ("Producto: " + selectedProduct.nombre) : "Verifica la informacion antes de confirmar."}
        confirmLabel="Si, guardar"
        cancelLabel="Volver"
      />

      <Toast />
    </div>
  );
}

