    'Marron',
    'Marron Claro',
    'Marron Oscuro',
    'Cafe',
    'Cafe Claro',
    'Cafe Oscuro',
    'Natural',
    'Nude',
    'Camel',
    'Taupe',

    // Rojos y derivados
    'Rojo',
    'Rojo Claro',
    'Rojo Oscuro',
    'Bordo',
    'Guindo',
    'Vino',
    'Marron Rojizo',
    'Oxido',

    // Rosados y fucsia
    'Rosado',
    'Rosado Claro',
    'Rosado Oscuro',
    'Fucsia',
    'Magenta',
    'Palo de Rosa',
    'Salmón',
    'Durazno',

    // Corales y naranjas
    'Coral',
    'Coral Claro',
    'Naranja',
    'Naranja Claro',
    'Naranja Oscuro',
    'Mandarina',

    // Amarillos
    'Amarillo',
    'Amarillo Claro',
    'Amarillo Oscuro',
    'Mostaza',
    'Oro',
    'Dorado',
    'Lima',

    // Verdes
    'Verde',
    'Verde Claro',
    'Verde Oscuro',
    'Verde Militar',
    'Oliva',
    'Kaki',
    'Salvia',
    'Menta',
    'Verde Agua',
    'Pistacho',
    'Esmeralda',

    // Azules
    'Azul',
    'Azul Claro',
    'Azul Oscuro',
    'Navy',
    'Real',
    'Celeste',
    'Cielo',
    'Turquesa',
    'Teal',
    'Petroleo',
    'Acero Azulado',

    // Morados y violetas
    'Morado',
    'Morado Claro',
    'Morado Oscuro',
    'Violeta',
    'Lila',
    'Lavanda',
    'Berenjena',
    'Purpura',
    'Ciruela',

    // Metalizados
    'Plateado',
    'Plata',
    'Gris Metalizad',
    'Plomo Metalizad',

    // Tonos especiales
    'Transparente',
    'Traslucido',
    'Plateado Brillante',
    'Dorado Brillante',
    'Coppel',
    'Bronce',
    'Cobre',

    // Combinaciones clasicas
    'Blanco con Negro',
    'Blanco con Dorado',
    'Blanco con Plateado',
    'Blanco con Rojo',
    'Blanco con Azul',
    'Blanco con Verde',
    'Negro con Dorado',
    'Negro con Plateado',
    'Negro con Rojo',
