                                                            <rect x="6" y="13" width="12" height="7" rx="1" />
                                                            <path d="M6 14H4a2 2 0 0 1-2-2v-1a4 4 0 0 1 4-4h12a4 4 0 0 1 4 4v1a2 2 0 0 1-2 2h-2" />
