"use client";
import { useEffect, useState } from "react";
import { supabase } from "../../../../lib/SupabaseClient";
import dynamic from "next/dynamic";
import { useSucursalActiva } from "../../../../components/admin/SucursalContext";

const Pie = dynamic(() => import("react-chartjs-2").then(mod => mod.Pie), { ssr: false });
const Line = dynamic(() => import("react-chartjs-2").then(mod => mod.Line), { ssr: false });
const Bar = dynamic(() => import("react-chartjs-2").then(mod => mod.Bar), { ssr: false });
import { Chart as ChartJS, ArcElement, Tooltip, Legend, CategoryScale, LinearScale, PointElement, LineElement, BarElement } from "chart.js";
ChartJS.register(ArcElement, Tooltip, Legend, CategoryScale, LinearScale, PointElement, LineElement, BarElement);

export default function VentasEstadisticaPage() {
  const { activeSucursalId } = useSucursalActiva();
  const [ventas, setVentas] = useState([]);
  const [detalles, setDetalles] = useState([]);
  const [reportLines, setReportLines] = useState([]);
  const [openRow, setOpenRow] = useState(null);

  useEffect(() => {
    async function fetchVentas() {

      let ventasQuery = supabase
        .from("ventas")
        .select("id, total, fecha, costos_extra, descuentos, cliente_nombre, modo_pago");
      if (activeSucursalId) ventasQuery = ventasQuery.eq("sucursal_id", activeSucursalId);
      const { data, error } = await ventasQuery;
      if (!error && data) setVentas(data);

      let detallesQuery = supabase
        .from("ventas_detalle")
        .select("venta_id, producto_id, cantidad, precio_unitario, costo_unitario");
      if (activeSucursalId) detallesQuery = detallesQuery.eq("sucursal_id", activeSucursalId);
      const { data: dets } = await detallesQuery;
      if (dets) {
        setDetalles(dets);
      }
    }
    fetchVentas();
  }, [activeSucursalId]);


  useEffect(() => {
    if (ventas.length === 0) return;

    // Agrupar detalles por venta para acceso O(1)
    const detallesPorVenta = {};
    detalles.forEach(d => {
      const key = Number(d.venta_id);
      if (!detallesPorVenta[key]) detallesPorVenta[key] = [];
      detallesPorVenta[key].push(d);
    });

    const lines = ventas.map(v => {
      const detsThis = detallesPorVenta[Number(v.id)] || [];
      const inversion = detsThis.reduce((acc, d) =>
        acc + ((Number(d.costo_unitario) || 0) * Number(d.cantidad || 0)), 0
      );
      const ventaPrice = Number(v.total) || 0;

      // Manejo robusto de costos_extra
      let costosExtras = v.costos_extra || {};
      if (typeof costosExtras === "string") {
        try { costosExtras = JSON.parse(costosExtras); } catch { costosExtras = {}; }
      }

      const descuentos = Number(v.descuentos || 0);
      const costos = Number(costosExtras.impuestos) || 0;
      const gananciaBruta = ventaPrice - inversion;
      const gananciaNeta = gananciaBruta - costos;
      const porcentajeUtilidad = inversion > 0 ? (gananciaNeta / inversion * 100) : 0;
      const items = detsThis.map(d => {
        const cantidad = Number(d.cantidad) || 0;
        const precio = Number(d.precio_unitario) || 0;
        const costo = (Number(d.costo_unitario) || 0) * cantidad;
        const ingreso = precio * cantidad;
        return {
          producto_id: d.producto_id,
          cantidad,
          precio,
          costo,
          ingreso,
          ganancia: ingreso - costo,
        };
      });
      return { venta: v, inversion, ventaPrice, descuentos, costos, gananciaBruta, gananciaNeta, porcentajeUtilidad, items };
    });
    setReportLines(lines);
  }, [ventas, detalles]);

  // Diagnóstico rápido
  const totalVentas = ventas.length;
  const montoTotal = ventas.reduce((acc, v) => acc + Number(v.total), 0);
  const ticketPromedio = totalVentas > 0 ? montoTotal / totalVentas : 0;
  const ventasPerdida = reportLines.filter(r => r.gananciaNeta < 0).length;
  const margenPromedio = reportLines.reduce((a, r) => a + r.porcentajeUtilidad, 0) / (reportLines.length || 1);
  const alertas = reportLines.filter(r => r.gananciaNeta < 0);

  const sortedLines = [...reportLines].sort((a,b)=> new Date(a.venta.fecha) - new Date(b.venta.fecha));
  const fechasLines = sortedLines.map(r=> new Date(r.venta.fecha).toLocaleDateString());
  const gananciaNetaData = sortedLines.map(r=> r.gananciaNeta.toFixed(2));
  const utilidadPctData = sortedLines.map(r=> r.porcentajeUtilidad.toFixed(2));
  const gananciaLineChart = {
    labels: fechasLines,
    datasets: [{ label: 'Ganancia neta', data: gananciaNetaData, borderColor: '#10B981', backgroundColor: 'rgba(16,185,129,0.1)' }]
  };
  const utilidadBarChart = {
    labels: fechasLines,
    datasets: [{ label: '% Utilidad', data: utilidadPctData, backgroundColor: '#3B82F6' }]
  };

  const ventasPorDia = {};
  ventas.forEach(v => {
    const fecha = new Date(v.fecha).toLocaleDateString();
    ventasPorDia[fecha] = (ventasPorDia[fecha] || 0) + 1;
  });

  const productosVendidos = {};
  detalles.forEach(d => {
    productosVendidos[d.producto_id] = (productosVendidos[d.producto_id] || 0) + d.cantidad;
  });
  const masVendidoId = Object.keys(productosVendidos).reduce((a, b) => productosVendidos[a] > productosVendidos[b] ? a : b, null);

  const rentabilidadProductos = {};
  detalles.forEach(d => {
    const ganancia = ((Number(d.precio_unitario) || 0) - (Number(d.costo_unitario) || 0)) * (Number(d.cantidad) || 0);
    rentabilidadProductos[d.producto_id] = (rentabilidadProductos[d.producto_id] || 0) + ganancia;
  });
  const topRentables = Object.entries(rentabilidadProductos)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 5);

  const clientes = {};
  ventas.forEach(v => {
    const key = v.cliente_nombre || "Sin nombre";
    clientes[key] = (clientes[key] || 0) + Number(v.total || 0);
  });
  const topClientes = Object.entries(clientes)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 5);

  const pieDataDia = {
    labels: Object.keys(ventasPorDia),
    datasets: [{
      data: Object.values(ventasPorDia),
      backgroundColor: ["#60a5fa", "#fbbf24", "#f87171", "#a78bfa", "#f472b6", "#34d399", "#facc15", "#818cf8", "#fca5a5"],
    }],
  };

  const pieDataProducto = {
    labels: Object.keys(productosVendidos).map(id => `#${id}`),
    datasets: [{
      data: Object.values(productosVendidos),
      backgroundColor: ["#4ade80", "#60a5fa", "#fbbf24", "#f87171", "#a78bfa", "#f472b6", "#34d399", "#facc15", "#818cf8", "#fca5a5"],
    }],
  };


  // =========================
  // 🧠 INTELIGENCIA AVANZADA
  // =========================

  // 💰 ingreso neto real
  const ingresoNeto = reportLines.reduce((a, r) => a + r.gananciaNeta, 0);

  // 📊 dependencia (riesgo)
  const metodoConteo = {};
  ventas.forEach(v => {
    const m = v.modo_pago || "otros";
    metodoConteo[m] = (metodoConteo[m] || 0) + Number(v.total || 0);
  });

  let metodoTop = null;
  let metodoTopValor = 0;
  Object.entries(metodoConteo).forEach(([k, v]) => {
    if (v > metodoTopValor) {
      metodoTop = k;
      metodoTopValor = v;
    }
  });
  const dependencia = metodoTopValor / (montoTotal || 1);

  // 📉 volatilidad
  const valores = sortedLines.map(r => r.gananciaNeta);
  const promedio = ingresoNeto / (valores.length || 1);
  const varianza = valores.reduce((acc, v) => acc + Math.pow(v - promedio, 2), 0) / (valores.length || 1);
  const volatilidad = Math.sqrt(varianza);

  // 📅 días sin ventas
  const diasSinVentas = Object.values(ventasPorDia).filter(v => v === 0).length;

  // 🔮 predicción simple
  const ultimos7 = valores.slice(-7);
  const prediccion = ultimos7.reduce((a,b)=>a+b,0) / (ultimos7.length || 1);

  // 🧠 score de negocio
  let score = 0;
  if (margenPromedio > 20) score += 25;
  if (ventasPerdida === 0) score += 25;
  if (dependencia < 0.6) score += 25;
  if (volatilidad < promedio * 0.5) score += 25;
  let estado = "Crítico";
  if (score > 75) estado = "Saludable";
  else if (score > 50) estado = "Estable";

  // =========================
  // 💡 INSIGHTS AUTOMÁTICOS
  // =========================
  const insights = [];
  if (ventasPerdida > 0) {
    insights.push(`Tienes ${ventasPerdida} ventas con pérdida.`);
  }
  if (dependencia > 0.7) {
    insights.push(`Dependes mucho de ${metodoTop}.`);
  }
  if (margenPromedio < 15) {
    insights.push("Margen bajo, revisa costos o precios.");
  }
  if (volatilidad > promedio * 0.7) {
    insights.push("Ingresos inestables.");
  }
  if (ticketPromedio < 50) {
    insights.push("Ticket promedio bajo (estrategia de volumen).");
  }

  // =========================
  // ⚠️ ALERTAS
  // =========================
  const alertasPro = [];
  if (ventasPerdida > 0) {
    alertasPro.push("Ventas con pérdida detectadas");
  }
  if (dependencia > 0.75) {
    alertasPro.push("Riesgo: dependencia de un solo método");
  }
  if (volatilidad > promedio) {
    alertasPro.push("Ingresos altamente variables");
  }

  return (
    <div className="p-4 bg-gray-100 min-h-screen">
      {/* 🧠 SCORE + SALUD */}
      <div className={`mb-6 p-4 rounded-xl shadow font-bold ${
        score > 75 ? "bg-green-100 text-green-700" :
        score > 50 ? "bg-yellow-100 text-yellow-700" :
        "bg-red-100 text-red-700"
      }`}>
        🧠 Score del negocio: {score}/100 — {estado}
      </div>
      <h1 className="text-2xl font-extrabold text-gray-900 mb-4">Estadísticas de Ventas</h1>


      {alertas.length > 0 && (
        <div className="mb-4 rounded-xl bg-red-100 p-4 font-semibold text-red-700 shadow-sm">
          ⚠️ {alertas.length} ventas con pérdida detectadas
        </div>
      )}

      {/* 💰 KPIs AVANZADOS */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
        <div className="bg-white p-4 rounded-xl shadow">
          <div className="text-gray-500 text-sm">Ingreso neto real</div>
          <div className="text-xl font-bold text-green-600">Bs {ingresoNeto.toFixed(2)}</div>
        </div>
        <div className="bg-white p-4 rounded-xl shadow">
          <div className="text-gray-500 text-sm">Dependencia</div>
          <div className="text-xl font-bold">{(dependencia * 100).toFixed(1)}%</div>
        </div>
        <div className="bg-white p-4 rounded-xl shadow">
          <div className="text-gray-500 text-sm">Volatilidad</div>
          <div className="text-xl font-bold text-purple-600">{volatilidad.toFixed(2)}</div>
        </div>
        <div className="bg-white p-4 rounded-xl shadow">
          <div className="text-gray-500 text-sm">Predicción próxima</div>
          <div className="text-xl font-bold text-blue-600">Bs {prediccion.toFixed(2)}</div>
        </div>
      </div>

      {/* 💡 INSIGHTS AUTOMÁTICOS */}
      {insights.length > 0 && (
        <div className="mb-6 bg-yellow-50 p-4 rounded-xl shadow">
          <h3 className="font-bold mb-2">💡 Insights inteligentes</h3>
          <ul className="list-disc list-inside text-sm">
            {insights.map((i, idx) => (
              <li key={idx}>{i}</li>
            ))}
          </ul>
        </div>
      )}

      {/* ⚠️ ALERTAS PRO */}
      {alertasPro.length > 0 && (
        <div className="mb-6 bg-red-50 p-4 rounded-xl shadow">
          <h3 className="font-bold text-red-700 mb-2">⚠️ Alertas críticas</h3>
          <ul className="list-disc list-inside text-sm text-red-600">
            {alertasPro.map((a, idx) => (
              <li key={idx}>{a}</li>
            ))}
          </ul>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
        <div className="bg-white rounded-xl shadow p-6 flex flex-col gap-2">
          <span className="text-gray-900 font-bold">Total de ventas: <span className="font-extrabold">{totalVentas}</span></span>
          <span className="text-gray-900 font-bold">Monto total vendido: <span className="font-extrabold">Bs {montoTotal.toFixed(2)}</span></span>
          <span className="text-gray-900 font-bold">Ticket promedio: <span className="font-extrabold">Bs {ticketPromedio.toFixed(2)}</span></span>
          <span className="text-gray-900 font-bold">⚠️ Ventas con pérdida: <span className="font-extrabold text-red-600">{ventasPerdida}</span></span>
          <span className="text-gray-900 font-bold">📉 Margen promedio: <span className="font-extrabold">{margenPromedio.toFixed(2)}%</span></span>
          {masVendidoId && (
            <span className="text-gray-900 font-bold">Producto más vendido: <span className="font-extrabold">#{masVendidoId}</span> ({productosVendidos[masVendidoId]} unidades)</span>
          )}
        </div>
        <div className="bg-white rounded-xl shadow p-6 flex flex-col items-center">
          <span className="text-gray-900 font-bold mb-2 block">Ventas por día</span>
          {Object.keys(ventasPorDia).length > 0 && <Pie data={pieDataDia} />}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="bg-white rounded-xl shadow p-6 flex flex-col items-center">
          <span className="text-gray-900 font-bold mb-2 block">Ventas por producto</span>
          {Object.keys(productosVendidos).length > 0 && <Pie data={pieDataProducto} />}
        </div>
        <div className="bg-white rounded-xl shadow p-6">
          <span className="text-gray-900 font-bold mb-4 block">Top productos más rentables</span>
          <div className="space-y-2">
            {topRentables.length === 0 ? (
              <p className="text-sm text-gray-500">Sin datos de rentabilidad.</p>
            ) : topRentables.map(([productoId, ganancia]) => (
              <div key={productoId} className="flex items-center justify-between border-b py-2 text-sm">
                <span className="font-medium text-gray-800">Producto #{productoId}</span>
                <span className={Number(ganancia) >= 0 ? "font-bold text-green-600" : "font-bold text-red-600"}>
                  Bs {Number(ganancia).toFixed(2)}
                </span>
              </div>
            ))}
          </div>
          {/* 🏆 TOP INTELIGENTE */}
          <div className="mt-6 bg-white rounded-xl shadow p-6">
            <h3 className="font-bold mb-2">🏆 Producto más rentable</h3>
            {topRentables.length > 0 && (
              <div className="text-lg font-bold text-green-600">
                Producto #{topRentables[0][0]} → Bs {Number(topRentables[0][1]).toFixed(2)}
              </div>
            )}
          </div>
        </div>
      </div>

      <div className="mt-8 grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="bg-white rounded-xl shadow p-6">
          <span className="text-gray-900 font-bold mb-4 block">Top clientes</span>
          <div className="space-y-2">
            {topClientes.length === 0 ? (
              <p className="text-sm text-gray-500">Sin clientes registrados.</p>
            ) : topClientes.map(([cliente, total]) => (
              <div key={cliente} className="flex items-center justify-between border-b py-2 text-sm">
                <span className="font-medium text-gray-800">{cliente}</span>
                <span className="font-bold text-cyan-700">Bs {Number(total).toFixed(2)}</span>
              </div>
            ))}
          </div>
        </div>
      </div>

      {reportLines.length > 0 && (
        <div className="mt-8 grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="bg-white rounded-xl shadow p-6">
            <span className="text-gray-900 font-bold mb-2 block">Ganancia Neta por Fecha</span>
            <Line data={gananciaLineChart} />
          </div>
          <div className="bg-white rounded-xl shadow p-6">
            <span className="text-gray-900 font-bold mb-2 block">% de Utilidad por Fecha</span>
            <Bar data={utilidadBarChart} />
          </div>
        </div>
      )}

      {reportLines.length > 0 && (
        <div className="mt-10 bg-white rounded-xl shadow p-6">
          <h2 className="text-xl font-bold mb-4">Detalle contable por venta</h2>
          <div className="overflow-x-auto">
            <table className="w-full text-left text-sm">
              <thead className="bg-gray-100">
                <tr>
                  <th className="px-4 py-2">#Venta</th>
                  <th className="px-4 py-2">Fecha</th>
                  <th className="px-4 py-2">Inversión</th>
                  <th className="px-4 py-2">Precio venta</th>
                  <th className="px-4 py-2">Costos</th>
                  <th className="px-4 py-2">Ganancia bruta</th>
                  <th className="px-4 py-2">Ganancia neta</th>
                  <th className="px-4 py-2">% utilidad</th>
                </tr>
              </thead>
              {reportLines.map((r, idx) => (
                  <tbody key={`row-group-${r.venta.id}-${idx}`}>
                    <tr
                      className="border-t cursor-pointer hover:bg-gray-50"
                      onClick={() => setOpenRow(openRow === r.venta.id ? null : r.venta.id)}
                    >
                      <td className="px-4 py-2">{r.venta.id}</td>
                      <td className="px-4 py-2">{new Date(r.venta.fecha).toLocaleDateString()}</td>
                      <td className="px-4 py-2">Bs {r.inversion.toFixed(2)}</td>
                      <td className="px-4 py-2">Bs {r.ventaPrice.toFixed(2)}</td>
                      <td className="px-4 py-2">Bs {r.costos.toFixed(2)}</td>
                      <td className="px-4 py-2">Bs {r.gananciaBruta.toFixed(2)}</td>
                      <td className={
                        `px-4 py-2 ${
                          r.gananciaNeta > 0 ? "text-green-600" :
                          r.gananciaNeta < 0 ? "text-red-600" :
                          "text-gray-600"
                        }`
                      }>Bs {r.gananciaNeta.toFixed(2)}</td>
                      <td className="px-4 py-2">{r.porcentajeUtilidad.toFixed(2)}%</td>
                    </tr>

                    {openRow === r.venta.id && (
                      <tr key={`detail-${r.venta.id}`}>
                        <td colSpan="100%" className="px-4 py-3">
                          <div className="rounded-xl bg-slate-50 p-4">
                            <h3 className="mb-2 font-bold">Productos vendidos</h3>
                            {r.items.map((i, itemIdx) => (
                              <div key={itemIdx} className="flex justify-between border-b py-1 text-sm last:border-b-0">
                                <span>Producto #{i.producto_id} x{i.cantidad}</span>
                                <span className={i.ganancia >= 0 ? "text-green-600" : "text-red-600"}>
                                  Bs {i.ganancia.toFixed(2)}
                                </span>
                              </div>
                            ))}
                          </div>
                        </td>
                      </tr>
                    )}
                  </tbody>
                ))}
            </table>
        </div>
        </div>
      )}

      {/* Resumen general */}
      {reportLines.length > 0 && (() => {
        const inversionTotal = reportLines.reduce((a,b)=>a+b.inversion,0);
        const ventasTot = reportLines.length;
        const gananciaTotal = reportLines.reduce((a,b)=>a+b.gananciaNeta,0);
        const margen = inversionTotal > 0 ? (gananciaTotal / inversionTotal * 100) : 0;
        return (
          <div className="mt-8 bg-white rounded-xl shadow p-6">
            <h2 className="text-xl font-bold mb-4">Resumen financiero</h2>
            <p>Inversión total: Bs {inversionTotal.toFixed(2)}</p>
            <p>Ventas totales: {ventasTot}</p>
            <p>Ganancia total neta: Bs {gananciaTotal.toFixed(2)}</p>
            <p>Margen de utilidad general: {margen.toFixed(2)}%</p>
            <div className="mt-4">
              <h3 className="font-semibold">Recomendaciones</h3>
              <ul className="list-disc list-inside">
                <li>Revisar costos de envío y comisiones para reducir gastos.</li>
                <li>Optimizar el precio de compra y stock para mejorar margen.</li>
                <li>Considerar promociones controladas para no disminuir demasiado la utilidad.</li>
              </ul>
            </div>
          </div>
        );
      })()}
    </div>
  );
}

"use client";
import { calcularLineaVenta } from '../../../../lib/cartPricing';
import { restorePendingOrderPricing } from '../../../../lib/pendingOrderPricing.mjs';
import React, { useEffect, useRef, useCallback } from 'react';
import { useCarrito } from '../../../../hooks/useCarrito';
import { useCliente } from '../../../../hooks/useCliente';
import { useProductos } from '../../../../hooks/useProductos';
import { usePromociones } from '../../../../lib/usePromociones';
import { usePacks } from '../../../../lib/packs';
import ClienteForm from '../../../../components/venta/ClienteForm';
import BuscadorProductos from '../../../../components/venta/BuscadorProductos';
import { calcularDescuentoPack } from '../../../../lib/packs';
import CarritoPanel from '../../../../components/venta/CarritoPanel';
import dynamic from 'next/dynamic';
const TicketPrinter = dynamic(() => import('../../../../components/venta/TicketPrinter'), { ssr: false });
import type { TicketPrinterHandle } from '../../../../components/venta/TicketPrinter';
import { Pack, Producto } from '../../../../hooks/useCarrito';
import { supabase } from '../../../../lib/SupabaseClient';
import { showToast } from '../../../../components/ui/Toast';
import { useSucursalActiva } from '../../../../components/admin/SucursalContext';

type VariantMatch = {
  variante_id?: number | string;
  id?: number | string;
  color?: string;
  precio?: number;
  stock?: number;
  stock_decimal?: number;
  sku?: string;
  codigo_barra?: string;
};

type ProductoDB = {
  user_id: string | number;
  nombre?: string;
  precio?: number;
  precio_compra?: number;
  stock?: number;
  unidad_base?: string;
  unidades_alternativas?: string[];
  factor_conversion?: number;
  producto_variantes?: Array<{
    id?: string | number;
    color?: string;
    precio?: number;
    stock?: number;
    stock_decimal?: number;
  }>;
};

function getCarritoProductoId(item: Producto & { producto_id?: string | number | null }) {
  return item.user_id ?? item.producto_id ?? null;
}

type StockRequest = {
  nombre: string;
  color?: string | null;
  disponible: number;
  solicitado: number;
};

type PackDB = {
  id: string | number;
  nombre?: string;
  precio_pack?: number;
  pack_productos?: Array<{
    cantidad?: number;
    variante_id?: string | number | null;
    productos?: {
      user_id?: string | number;
      nombre?: string;
      precio?: number;
      stock?: number;
      producto_variantes?: Array<{
        id?: string | number;
        color?: string;
        precio?: number;
        stock?: number;
        stock_decimal?: number;
      }>;
    };
  }>;
};

function parseMoneyInput(value: string) {
  const normalized = String(value || '').replace(',', '.').trim();
  if (!normalized) return 0;
  const parsed = Number(normalized);
  return Number.isNaN(parsed) ? 0 : parsed;
}

function formatMoneyInput(value: number) {
  if (!value) return '';
  return String(value).replace('.', ',');
}

function parsePositiveNumber(value: string | number) {
  const parsed = parseMoneyInput(String(value ?? ''));
  return Number.isFinite(parsed) ? Math.max(0, parsed) : 0;
}

function normalizeQuantity(value: unknown) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? Math.max(0, parsed) : 0;
}

function getVariantStock(variant?: { stock?: number; stock_decimal?: number } | null) {
  const decimal = Number(variant?.stock_decimal);
  const legacy = Number(variant?.stock);
  const hasDecimal = variant?.stock_decimal !== null && variant?.stock_decimal !== undefined;
  return normalizeQuantity(hasDecimal && Number.isFinite(decimal) ? decimal : legacy || 0);
}

function getProductStock(product?: { stock?: number } | null) {
  return normalizeQuantity(product?.stock ?? 0);
}

function hasUnitConversion(product?: { unidades_alternativas?: string[]; factor_conversion?: number } | null) {
  return Boolean(
    Array.isArray(product?.unidades_alternativas) &&
    product.unidades_alternativas.length > 0 &&
    Number(product?.factor_conversion || 0) > 0
  );
}

function getStockForVariantSale(product: ProductoDB, variant?: { stock?: number; stock_decimal?: number } | null) {
  return variant ? getVariantStock(variant) : getProductStock(product);
}

function formatStockQuantity(value: number) {
  return Number(value.toFixed(3)).toString();
}

function getSaleBaseQuantity(
  item: {
    cantidad?: number;
    cantidad_base?: number;
    cantidad_display?: number;
    unidad?: string;
    unidad_base?: string;
    factor_conversion?: number;
  },
  product?: { unidad_base?: string; factor_conversion?: number } | null
) {
  const unidadBase = String(product?.unidad_base || item.unidad_base || item.unidad || 'unidad');
  const unidadVenta = String(item.unidad || unidadBase);
  const factor = Number(item.factor_conversion || product?.factor_conversion || 0);
  const visible = normalizeQuantity(item.cantidad_display ?? item.cantidad ?? item.cantidad_base ?? 1);
  if (unidadVenta !== unidadBase && Number.isFinite(factor) && factor > 0) {
    return visible / factor;
  }
  return normalizeQuantity(item.cantidad_base ?? item.cantidad ?? visible);
}

export default function NuevaVenta() {
  // hooks
  const { activePaisId, activeSucursal } = useSucursalActiva() as any;
  const effectiveSucursalId = activeSucursal?.id || "";
  const { cliente, cambiarCampo, buscarPorCarnet, guardar, buscarEmailHistorico } = useCliente(effectiveSucursalId, activePaisId);
  const { promociones, loading: loadingPromociones, error: errorPromociones } = usePromociones(effectiveSucursalId);
  const { packs } = usePacks(effectiveSucursalId) as { packs: Pack[] };
  const {
    productos, imagenes, searchResults, searchLoading, fetchProductos, searchProductos
  } = useProductos(false, effectiveSucursalId);
  const {
    carrito,
    agregar,
    quitar,
    cambiarCantidad,
    cambiarDescuento,
    cambiarUnidadYCantidad,
    subtotal,
    totalDescuento,
    total,
    setCarrito,
    stockWarning,
    clearStockWarning
  } = useCarrito(promociones, effectiveSucursalId, productos);

  const [busqueda, setBusqueda] = React.useState('');
  const [showSuggestions, setShowSuggestions] = React.useState(false);
  const [packResults, setPackResults] = React.useState<Pack[]>([]);
  const lastAutoAddRef = React.useRef({ code: '', timestamp: 0 });

  const scanBuffer = React.useRef('');
  const scanTimer = React.useRef<ReturnType<typeof setTimeout> | null>(null);
  const [scanFeedback, setScanFeedback] = React.useState(false);
  const beepRef = useRef<HTMLAudioElement | null>(null);

  const [efectivizando, setEfectivizando] = React.useState(false);

  // NUEVO: hasta 2 métodos de pago
  const [pagos, setPagos] = React.useState([
    { metodo: '', monto: 0 },
  ]);
  const [mostrarSegundoPago, setMostrarSegundoPago] = React.useState(false);

  // campos contables adicionales
  const [cobrarImpuestos, setCobrarImpuestos] = React.useState(false);
  const tasaImpuestos = 0.16;
  const [envio, setEnvio] = React.useState(0);
  const [comision, setComision] = React.useState(0);
  const [publicidad, setPublicidad] = React.useState(0);
  const [rebajas, setRebajas] = React.useState(0);
  const [showInsufficientPaymentWarning, setShowInsufficientPaymentWarning] = React.useState(false);

  const totalBaseOperacion = Math.max(0, Number(total) + Number(envio) + Number(comision) - Number(publicidad) - Number(rebajas));
  const impuestosCalculados = cobrarImpuestos ? Number((totalBaseOperacion * tasaImpuestos).toFixed(2)) : 0;
  const totalCobrar = Number((totalBaseOperacion + impuestosCalculados).toFixed(2));
  const sumaPagos = pagos.reduce((acc, p) => acc + Number(p.monto || 0), 0);
  const tienePagoEnEfectivo = pagos.some((p) => p.metodo === 'efectivo' && Number(p.monto || 0) > 0);
  const cambio = tienePagoEnEfectivo && sumaPagos > totalCobrar ? Number((sumaPagos - totalCobrar).toFixed(2)) : 0;
  const pagoInsuficiente = sumaPagos > 0 && (sumaPagos + 0.009) < totalCobrar;

  const printerRef = useRef<TicketPrinterHandle>(null);
  const efectivizarBtnRef = useRef<HTMLButtonElement>(null);
  const pendingPedidoIdRef = useRef<string | number | null>(null);
  const saleRequestKeyRef = useRef<string | null>(null);
  const saleInFlightRef = useRef(false);

  // Cargar carrito desde pedidos si existe
  // Dependencias fijas para evitar warning de React
  const packsKey = Array.isArray(packs) ? packs.map(p => p.id).join(',') : '';
  const productosKey = Array.isArray(productos) ? productos.map(p => p.user_id).join(',') : '';

  // Carga robusta: siempre consulta productos y packs desde la base de datos
  React.useEffect(() => {
    if (typeof window === 'undefined') return;
    if (!activePaisId || !effectiveSucursalId) return;
    const pedido = sessionStorage.getItem('pedido_a_efectivizar');
    if (!pedido) return;
    (async () => {
      try {
        const pedidoObj = JSON.parse(pedido);
        if ((pedidoObj.pais_id && String(pedidoObj.pais_id) !== String(activePaisId))
          || (pedidoObj.sucursal_id && String(pedidoObj.sucursal_id) !== String(effectiveSucursalId))) {
          showToast('Selecciona el país y la sucursal del pedido antes de efectivizarlo.', 'error');
          return;
        }
        pendingPedidoIdRef.current = pedidoObj?.id || null;
        if (!Array.isArray(pedidoObj.productos)) return;
        // Agrupar productos por producto_id, variante_id y color
        const grouped: { [key: string]: any } = {};
        for (const p of pedidoObj.productos) {
          // Sanitizar: si es pack y user_id es 'pack-<id>', usar solo pack_id numérico
          let producto_id = p.producto_id || p.user_id || '';
          if (p.pack_id && typeof producto_id === 'string' && producto_id.startsWith('pack-')) {
            producto_id = '';
          }
          const variante_id = p.variante_id || 'default';
          const color = p.color || '';
          const unidad = p.unidad || p.unidad_base || 'unidad';
          const key = `${producto_id}|${variante_id}|${color}|${p.pack_id || ''}|${unidad}`;
          const cantidadDisplay = normalizeQuantity(p.cantidad_display ?? p.cantidad ?? 1);
          const cantidadBase = normalizeQuantity(p.cantidad_base ?? p.cantidad ?? 1);
          if (!grouped[key]) {
            grouped[key] = { ...p };
            grouped[key].cantidad = cantidadDisplay;
            grouped[key].cantidad_display = cantidadDisplay;
            grouped[key].cantidad_base = cantidadBase;
          } else {
            grouped[key].cantidad += cantidadDisplay;
            grouped[key].cantidad_display = Number(grouped[key].cantidad_display || 0) + cantidadDisplay;
            grouped[key].cantidad_base = Number(grouped[key].cantidad_base || 0) + cantidadBase;
          }
        }
        const productosAgrupados = Object.values(grouped);

        // Separar productos y packs
        const productosIds = productosAgrupados.filter(p => !p.pack_id).map(p => p.producto_id || p.user_id).filter(Boolean);
        const packsIds = productosAgrupados.filter(p => p.pack_id).map(p => p.pack_id).filter(Boolean);

        // Consultar productos desde la base de datos, trayendo también la imagen principal
        let productosDB = [];
        let imagenesDB: { [key: string]: string[] } = {};
        let unidadesByProducto: Record<string, any> = {};
        if (productosIds.length > 0) {
          const supabaseClient = supabase;
          let productosQuery = supabaseClient
            .from('v_productos_catalogo')
            .select('*')
            .in('producto_id', productosIds);
          if (activePaisId) productosQuery = productosQuery.eq('pais_id', activePaisId);
          if (effectiveSucursalId) productosQuery = productosQuery.eq('sucursal_id', effectiveSucursalId);
          const { data: productosData, error: productosError } = await productosQuery;
          if (productosError) throw productosError;
          productosDB = Array.isArray(productosData) ? productosData : [];

          let unidadesQuery = supabaseClient
            .from('productos')
            .select('user_id, precio, precio_compra, stock, unidad_base, unidades_alternativas, factor_conversion')
            .in('user_id', productosIds);
          if (activePaisId) unidadesQuery = unidadesQuery.eq('pais_id', activePaisId);
          if (effectiveSucursalId) unidadesQuery = unidadesQuery.eq('sucursal_id', effectiveSucursalId);
          const { data: unidadesData, error: unidadesError } = await unidadesQuery;
          if (unidadesError) throw unidadesError;
          unidadesByProducto = Object.fromEntries((Array.isArray(unidadesData) ? unidadesData : []).map((row) => [String(row.user_id), row]));

          // Traer imágenes asociadas
          let imgsQuery = supabaseClient
            .from('producto_imagenes')
            .select('producto_id, imagen_url')
            .in('producto_id', productosIds);
          if (activePaisId) imgsQuery = imgsQuery.eq('pais_id', activePaisId);
          if (effectiveSucursalId) imgsQuery = imgsQuery.eq('sucursal_id', effectiveSucursalId);
          const { data: imgs } = await imgsQuery;
          if (Array.isArray(imgs)) {
            imgs.forEach(i => {
              if (!imagenesDB[i.producto_id]) imagenesDB[i.producto_id] = [];
              if (i.imagen_url) imagenesDB[i.producto_id].push(i.imagen_url);
            });
          }
        }

        // Consultar packs desde la base de datos
        let packsDB = [];
        if (packsIds.length > 0) {
          let packsQuery = supabase
            .from('packs')
            .select(`*, pack_productos ( cantidad, producto_id, variante_id, productos!pack_productos_producto_id_fkey ( user_id, nombre, precio, categoria, stock, producto_variantes ( id, color, precio, stock, stock_decimal, sku ) ) )`)
            .in('id', packsIds);
          if (activePaisId) packsQuery = packsQuery.eq('pais_id', activePaisId);
          if (effectiveSucursalId) packsQuery = packsQuery.eq('sucursal_id', effectiveSucursalId);
          const { data: packsData, error: packsError } = await packsQuery;
          if (packsError) throw packsError;
          packsDB = Array.isArray(packsData) ? packsData : [];
        }

        // Reconstruir carrito solo con productos/packs válidos
        const carritoReconstruido = productosAgrupados.map((p) => {
          if (p.pack_id) {
            const pack = packsDB.find((pk: { id: string | number }) => String(pk.id) === String(p.pack_id));
            if (!pack) return { ...p, error: 'Pack no encontrado en base de datos' };
            return {
              tipo: 'pack',
              pack_id: pack.id,
              pack_data: pack,
              nombre: pack.nombre || 'Pack especial',
              cantidad: normalizeQuantity(p.cantidad_base ?? p.cantidad ?? 1),
              cantidad_base: normalizeQuantity(p.cantidad_base ?? p.cantidad ?? 1),
              cantidad_display: normalizeQuantity(p.cantidad_display ?? p.cantidad ?? 1),
              precio: pack.precio_pack,
              precio_pack: pack.precio_pack,
              precio_individual: (pack.pack_productos ?? []).reduce((t: number, i: { productos: { precio: number }, cantidad: number }) => t + (i.productos.precio * i.cantidad), 0),
              descuento: ((pack.pack_productos ?? []).reduce((t: number, i: { productos: { precio: number }, cantidad: number }) => t + (i.productos.precio * i.cantidad), 0)) - pack.precio_pack,
              productos: pack.pack_productos ?? [],
              cart_key: `pack:${pack.id}`,
              imagen_url: pack.imagen_url || '/sin-imagen.png',
            };
          }
          // Producto normal
          const prodId = p.producto_id || p.user_id;
          // Si prodId es string tipo 'pack-<id>', ignorar este item
          if (typeof prodId === 'string' && prodId.startsWith('pack-')) {
            return { ...p, error: 'ID inválido para producto (pack-xx)' };
          }
          const productoCompleto = productosDB.find((prod: { producto_id: string | number }) => String(prod.producto_id) === String(prodId));
          if (!productoCompleto) return { ...p, error: 'Producto no encontrado en base de datos' };
          const unidadesProducto = unidadesByProducto[String(prodId)] || {};
          const variantesProducto = Array.isArray(productoCompleto.variantes) ? productoCompleto.variantes : [];
          const varianteSeleccionada = p.variante_id
            ? variantesProducto.find((v: VariantMatch) => String(v.variante_id ?? v.id) === String(p.variante_id))
            : null;
          // Siempre usar la imagen del producto
          const imagenesProducto = imagenesDB[productoCompleto.producto_id] || [];
          const imagen_url = imagenesProducto.length > 0 ? imagenesProducto[0] : '/sin-imagen.png';
          const unidadBase = p.unidad_base || unidadesProducto.unidad_base || productoCompleto.unidad_base || p.unidad || 'unidad';
          const unidadesAlternativas = Array.isArray(p.unidades_alternativas)
            ? p.unidades_alternativas
            : Array.isArray(unidadesProducto.unidades_alternativas)
              ? unidadesProducto.unidades_alternativas
              : [];
          const factorConversion = Number(p.factor_conversion ?? unidadesProducto.factor_conversion ?? productoCompleto.factor_conversion ?? 0) || undefined;
          const cantidadBase = normalizeQuantity(p.cantidad_base ?? p.cantidad ?? 1);
          const cantidadDisplay = normalizeQuantity(p.cantidad_display ?? p.cantidad ?? 1);
          return {
            ...productoCompleto,
            user_id: productoCompleto.producto_id,
            cantidad: cantidadBase,
            cantidad_base: cantidadBase,
            cantidad_display: cantidadDisplay,
            unidad: p.unidad || unidadBase,
            unidad_base: unidadBase,
            unidades_alternativas: unidadesAlternativas,
            unidades_disponibles: [unidadBase, ...unidadesAlternativas.filter((u: string) => u !== unidadBase)],
            factor_conversion: factorConversion,
            tipo: 'producto',
            cart_key: `prod:${productoCompleto.producto_id}:${p.variante_id || 'default'}:${p.unidad || unidadBase}`,
            variante_id: p.variante_id || productoCompleto.variante_id,
            color: p.color || productoCompleto.color,
            ...restorePendingOrderPricing(p, { ...productoCompleto, precio: unidadesProducto.precio ?? productoCompleto.precio_base }, varianteSeleccionada),
            precio_compra: unidadesProducto.precio_compra,
            nombre: productoCompleto.nombre || 'Producto sin nombre',
            stock: varianteSeleccionada ? getVariantStock(varianteSeleccionada) : Number(unidadesProducto.stock ?? productoCompleto.stock ?? 0),
            categoria: productoCompleto.categoria,
            categorias: productoCompleto.categorias,
            variantes: variantesProducto,
            codigo_barra: productoCompleto.codigo_barra,
            codigo: productoCompleto.codigo,
            imagenes: productoCompleto.imagenes,
            imagen_url,
          };
        });

        // Si hay algún error, bloquear venta y mostrar error
        const errores = carritoReconstruido.filter(i => i.error);
        if (errores.length > 0) {
          showToast('Error: Hay productos o packs que ya no existen en la base de datos. Corrige el pedido antes de continuar.', 'error');
          setCarrito([]);
        } else {
          setCarrito(carritoReconstruido);
        }

        // Cargar datos de cliente si existen
        if (pedidoObj.cliente_nombre) cambiarCampo('nombre', pedidoObj.cliente_nombre);
        if (pedidoObj.usuario_email || pedidoObj.cliente_email) cambiarCampo('email', pedidoObj.usuario_email || pedidoObj.cliente_email);
        if (pedidoObj.cliente_telefono) cambiarCampo('telefono', pedidoObj.cliente_telefono);
        if (pedidoObj.cliente_nit) cambiarCampo('nit', pedidoObj.cliente_nit);
      } catch (e: unknown) {
        console.error('Error cargando pedido:', e);
        let errorMsg = '';
        if (e && typeof e === 'object' && 'message' in e && typeof (e as any).message === 'string') {
          errorMsg = (e as any).message;
        } else {
          errorMsg = String(e);
        }
        showToast('Error cargando pedido: ' + errorMsg, 'error');
        setCarrito([]);
      }
      sessionStorage.removeItem('pedido_a_efectivizar');
    })();
    // Solo dependencias estables para evitar warning de React
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [setCarrito, cambiarCampo, activePaisId, effectiveSucursalId]);

  // shortcuts
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.ctrlKey && e.key.toLowerCase() === 'b') { e.preventDefault(); document.querySelector<HTMLInputElement>('input[placeholder="Escanea o ingresa código de barra"]')?.focus(); }
      if (e.ctrlKey && e.key.toLowerCase() === 'f') { e.preventDefault(); document.querySelector<HTMLInputElement>('input[placeholder*="Buscar producto"]')?.focus(); }
      if (e.ctrlKey && e.key.toLowerCase() === 'k') { e.preventDefault(); document.querySelector<HTMLInputElement>('input[placeholder*="Carnet"]')?.focus(); }
      if (e.ctrlKey && e.key.toLowerCase() === 'e') { e.preventDefault(); document.querySelector<HTMLButtonElement>('button[aria-label="efectivizar-venta"]')?.click(); }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, []);

  // fetch iniciales
  useEffect(() => {
    fetchProductos();
  }, [fetchProductos]);

  // sonido beep
  useEffect(() => {
    beepRef.current = new Audio('/beep.mp3');
  }, []);

  // pago auto

  // Sincroniza pagos con total
  useEffect(() => {
    // Si método no es efectivo, autollenar monto
    setPagos((prev) => prev.map((p, idx) => {
      if (p.metodo && p.metodo !== 'efectivo' && Number(p.monto) === 0) {
        // Si hay dos pagos, el segundo es el resto
        if (mostrarSegundoPago && idx === 1) {
          return { ...p, monto: Math.max(0, totalCobrar - (Number(prev[0]?.monto) || 0)) };
        }
        return { ...p, monto: totalCobrar };
      }
      return p;
    }));
  }, [pagos[0]?.metodo, pagos[1]?.metodo, totalCobrar, mostrarSegundoPago]);

  useEffect(() => {
    setShowInsufficientPaymentWarning(pagoInsuficiente);
  }, [pagoInsuficiente]);

  useEffect(() => {
    if (!stockWarning) return;
    const timeoutId = setTimeout(() => clearStockWarning(), 2500);
    return () => clearTimeout(timeoutId);
  }, [stockWarning, clearStockWarning]);

  useEffect(() => {
    if (!Array.isArray(productos) || productos.length === 0 || carrito.length === 0) return;

    setCarrito((prev) => {
      let changed = false;
      const next = prev.map((item) => {
        if (item.tipo === 'pack' || item.user_id == null) return item;
        const product = productos.find((p) => String(p.user_id) === String(item.user_id));
        if (!product) return item;
        if (!hasUnitConversion(product)) {
          if (item.precio_compra === product.precio_compra && item.imagen_url === product.imagen_url) return item;
          changed = true;
          return { ...item, precio_compra: product.precio_compra, imagen_url: product.imagen_url };
        }

        const unidadBase = String(product.unidad_base || item.unidad_base || 'unidad');
        const alternativas = Array.isArray(product.unidades_alternativas)
          ? product.unidades_alternativas.filter((u) => u && u !== unidadBase)
          : [];
        const unidadAlternativa = alternativas[0];
        const factor = Number(product.factor_conversion || item.factor_conversion || 0);
        const variantForItem = item.variante_id
          ? (Array.isArray((product as Producto & { variantes?: VariantMatch[] }).variantes)
              ? (product as Producto & { variantes?: VariantMatch[] }).variantes?.find((variant) =>
                  String(variant.variante_id ?? variant.id) === String(item.variante_id)
                )
              : null)
          : null;
        const stockBase = variantForItem ? getVariantStock(variantForItem) : getProductStock(product);
        if (!unidadAlternativa || !Number.isFinite(factor) || factor <= 0) return item;

        const unidadesDisponibles = [
          ...(stockBase >= 1 ? [unidadBase] : []),
          ...(stockBase * factor > 0 ? [unidadAlternativa] : []),
        ];
        const unidadActual = String(item.unidad || item.unidad_base || unidadBase);
        const unidadVenta = unidadesDisponibles.includes(unidadActual)
          ? unidadActual
          : (unidadesDisponibles[0] || unidadAlternativa);
        const cantidadDisplay = normalizeQuantity(item.cantidad_display ?? item.cantidad ?? 1) || 1;
        const cantidadBase = unidadVenta === unidadBase ? cantidadDisplay : cantidadDisplay / factor;

        const patched = {
          ...item,
          stock: stockBase,
          precio_compra: product.precio_compra,
          imagen_url: product.imagen_url,
          unidad_base: unidadBase,
          unidades_alternativas: alternativas,
          unidades_disponibles: unidadesDisponibles,
          factor_conversion: factor,
          unidad: unidadVenta,
          cantidad: cantidadBase,
          cantidad_base: cantidadBase,
          cantidad_display: cantidadDisplay,
        };

        const same =
          item.precio_compra === patched.precio_compra &&
          item.imagen_url === patched.imagen_url &&
          Number(item.stock || 0) === stockBase &&
          item.unidad_base === patched.unidad_base &&
          item.unidad === patched.unidad &&
          Number(item.factor_conversion || 0) === factor &&
          Number(item.cantidad_base || 0) === cantidadBase &&
          Number(item.cantidad_display || 0) === cantidadDisplay &&
          JSON.stringify(item.unidades_disponibles || []) === JSON.stringify(unidadesDisponibles);

        if (!same) changed = true;
        return same ? item : patched;
      });
      return changed ? next : prev;
    });
  }, [productos, carrito, setCarrito]);

  // Escaneo: si el producto está en un pack, ofrecer opción de agregar pack o individual
  const procesarCodigo = useCallback(async (codigo: string) => {
    const normalizeCode = (value: unknown) => String(value ?? '').replace(/\D/g, '');
    const matchesBarcode = (input: string, stored: unknown) => {
      const a = normalizeCode(input);
      const b = normalizeCode(stored);
      if (!a || !b) return false;
      return a === b || (a.length === 13 && a.slice(0, 12) === b) || (b.length === 13 && b.slice(0, 12) === a);
    };

    const buildScannedProduct = (p: Producto) => {
      const variants = Array.isArray(p.variantes) ? p.variantes : [];
      const matchedVariant = variants.find((variant) => {
        const currentVariant = variant as VariantMatch;
        return matchesBarcode(codigo, currentVariant?.codigo_barra) || matchesBarcode(codigo, currentVariant?.sku);
      }) as VariantMatch | undefined;
      if (!matchedVariant) return null;
      return {
        ...p,
        variante_id: matchedVariant?.variante_id ?? matchedVariant?.id,
        color: matchedVariant?.color || 'Sin color',
        precio: Number(matchedVariant?.precio ?? p.precio ?? 0),
        stock: getVariantStock(matchedVariant),
        codigo: String(matchedVariant?.sku || '')
      } as Producto;
    };

    let productoEncontrado: Producto | null = null;
    for (const p of productos) {
      const candidate = buildScannedProduct(p);
      if (candidate) {
        productoEncontrado = candidate;
        break;
      }
    }

    // Fallback: buscar en DB por si el producto se creó recientemente y la página sigue abierta
    if (!productoEncontrado) {
      const resultados = await searchProductos(codigo);
      if (Array.isArray(resultados) && resultados.length > 0) {
        const conVariante = resultados.find((resultado) => resultado.variante_id != null);
        if (conVariante) {
          productoEncontrado = conVariante;
        }
      }
    }

    if (!productoEncontrado) {
      return false;
    }

    // Buscar si el producto está en algún pack activo
    const packsConEsteProducto = packs.filter(pack =>
      Array.isArray(pack.pack_productos) &&
      pack.pack_productos.some(item => item.productos.user_id === productoEncontrado.user_id)
    );

    if (packsConEsteProducto.length > 0) {
      // Mostrar confirmación al usuario
      if (window.confirm(`Este producto está en un pack: ${packsConEsteProducto.map(p=>p.nombre).join(', ')}.\n¿Agregar el pack (OK) o solo el producto individual (Cancelar)?`)) {
        // Agregar el primer pack encontrado
        agregar({
          user_id: null,
          tipo: 'pack',
          pack_id: packsConEsteProducto[0].id,
          pack_data: packsConEsteProducto[0],
          nombre: packsConEsteProducto[0].nombre,
          cantidad: 1,
          precio: packsConEsteProducto[0].precio_pack,
          precio_pack: packsConEsteProducto[0].precio_pack,
          precio_individual: (packsConEsteProducto[0].pack_productos ?? []).reduce((t: number, i: { productos: { precio: number }, cantidad: number }) => t + (i.productos.precio * i.cantidad), 0),
          descuento: calcularDescuentoPack(packsConEsteProducto[0]).descuentoAbsoluto,
          productos: packsConEsteProducto[0].pack_productos,
          cart_key: `pack:${packsConEsteProducto[0].id}`
        });
      } else {
        // Agregar solo el producto individual con su precio original
        agregar({ ...productoEncontrado, precio: productoEncontrado.precio, tipo: 'producto' });
      }
    } else {
      agregar(productoEncontrado);
    }

    // Sonido y feedback
    beepRef.current?.play().catch(() => {});
    if (navigator.vibrate) navigator.vibrate(80);
    setScanFeedback(true);
    setTimeout(() => setScanFeedback(false), 200);
    return true;
  }, [productos, agregar, searchProductos, packs]);

  const handleBuscadorSubmit = useCallback(async () => {
    const raw = busqueda.trim();
    if (!raw) {
      await searchProductos('');
      setShowSuggestions(true);
      // Mostrar todos los packs activos si no hay búsqueda
      setPackResults(packs);
      return;
    }

    const codigoNumerico = raw.replace(/\D/g, '');
    if (codigoNumerico.length >= 6) {
      const now = Date.now();
      const last = lastAutoAddRef.current;
      if (!(last.code === codigoNumerico && now - last.timestamp < 700)) {
        const agregado = await procesarCodigo(codigoNumerico);
        if (agregado) {
          lastAutoAddRef.current = { code: codigoNumerico, timestamp: now };
          setBusqueda('');
          setShowSuggestions(false);
          setPackResults([]);
          return;
        }
      }
    }

    await searchProductos(raw);
    // Filtrar packs por nombre o productos incluidos
    const lower = raw.toLowerCase();
    const filteredPacks = packs.filter(pack => {
      if (pack.nombre?.toLowerCase().includes(lower)) return true;
      if (pack.descripcion?.toLowerCase().includes(lower)) return true;
      if (Array.isArray(pack.pack_productos)) {
        return pack.pack_productos.some(item => item.productos?.nombre?.toLowerCase().includes(lower));
      }
      return false;
    });
    setPackResults(filteredPacks);
    setShowSuggestions(true);
  }, [busqueda, procesarCodigo, searchProductos, packs]);

  // detector de scanner real (teclado rápido + ENTER)
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const key = e.key;
      const active = document.activeElement as HTMLElement | null;
      const isInput = active && (active.tagName === 'INPUT' || active.tagName === 'TEXTAREA' || active.tagName === 'SELECT' || active.isContentEditable);
      const isBarcodeInput = isInput && active instanceof HTMLInputElement && active.placeholder?.includes('Escanea o ingresa código de barra');

      // ignorar teclas especiales
      if (key === 'Shift' || key === 'Control' || key === 'Alt' || key === 'Meta') return;

      // ENTER = terminar escaneo (solo si no estamos en un campo normal o estamos en campo de barcode)
      if (key === 'Enter') {
        if (isInput && !isBarcodeInput) return; // no ligar con enter de formulario normal

        const codigo = scanBuffer.current;

        if (codigo.length >= 6) {
          procesarCodigo(codigo);
        }

        scanBuffer.current = '';
        setBusqueda('');
        setShowSuggestions(false);

        if (scanTimer.current) {
          clearTimeout(scanTimer.current);
          scanTimer.current = null;
        }

        return;
      }

      // solo números
      if (/^[0-9]$/.test(key)) {
        if (isInput && !isBarcodeInput) return; // dejamos escribir cantidades y pagos normales

        e.preventDefault();
        scanBuffer.current += key;

        // reset timer (detectar si no es scanner)
        if (scanTimer.current) clearTimeout(scanTimer.current);

        scanTimer.current = setTimeout(() => {
          scanBuffer.current = '';
          scanTimer.current = null;
        }, 100);
      }
    };

    window.addEventListener('keydown', handleKeyDown);

    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      if (scanTimer.current) clearTimeout(scanTimer.current);
    };
  }, [procesarCodigo]);


  // acciones de venta

  const efectivizarVenta = useCallback(async () => {
    if (saleInFlightRef.current) return;
    if (loadingPromociones || errorPromociones) {
      showToast('Espera a que se verifiquen las promociones antes de efectivizar.', 'error');
      return;
    }
    saleRequestKeyRef.current ||= crypto.randomUUID();
      // ...existing code...
    if (carrito.length === 0) { showToast('El carrito esta vacio', 'error'); return; }
    if (!pagos[0].metodo || pagos[0].monto <= 0) { showToast('Selecciona al menos un método de pago y monto', 'error'); return; }
    if (mostrarSegundoPago && (!pagos[1].metodo || pagos[1].monto <= 0)) { showToast('Completa el segundo método de pago y monto', 'error'); return; }
    if (sumaPagos + 0.009 < totalCobrar) { showToast('La suma de los pagos es insuficiente', 'error'); return; }
    if (!tienePagoEnEfectivo && sumaPagos > totalCobrar + 0.01) { showToast('La suma de los pagos supera el total', 'error'); return; }
    if (cliente.requiereFactura && (!cliente.nombre.trim() || !cliente.nit.trim())) { showToast('Completa los datos de facturacion (nombre y NIT)', 'error'); return; }
    if (!activePaisId || !effectiveSucursalId) { showToast('Selecciona pais y sucursal antes de vender', 'error'); return; }

    setEfectivizando(true);
    saleInFlightRef.current = true;

    try {
      // Obtener token y usuario solo una vez
      const { data: sessionData } = await supabase.auth.getSession();
      const token = sessionData?.session?.access_token;
      // 1. Agrupar productos y packs del carrito
      const productosIds = carrito
        .filter(p => p.tipo !== 'pack' && getCarritoProductoId(p))
        .map(p => String(getCarritoProductoId(p)));
      const packsIds = carrito.filter(p => p.tipo === 'pack' && p.pack_id).map(p => String(p.pack_id));

      // 2. Consultar productos y variantes desde la base de datos
      let productosDB: ProductoDB[] = [];
      if (productosIds.length > 0) {
        let productosQuery = supabase
          .from('productos')
          .select('user_id, nombre, precio, precio_compra, stock, categoria, codigo_barra, unidad_base, unidades_alternativas, factor_conversion, producto_variantes ( id, color, precio, stock, stock_decimal, sku )')
          .in('user_id', productosIds)
          .eq('archivado', false);
        if (activePaisId) productosQuery = productosQuery.eq('pais_id', activePaisId);
        if (effectiveSucursalId) productosQuery = productosQuery.eq('sucursal_id', effectiveSucursalId);
        const { data: productosData, error: productosError } = await productosQuery;
        if (productosError) throw productosError;
        productosDB = Array.isArray(productosData) ? productosData : [];
      }

      // 3. Consultar packs y sus productos desde la base de datos
      let packsDB: PackDB[] = [];
      if (packsIds.length > 0) {
        let packsQuery = supabase
          .from('packs')
          .select('*, pack_productos ( cantidad, producto_id, variante_id, productos!pack_productos_producto_id_fkey ( user_id, nombre, precio, categoria, stock, producto_variantes ( id, color, precio, stock, stock_decimal, sku ) ) )')
          .in('id', packsIds);
        if (activePaisId) packsQuery = packsQuery.eq('pais_id', activePaisId);
        if (effectiveSucursalId) packsQuery = packsQuery.eq('sucursal_id', effectiveSucursalId);
        const { data: packsData, error: packsError } = await packsQuery;
        if (packsError) throw packsError;
        packsDB = Array.isArray(packsData) ? packsData : [];
      }

      const stockRequests = new Map<string, StockRequest>();
      const addStockRequest = (key: string, request: StockRequest) => {
        const current = stockRequests.get(key);
        if (current) {
          current.solicitado += request.solicitado;
          return;
        }
        stockRequests.set(key, request);
      };

      for (const p of carrito) {
        const cantidadBase = normalizeQuantity(p.cantidad_base ?? p.cantidad ?? 1);
        if (cantidadBase <= 0) throw new Error(`Cantidad invalida para ${p.nombre || 'producto'}`);

        if (p.tipo === 'pack') {
          const pack = packsDB.find(pk => String(pk.id) === String(p.pack_id));
          if (!pack) throw new Error('Pack no encontrado en base de datos');

          for (const item of pack.pack_productos ?? []) {
            const productoPack = item.productos;
            if (!productoPack?.user_id) throw new Error('Producto de pack no encontrado en base de datos');
            const cantidadTotal = normalizeQuantity(item.cantidad) * cantidadBase;
            if (item.variante_id) {
              const variante = productoPack.producto_variantes?.find((v: { id?: string | number }) => String(v.id) === String(item.variante_id));
              if (!variante) throw new Error(`Variante de pack no encontrada para ${productoPack.nombre || 'producto'}`);
              addStockRequest(`var:${String(variante.id)}`, {
                nombre: productoPack.nombre || 'Producto',
                color: variante.color || null,
                disponible: getVariantStock(variante),
                solicitado: cantidadTotal
              });
            } else {
              addStockRequest(`prod:${String(productoPack.user_id)}`, {
                nombre: productoPack.nombre || 'Producto',
                color: null,
                disponible: getProductStock(productoPack),
                solicitado: cantidadTotal
              });
            }
          }
          continue;
        }

        const carritoProductoId = getCarritoProductoId(p);
        if (carritoProductoId == null) throw new Error('Producto invalido en carrito');
        const productoCompleto = productosDB.find(prod => String(prod.user_id) === String(carritoProductoId));
        if (!productoCompleto) throw new Error(`Producto no encontrado en base de datos: ${p.nombre || carritoProductoId}`);
        const cantidadBaseVenta = getSaleBaseQuantity(p, productoCompleto);

        if (p.variante_id) {
          const variante = (productoCompleto.producto_variantes || []).find((v) => String(v.id) === String(p.variante_id));
          if (!variante) throw new Error(`Color no encontrado para ${productoCompleto.nombre || p.nombre}`);
          addStockRequest(`var:${String(variante.id)}`, {
            nombre: productoCompleto.nombre || p.nombre || 'Producto',
            color: variante.color || p.color || null,
            disponible: getStockForVariantSale(productoCompleto, variante),
            solicitado: cantidadBaseVenta
          });
        } else {
          addStockRequest(`prod:${String(productoCompleto.user_id)}`, {
            nombre: productoCompleto.nombre || p.nombre || 'Producto',
            color: null,
            disponible: getProductStock(productoCompleto),
            solicitado: cantidadBaseVenta
          });
        }
      }

      for (const request of stockRequests.values()) {
        if (request.solicitado > request.disponible + 0.0001) {
          throw new Error(
            `Stock insuficiente para ${request.nombre}${request.color ? ` color ${request.color}` : ''} ` +
            `(stock=${formatStockQuantity(request.disponible)}, solicitado=${formatStockQuantity(request.solicitado)})`
          );
        }
      }

      // 4. Armar objeto de costos extra
      const costos_extra = {
        envio: Number(envio) || 0,
        comision: Number(comision) || 0,
        impuestos: Number(impuestosCalculados.toFixed(2)) || 0,
        cobrar_impuestos: cobrarImpuestos,
        publicidad: Number(publicidad) || 0,
        rebajas: Number(rebajas) || 0,
        descuento: Number(totalDescuento) || 0,
        descuentos_productos: carrito.filter(p => p.tipo !== 'pack').map(p => ({
          producto_id: String(p.user_id), variante_id: p.variante_id == null ? null : String(p.variante_id),
          ...calcularLineaVenta(p, promociones, packs)
        }))
      };

      const ventaPayload = {
        cliente_nombre: cliente.nombre,
        cliente_telefono: cliente.telefono,
        cliente_email: cliente.email,
        cliente_nit: cliente.nit,
        requiere_factura: cliente.requiereFactura,
        modo_pago: pagos.map(p => p.metodo).filter(Boolean).join(' + '),
        total: totalCobrar,
        pago: sumaPagos,
        cambio,
        descuentos: totalDescuento,
        costos_extra,
        pais_id: activePaisId,
        sucursal_id: effectiveSucursalId,
      };

      const ventaItems: Array<Record<string, unknown>> = [];
      for (const p of carrito) {
        const cantidadVisible = Number(p.cantidad_display ?? p.cantidad ?? 1);
        const unidadVenta = String(p.unidad || p.unidad_base || 'unidad');

        if (p.tipo === 'pack') {
          const cantidadPack = normalizeQuantity(p.cantidad_base ?? p.cantidad ?? 1);
          const pack = packsDB.find(pk => String(pk.id) === String(p.pack_id));
          if (!pack) throw new Error('Pack no encontrado en base de datos');

          for (const item of pack?.pack_productos ?? []) {
            const productoPack = item.productos as NonNullable<typeof item.productos>;
            if (!productoPack?.user_id) throw new Error('Producto de pack no encontrado en base de datos');
            const cantidadTotal = normalizeQuantity(item.cantidad) * cantidadPack;
            const variante = item.variante_id
              ? productoPack.producto_variantes?.find(v => String(v.id) === String(item.variante_id))
              : null;
            ventaItems.push({
              producto_id: productoPack.user_id,
              variante_id: variante?.id || null,
              cantidad: cantidadTotal,
              cantidad_base: cantidadTotal,
              unidad: 'unidad',
              precio_unitario: 0,
              pack_id: p.pack_id,
              pack_cantidad: cantidadPack,
              costo_unitario: 0,
              color: variante?.color || null,
              descripcion: `Pack: ${pack.nombre || p.nombre || 'Pack'} - ${productoPack.nombre || 'Producto'}`,
              nombre: productoPack.nombre || p.nombre || 'Producto',
            });
          }
          continue;
        }

        const carritoProductoId = getCarritoProductoId(p);
        if (carritoProductoId == null) throw new Error('Producto invalido en carrito');
        const productoCompleto = productosDB.find(prod => String(prod.user_id) === String(carritoProductoId));
        if (!productoCompleto) throw new Error(`Producto no encontrado en base de datos: ${p.nombre || carritoProductoId}`);
        const variante = p.variante_id
          ? (productoCompleto.producto_variantes || []).find(v => String(v.id) === String(p.variante_id))
          : null;
        const cantidadBase = getSaleBaseQuantity(p, productoCompleto);
        const unidadBaseVenta = String(p.unidad_base || productoCompleto.unidad_base || unidadVenta);
        const descripcionItem = `${productoCompleto.nombre || p.nombre || 'Producto'}${variante?.color ? ` ${variante.color}` : p.color ? ` ${p.color}` : ''}${unidadVenta !== unidadBaseVenta ? ` (${cantidadVisible} ${unidadVenta} = ${formatStockQuantity(cantidadBase)} ${unidadBaseVenta})` : ''}`.trim();

        ventaItems.push({
          producto_id: productoCompleto.user_id,
          variante_id: variante?.id || null,
          cantidad: cantidadVisible,
          cantidad_base: cantidadBase,
          unidad: unidadVenta,
          precio_unitario: calcularLineaVenta(p, promociones, packs).precio,
          costo_unitario: Number(productoCompleto.precio_compra || 0),
          color: variante?.color || p.color || null,
          descripcion: descripcionItem,
          nombre: productoCompleto.nombre || p.nombre || 'Producto',
        });
      }

      if (!token) throw new Error('Sesion no disponible para efectivizar la venta');

      const response = await fetch('/api/admin/ventas/crear', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
          'Idempotency-Key': saleRequestKeyRef.current,
          'X-Correlation-Id': saleRequestKeyRef.current,
        },
        body: JSON.stringify({
          venta: ventaPayload,
          items: ventaItems,
          pagos: pagos
            .filter(p => p.metodo && Number(p.monto || 0) > 0)
            .map(p => ({ metodo_pago: p.metodo, monto: Number(p.monto || 0) })),
          pending_order_id: pendingPedidoIdRef.current,
          cashbox_id: 'main',
        }),
      });
      const apiPayload = await response.json().catch(() => null);
      if (!response.ok || !apiPayload?.success) {
        throw new Error(apiPayload?.error || 'No se pudo efectivizar la venta');
      }

      printerRef.current?.printComprobante();
      pendingPedidoIdRef.current = null;
      saleRequestKeyRef.current = null;
      setCarrito([]);
      setPagos([{ metodo: '', monto: 0 }]);
      setMostrarSegundoPago(false);
      setEnvio(0); setComision(0); setPublicidad(0); setRebajas(0); setCobrarImpuestos(false);
      cambiarCampo('nombre',''); cambiarCampo('carnet',''); cambiarCampo('telefono',''); cambiarCampo('email',''); cambiarCampo('nit',''); cambiarCampo('guardado',false); cambiarCampo('requiereFactura',false);
      setEfectivizando(false);
      saleInFlightRef.current = false;
      showToast('Venta efectivizada y stock actualizado');
      return;
    } catch (err) {
      const errorContext = err && typeof err === 'object'
        ? ['message', 'details', 'hint']
            .map((key) => {
              const value = (err as Record<string, unknown>)[key];
              return typeof value === 'string' && value.trim() ? value : null;
            })
            .filter(Boolean)
            .join(' | ')
        : '';
      const errorMessage = err instanceof Error
        ? err.message
        : errorContext || String(err);
      showToast('Error al crear venta: ' + errorMessage, 'error');
      setEfectivizando(false);
      saleInFlightRef.current = false;
    }
  }, [promociones, loadingPromociones, errorPromociones, carrito, cliente, pagos, mostrarSegundoPago, sumaPagos, tienePagoEnEfectivo, cambio, totalCobrar, subtotal, totalDescuento, packs, setCarrito, cambiarCampo, envio, comision, publicidad, rebajas, impuestosCalculados, cobrarImpuestos, activePaisId, effectiveSucursalId]);

  // ...continued building UI mostly replicates previous layout using components

  return (
    <div className="min-h-screen w-full flex flex-col items-center justify-start py-8 px-2 bg-gradient-to-br from-gray-100 to-gray-300">
      <h1 className="text-3xl font-extrabold mb-8 text-gray-900 w-full text-center">Nueva Venta</h1>
      <div className="w-full max-w-7xl grid grid-cols-1 lg:grid-cols-4 gap-6 bg-white rounded-xl shadow-xl p-0 mb-8 border border-gray-900">
        <div className="col-span-1 bg-gray-50 border-b lg:border-b-0 lg:border-r border-gray-200 p-6 sticky top-16 z-0 print:hidden flex flex-col h-full">
          <div className="flex flex-col gap-4">
            <div className="flex flex-col gap-2">
              <span className="font-bold text-gray-900 text-lg">Resumen de la venta</span>
              <span className="text-gray-900">Subtotal: <span className="font-bold">Bs {subtotal.toFixed(2)}</span></span>
              {totalDescuento > 0 && <span className="text-green-700">Descuentos: -Bs {totalDescuento.toFixed(2)}</span>}
              <span className="text-gray-900">Base operativa: <span className="font-bold">Bs {totalBaseOperacion.toFixed(2)}</span></span>
              {cobrarImpuestos && <span className="text-amber-700">IVA+IT (16%): +Bs {impuestosCalculados.toFixed(2)}</span>}
              <span className="text-2xl font-extrabold text-gray-900">Total a cobrar: Bs {totalCobrar.toFixed(2)}</span>
            </div>
            {/* costos adicionales configurables por admin */}
            <div className="mt-4 grid grid-cols-2 gap-2">
              <div>
                <label className="block text-gray-700">Envio</label>
                <input type="number" step="0.01" min="0" value={envio} onChange={e=>setEnvio(parsePositiveNumber(e.target.value))} className="w-full border p-2 rounded" />
              </div>
              <div>
                <label className="block text-gray-700">Comision</label>
                <input type="number" step="0.01" min="0" value={comision} onChange={e=>setComision(parsePositiveNumber(e.target.value))} className="w-full border p-2 rounded" />
              </div>
              <div>
                <label className="block text-gray-700">Impuestos</label>
                <input type="number" step="0.01" min="0" value={Number(impuestosCalculados.toFixed(2))} readOnly className="w-full border p-2 rounded bg-gray-100" />
              </div>
              <div>
                <label className="block text-gray-700">Publicidad</label>
                <input type="number" step="0.01" min="0" value={publicidad} onChange={e=>setPublicidad(parsePositiveNumber(e.target.value))} className="w-full border p-2 rounded" />
              </div>
              <div>
                <label className="block text-gray-700">Rebajas</label>
                <input aria-label="Rebaja general en Bs" type="number" step="0.01" min="0" value={rebajas} onChange={e=>setRebajas(parsePositiveNumber(e.target.value))} className="w-full border p-2 rounded" />
              </div>
            </div>
            <label className="inline-flex items-center gap-2 text-sm font-semibold text-gray-800">
              <input
                type="checkbox"
                checked={cobrarImpuestos}
                onChange={(e) => setCobrarImpuestos(e.target.checked)}
                className="w-4 h-4"
              />
              Cobrar IVA + IT (16% sobre precio final)
            </label>
            <button
              type="button"
              onClick={() => printerRef.current?.printCotizacion()}
              className="mt-6 w-full bg-blue-700 hover:bg-blue-800 text-white font-bold py-3 rounded-lg text-base disabled:opacity-50 disabled:cursor-not-allowed"
              disabled={efectivizando || carrito.length === 0}
            >
              Imprimir proforma
            </button>
          </div>
        </div>
        <div className="lg:col-span-3 p-6">
          <ClienteForm
            cliente={cliente}
            onChange={cambiarCampo}
            onBuscar={buscarPorCarnet}
            onGuardar={guardar}
            onBuscarEmailHistorico={buscarEmailHistorico}
          />

          {/* Métodos de pago */}
          <div className="mb-4 flex flex-col gap-2">
            <label className="font-bold text-gray-900">Modo de pago:</label>
            {[0, mostrarSegundoPago ? 1 : null].filter(i => i !== null).map((idx) => (
              <div key={idx} className="flex gap-2 flex-wrap items-center mb-2">
                {['efectivo','tarjeta','qr','transferencia'].map(m => (
                  <button
                    key={m}
                    type="button"
                    onClick={() => setPagos(p => p.map((pago, i) => i === idx ? { ...pago, metodo: m } : pago))}
                    className={`px-3 py-2 rounded-full font-semibold transition ${(pagos[idx] && pagos[idx].metodo === m) ? 'bg-green-700 text-white shadow' : 'bg-gray-100 text-gray-800 hover:bg-gray-200'}`}
                  >
                    {m.charAt(0).toUpperCase()+m.slice(1)}
                  </button>
                ))}
                <input
                  type="number"
                  min={0}
                  step={0.01}
                  className="w-40 border border-gray-900 bg-white text-gray-900 rounded px-3 py-2 placeholder-gray-700 focus:border-gray-900 focus:ring focus:ring-gray-900/30"
                  placeholder="Monto"
                  value={pagos[idx]?.monto ?? ''}
                  onChange={e => setPagos(p => p.map((pago, i) => i === idx ? { ...pago, monto: parsePositiveNumber(e.target.value) } : pago))}
                />
                {idx === 0 && (
                  <span className="text-sm text-gray-700">Cambio: <span className={cambio < 0 ? 'text-red-700' : 'text-green-700'}>Bs {cambio.toFixed(2)}</span></span>
                )}
              </div>
            ))}
            {/* Checkbox para segundo método */}
            <label className="inline-flex items-center gap-2 text-sm font-semibold text-gray-800 mt-2">
              <input
                type="checkbox"
                checked={mostrarSegundoPago}
                onChange={e => {
                  setMostrarSegundoPago(e.target.checked);
                  setPagos(p => e.target.checked ? (p.length === 1 ? [...p, { metodo: '', monto: 0 }] : p) : [p[0]]);
                }}
                className="w-4 h-4"
              />
              ¿Tienes otro método de pago?
            </label>
          </div>

          {/* ...existing code... */}

          <BuscadorProductos
            busqueda={busqueda}
            onChange={val => { setBusqueda(val); searchProductos(val); }}
            onSubmit={handleBuscadorSubmit}
            searchResults={searchResults}
            searchLoading={searchLoading}
            imagenes={imagenes}
            onAdd={agregar}
            showSuggestions={showSuggestions}
            setShowSuggestions={setShowSuggestions}
            packResults={packResults}
            onAddPack={pack => {
              // Estructura para agregar pack al carrito
              agregar({
                user_id: null,
                tipo: 'pack',
                pack_id: pack.id,
                pack_data: pack,
                nombre: pack.nombre,
                cantidad: 1,
                precio: pack.precio_pack,
                precio_pack: pack.precio_pack,
                precio_individual: (pack.pack_productos ?? []).reduce((t: number, i: { productos: { precio: number }, cantidad: number }) => t + (i.productos.precio * i.cantidad), 0),
                descuento: calcularDescuentoPack(pack).descuentoAbsoluto,
                productos: pack.pack_productos ?? [],
                cart_key: `pack:${pack.id}`
              });
              setShowSuggestions(false);
              setBusqueda('');
              setPackResults([]);
            }}
            promociones={promociones}
          />

          <CarritoPanel
            carrito={carrito}
            imagenes={imagenes}
            quitar={quitar}
            cambiarCantidad={cambiarCantidad}
            cambiarUnidadYCantidad={cambiarUnidadYCantidad}
            cambiarDescuento={cambiarDescuento}
            subtotal={subtotal}
            totalDescuento={totalDescuento}
            total={total}
            envio={envio}
            comision={comision}
            publicidad={publicidad}
            rebajas={rebajas}
            impuestos={impuestosCalculados}
            totalCobrar={totalCobrar}
            modoPago={pagos.map(p=>p.metodo).join(' + ')}
            pago={sumaPagos}
            cambio={cambio}
            packs={packs}
            promociones={promociones}
          />

          {stockWarning && (
            <div className="mt-4 rounded-lg border border-amber-300 bg-amber-50 px-4 py-3">
              <p className="font-bold text-amber-800">Stock insuficiente</p>
              <p className="text-sm text-amber-700">{stockWarning}</p>
            </div>
          )}

          {showInsufficientPaymentWarning && (
            <div className="mt-4 p-4 rounded-lg border border-red-300 bg-red-50">
              <p className="text-red-800 font-bold">El pago recibido es insuficiente</p>
              <p className="text-red-700 text-sm">Faltan: Bs {(totalCobrar - sumaPagos).toFixed(2)}</p>
            </div>
          )}

          <button
            ref={efectivizarBtnRef}
            aria-label="efectivizar-venta"
            onClick={efectivizarVenta}
            className="mt-4 w-full bg-black hover:bg-gray-900 text-white font-bold py-3 rounded-lg text-lg disabled:opacity-60"
            disabled={efectivizando || showInsufficientPaymentWarning || loadingPromociones || !!errorPromociones}
          >
            {efectivizando ? "Procesando..." : "Efectivizar venta"}
          </button>
        </div>
      </div>
      {efectivizando && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white p-6 rounded-xl font-bold text-black">Procesando venta...</div>
        </div>
      )}

      {scanFeedback && (
        <>
          <div className="fixed inset-0 pointer-events-none flex items-center justify-center z-50">
            <div className="bg-green-500/90 text-white px-6 py-3 rounded-xl text-xl font-bold shadow-2xl animate-pulse">
              ✔ Producto agregado
            </div>
          </div>
          <div className="fixed inset-0 bg-green-400/20 z-40 pointer-events-none" />
        </>
      )}

      <TicketPrinter
        ref={printerRef}
        carrito={carrito.map(item => item.tipo === 'pack' ? item : {
          ...item,
          precio: calcularLineaVenta(item, promociones, packs).precio,
          precio_original: calcularLineaVenta(item, promociones, packs).precioOriginal,
          descuento_item: calcularLineaVenta(item, promociones, packs).descuentoUnitario
        })}
        clienteNombre={cliente.nombre}
        clienteNIT={cliente.nit}
        modoPago={pagos.map(p=>`${p.metodo}: Bs ${p.monto}`).join(' + ')}
        requiereFactura={cliente.requiereFactura}
        subtotal={subtotal}
        totalDescuento={totalDescuento}
        total={totalCobrar}
        envio={envio}
        comision={comision}
        publicidad={publicidad}
        rebajas={rebajas}
        impuestos={Number(impuestosCalculados.toFixed(2))}
        cobrarImpuestos={cobrarImpuestos}
        pago={sumaPagos}
        cambio={cambio}
        ultimoTicket={undefined}
        setUltimoTicket={() => {}}
      />
    </div>
  );
}

import { NextResponse } from "next/server";
import { supabaseAdmin } from "@/lib/SupabaseAdminClient";
import { requireAdminAccess } from "@/lib/adminAccess";

export const dynamic = "force-dynamic";
export const revalidate = 0;

function parseDecimalInput(value, fallback = null) {
  if (value === undefined || value === null || value === "") return fallback;
  if (typeof value === "number") return Number.isFinite(value) ? value : fallback;
  const parsed = Number(String(value).replace(/\s/g, "").replace(",", "."));
  return Number.isFinite(parsed) ? parsed : fallback;
}

function getEffectiveVariantStock(variant) {
  const decimal = Number(variant?.stock_decimal);
  const legacy = Number(variant?.stock);
  const hasDecimal = variant?.stock_decimal !== null && variant?.stock_decimal !== undefined && variant?.stock_decimal !== "";
  return Math.max(0, hasDecimal && Number.isFinite(decimal) ? decimal : legacy || 0);
}

function hasUnitConversion(product) {
  return Boolean(
    Array.isArray(product?.unidades_alternativas) &&
      product.unidades_alternativas.length > 0 &&
      Number(product?.factor_conversion || 0) > 0
  );
}

function normalizeProductView(value) {
  const normalized = String(value || "").trim().toLowerCase();
  return /^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(normalized) ? normalized : "articulos";
}

function cleanImageUrl(image) {
  if (!image) return "";
  if (typeof image === "string") return image;
  return String(image.imagen_url || "").trim();
}

export async function POST(request) {
  try {
    const body = await request.json();
    const productId = body?.productId;
    const activeSucursalId = body?.activeSucursalId || null;
    const cambios = body?.cambios || {};
    const nuevasVariantes = Array.isArray(body?.variantes) ? body.variantes : [];
    const nuevasImagenes = Array.isArray(body?.imagenes) ? body.imagenes : [];

    if (!productId) {
      return NextResponse.json({ success: false, error: "Producto requerido" }, { status: 400 });
    }

    let productQuery = supabaseAdmin.from("productos").select("*");
    if (Number.isFinite(Number(productId))) {
      productQuery = productQuery.eq("user_id", Number(productId));
    } else {
      productQuery = productQuery.eq("id", productId);
    }
    if (activeSucursalId) productQuery = productQuery.eq("sucursal_id", activeSucursalId);

    const { data: productoActual, error: productError } = await productQuery.single();
    if (productError || !productoActual) {
      return NextResponse.json({ success: false, error: productError?.message || "Producto no encontrado" }, { status: 404 });
    }

    const auth = await requireAdminAccess(request, {
      paisId: productoActual.pais_id,
      sucursalId: productoActual.sucursal_id,
      allowedRoles: ["admin", "administracion"],
    });
    if (auth.error) return NextResponse.json({ success: false, error: auth.error }, { status: auth.status });

    const precioCompra = cambios.precio_compra === undefined
      ? parseDecimalInput(productoActual.precio_compra, 0)
      : parseDecimalInput(cambios.precio_compra, null);
    if (precioCompra === null || precioCompra < 0) {
      return NextResponse.json({ success: false, error: 'Ingresa un precio de compra valido, mayor o igual a cero.' }, { status: 400 });
    }

    const imageUrlsAfterSave = nuevasImagenes.map(cleanImageUrl).filter(Boolean);
    const requestedPrimaryImageUrl = String(cambios.primaryImageUrl || "").trim();
    const imagenPrincipal =
      (requestedPrimaryImageUrl && imageUrlsAfterSave.includes(requestedPrimaryImageUrl)
        ? requestedPrimaryImageUrl
        : "") ||
      imageUrlsAfterSave[0] ||
      "/sin-imagen.png";

    let variantesQuery = supabaseAdmin
      .from("producto_variantes")
      .select("id, producto_id, color, stock, stock_decimal, sku, precio, imagen_url, activo")
      .eq("producto_id", productoActual.user_id);
    if (activeSucursalId) variantesQuery = variantesQuery.eq("sucursal_id", activeSucursalId);
    const { data: variantesBD, error: variantesError } = await variantesQuery;
    if (variantesError) throw variantesError;

    const productHasConversion = hasUnitConversion(productoActual);
    const hasVariantsAfterSave = nuevasVariantes.length > 0;
    const variantesActualesById = new Map((variantesBD || []).map((variant) => [String(variant.id), variant]));

    for (const variant of variantesBD || []) {
      if (!nuevasVariantes.some((item) => String(item.id || "") === String(variant.id || ""))) {
        const stockActual = getEffectiveVariantStock(variant);
        if (stockActual > 0.0001) {
          return NextResponse.json(
            {
              success: false,
              error: `No se puede eliminar la variante "${variant.color || variant.id}" porque todavia tiene stock (${stockActual}). Primero transfierelo, vendelo o ajustalo desde el modulo de stock.`,
            },
            { status: 400 }
          );
        }
      }
    }

    const updatePayload = {
      nombre: cambios.nombre ?? productoActual.nombre,
      descripcion: cambios.descripcion ?? productoActual.descripcion,
      precio: parseDecimalInput(cambios.precio, parseDecimalInput(productoActual.precio, 0)),
      precio_compra: precioCompra,
      vista_producto: normalizeProductView(cambios.vista_producto ?? productoActual.vista_producto),
      category_id: cambios.category_id ? parseInt(cambios.category_id, 10) : productoActual.category_id ?? null,
      codigo_barra: productoActual.codigo_barra,
      stock: Math.max(0, Number(productoActual.stock || 0)),
      imagen_url: imagenPrincipal,
    };

    const { data: productType, error: productTypeError } = await supabaseAdmin
      .from("tipos_producto")
      .select("slug")
      .eq("slug", updatePayload.vista_producto)
      .eq("activo", true)
      .maybeSingle();
    if (productTypeError || !productType) {
      return NextResponse.json({ success: false, error: "El tipo de producto seleccionado no existe o esta desactivado" }, { status: 400 });
    }

    let updateQuery = supabaseAdmin.from("productos").update(updatePayload).eq("user_id", productoActual.user_id);
    if (activeSucursalId) updateQuery = updateQuery.eq("sucursal_id", activeSucursalId);
    const { error: updateError } = await updateQuery;
    if (updateError) throw updateError;

    for (const variant of variantesBD || []) {
      if (!nuevasVariantes.some((item) => String(item.id || "") === String(variant.id || ""))) {
        const { error } = await supabaseAdmin.from("producto_variantes").delete().eq("id", variant.id);
        if (error) throw error;
      }
    }

    for (const variant of nuevasVariantes) {
      const existingVariant = variant.id ? variantesActualesById.get(String(variant.id)) : null;
      const preservedStock = existingVariant ? getEffectiveVariantStock(existingVariant) : 0;
      const payload = {
        color: variant.color,
        stock: Math.max(0, Math.floor(preservedStock)),
        stock_decimal: preservedStock,
        sku: existingVariant?.sku || (!variant.id ? (variant.sku || variant.codigo_barra || null) : null),
        precio: parseDecimalInput(variant.precio, null),
        imagen_url: variant.imagen_url || null,
        activo: variant.activo !== undefined ? variant.activo : true,
      };

      if (variant.id) {
        const { error } = await supabaseAdmin.from("producto_variantes").update(payload).eq("id", variant.id);
        if (error) throw error;
      } else {
        const { data: insertedVariant, error } = await supabaseAdmin.from("producto_variantes").insert({
          ...payload,
          producto_id: productoActual.user_id,
          pais_id: productoActual.pais_id,
          sucursal_id: productoActual.sucursal_id,
          stock_inicial_decimal: 0,
        }).select("id").single();
        if (error) throw error;
      }
    }

    let stockTotal = updatePayload.stock;
    if (hasVariantsAfterSave) {
      let savedVariantsQuery = supabaseAdmin
        .from("producto_variantes")
        .select("stock, stock_decimal")
        .eq("producto_id", productoActual.user_id);
      if (activeSucursalId) savedVariantsQuery = savedVariantsQuery.eq("sucursal_id", activeSucursalId);
      const { data: savedVariants, error: savedVariantsError } = await savedVariantsQuery;
      if (savedVariantsError) throw savedVariantsError;
      stockTotal = (savedVariants || []).reduce((sum, variant) => sum + getEffectiveVariantStock(variant), 0);
      let resyncQuery = supabaseAdmin
        .from("productos")
        .update({ stock: stockTotal })
        .eq("user_id", productoActual.user_id);
      if (activeSucursalId) resyncQuery = resyncQuery.eq("sucursal_id", activeSucursalId);
      const { error: resyncError } = await resyncQuery;
      if (resyncError) throw resyncError;
    }

    let imagenesQuery = supabaseAdmin
      .from("producto_imagenes")
      .select("id, imagen_url")
      .eq("producto_id", productoActual.user_id);
    if (activeSucursalId) imagenesQuery = imagenesQuery.eq("sucursal_id", activeSucursalId);
    const { data: imagenesBD, error: imagenesError } = await imagenesQuery;
    if (imagenesError) throw imagenesError;

    for (const image of imagenesBD || []) {
      if (!nuevasImagenes.some((item) => String(item.id || "") === String(image.id || "") || cleanImageUrl(item) === image.imagen_url)) {
        const { error } = await supabaseAdmin.from("producto_imagenes").delete().eq("id", image.id);
        if (error) throw error;
      }
    }

    for (const image of nuevasImagenes) {
      const imagenUrl = cleanImageUrl(image);
      if (!image?.id && imagenUrl) {
        const { error } = await supabaseAdmin.from("producto_imagenes").insert({
          producto_id: productoActual.user_id,
          pais_id: productoActual.pais_id,
          sucursal_id: productoActual.sucursal_id,
          imagen_url: imagenUrl,
        });
        if (error) throw error;
      }
    }

    return NextResponse.json({
      success: true,
      totalStock: hasVariantsAfterSave ? stockTotal : updatePayload.stock,
      stockMode: hasVariantsAfterSave
        ? productHasConversion ? "variantes_con_conversion" : "variantes"
        : "producto",
    });
  } catch (error) {
    return NextResponse.json(
      { success: false, error: error?.message || "No se pudo guardar el producto" },
      { status: 400 }
    );
  }
}

