                                                                title={`Ver imagen ${idx2 + 1}`}
                                                                onClick={e => { e.currentTarget.focus({ preventScroll: true }); e.stopPropagation(); setModalImg({ urls: imagenes, index: idx2, nombre: producto.nombre }); }}
                                                            />
                                                        ))}
                                                    </div>
