                                                className="text-gray-500 hover:text-red-600 text-2xl leading-none"
                                                title="Cerrar"
                                            >
                                                ×
                                            </button>
                                        </div>
                                        <div className="mb-4">
                                            <p className="text-sm text-gray-500">Pack: <span className="font-semibold text-purple-800">{addToCartModal.pack.nombre}</span></p>
