"use client";
import { useEffect, useRef, useState } from "react";
let NextImage = null;
if (typeof window !== "undefined") {
  // Importar next/image solo en el cliente
  NextImage = require("next/image").default;
}
export default function SafeImage(props) {
  const [isClient, setIsClient] = useState(false);
  useEffect(() => { setIsClient(true); }, []);
  if (!isClient || !NextImage) return <div style={{width:props.width, height:props.height, background:'#eee', borderRadius:'50%'}} />;
  return <NextImage {...props} />;
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { resolveStorageImageUrl } from '../lib/storageImageUrl.mjs';
import { supabase } from '../lib/SupabaseClient';
import { useRouter } from 'next/navigation';
import Link from 'next/link';

export default function UserNavigation() {
  const [user, setUser] = useState(null);
  const [profile, setProfile] = useState(null);
  const [loading, setLoading] = useState(true);
  const [showDropdown, setShowDropdown] = useState(false);
  const router = useRouter();

  const loadProfile = useCallback(async (userId) => {
    try {
      const { data, error } = await supabase
        .from('profiles')
        .select('full_name, avatar_url')
        .eq('id', userId)
        .single();

      if (error && error.code !== 'PGRST116') {
        throw error;
      }

      setProfile(data);
    } catch (error) {
      // console.error('Error cargando perfil:', error);
    }
  }, []);

  const getUser = useCallback(async () => {
    try {
      const { data: { user }, error } = await supabase.auth.getUser();
      if (error) throw error;
      
      if (user) {
        setUser(user);
        await loadProfile(user.id);
      }
    } catch (error) {
      // console.error('Error obteniendo usuario:', error);
    } finally {
      setLoading(false);
    }
  }, [loadProfile]);

  useEffect(() => {
    getUser();

    const { data: { subscription } } = supabase.auth.onAuthStateChange(
      async (_event, session) => {
        if (session?.user) {
          setUser(session.user);
          await loadProfile(session.user.id);
        } else {
          setUser(null);
          setProfile(null);
        }
        setLoading(false);
      }
    );

    return () => subscription.unsubscribe();
  }, [getUser, loadProfile]);

  async function handleSignOut() {
    try {
      await supabase.auth.signOut();
      router.push('/');
    } catch (error) {
        // console.error('Error cerrando sesión:', error);
    }
  }

  if (loading) {
    return (
      <div className="bg-white shadow-sm border-b h-16 flex items-center justify-center">
        <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-blue-500"></div>
      </div>
    );
  }

  if (!user) {
    return (
      <div className="bg-white shadow-sm border-b">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <Link href="/" className="text-xl font-bold text-gray-800">
              Catálogo
            </Link>
            
            <div className="flex items-center space-x-4">
              <Link 
                href="/login"
                className="bg-blue-500 text-white px-4 py-2 rounded-md text-sm hover:bg-blue-600 transition-colors"
              >
                Iniciar Sesión
              </Link>
            </div>
          </div>
        </div>
      </div>
    );
  }

  const displayName = profile?.full_name || user.email?.split('@')[0] || 'Usuario';
  const firstName = displayName.split(' ')[0];

  return (
    <div className="bg-white shadow-sm border-b">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center h-16">
          <div className="flex items-center space-x-4">
            <Link href="/" className="text-xl font-bold text-gray-800">
              Catálogo
            </Link>
            
            <nav className="hidden md:flex items-center space-x-4">
              <Link 
                href="/productos"
                className="text-gray-600 hover:text-gray-800 transition-colors"
              >
                Productos
              </Link>
            </nav>
          </div>
          
          <div className="flex items-center space-x-4">
            <span className="text-gray-600 text-sm hidden sm:block">
              Hola, {firstName}
            </span>
            
            {/* Dropdown del perfil */}
            <div className="relative">
              <button
                onClick={() => setShowDropdown(!showDropdown)}
                className="flex items-center space-x-2 text-gray-600 hover:text-gray-800 focus:outline-none"
              >
                <div className="w-8 h-8 bg-gray-300 rounded-full flex items-center justify-center">
                  {profile?.avatar_url ? (
                    <img
                      src={resolveStorageImageUrl(profile.avatar_url)}
                      alt="Avatar"
                      className="w-8 h-8 rounded-full object-cover"
                      onError={(e) => {
                        e.target.style.display = 'none';
                        e.target.nextSibling.style.display = 'flex';
                      }}
                    />
                  ) : (
                    <span className="text-sm text-gray-500">
                      {firstName.charAt(0).toUpperCase()}
                    </span>
                  )}
                </div>
                <svg 
                  className={`w-4 h-4 transition-transform ${showDropdown ? 'rotate-180' : ''}`}
                  fill="none" 
                  stroke="currentColor" 
                  viewBox="0 0 24 24"
                >
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                </svg>
              </button>

              {showDropdown && (
                <div className="absolute right-0 mt-2 w-48 bg-white rounded-md shadow-lg border border-gray-200 z-50">
                  <div className="py-1">
                    <div className="px-4 py-2 text-sm text-gray-600 border-b">
                      {user.email}
                    </div>
                    
                    <Link
                      href="/perfil"
                      className="block px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 transition-colors"
                      onClick={() => setShowDropdown(false)}
                    >
                      Mi Perfil
                    </Link>
                    
                    <button
                      onClick={() => {
                        setShowDropdown(false);
                        handleSignOut();
                      }}
                      className="block w-full text-left px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 transition-colors"
                    >
                      Cerrar Sesión
                    </button>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* Overlay para cerrar dropdown al hacer click fuera */}
      {showDropdown && (
        <div 
          className="fixed inset-0 z-40" 
          onClick={() => setShowDropdown(false)}
        ></div>
      )}
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import Image from 'next/image';
import { resolveStorageImageUrl } from '../lib/storageImageUrl.mjs';
import { supabase } from '../lib/SupabaseClient';
import { useRouter } from 'next/navigation';

export default function UserProfile() {
  const [user, setUser] = useState(null);
  const [perfil, setPerfil] = useState(null);
  const [loading, setLoading] = useState(true);
  const [editando, setEditando] = useState(false);
  const [authorized, setAuthorized] = useState(false);
  const [message, setMessage] = useState('');
  const [updating, setUpdating] = useState(false);
  const [uploadingFoto, setUploadingFoto] = useState(false);
  const router = useRouter();

  // Estados para el formulario
  const [nombre, setNombre] = useState("");
  const [nitCi, setNitCi] = useState("");
  const [telefono, setTelefono] = useState("");
  const [fotoPerfil, setFotoPerfil] = useState("");
  const [bio, setBio] = useState("");

  useEffect(() => {
    const getUser = async () => {
      try {
        // 1. Verificar que el usuario esté autenticado
        const { data: { session }, error: sessionError } = await supabase.auth.getSession();
        
        if (sessionError || !session?.user) {
          // console.log('❌ No hay sesión válida, redirigiendo...');
          router.push('/login');
          return;
        }

        const currentUser = session.user;
        setUser(currentUser);

        // 2. SEGURIDAD: Solo permitir acceso a SU PROPIO perfil
        const { data: perfilData, error: perfilError } = await supabase
          .from('perfiles')
          .select('*')
          .eq('id', currentUser.id)
          .single();
        
        if (perfilError && perfilError.code !== 'PGRST116') {
          // console.error('❌ Error cargando perfil:', perfilError);
        }

        // 3. Establecer datos seguros
        const finalPerfil = perfilData || {
          id: currentUser.id,
          email: currentUser.email,
          nombre: '',
          telefono: '',
          nit_ci: '',
          rol: 'cliente',
          foto_perfil: null,
          bio: ''
        };
        
        setPerfil(finalPerfil);
        
        // Cargar datos en el formulario
        setNombre(finalPerfil.nombre || '');
        setNitCi(finalPerfil.nit_ci || '');
        setTelefono(finalPerfil.telefono || '');
        setFotoPerfil(finalPerfil.foto_perfil || '');
        setBio(finalPerfil.bio || '');
        
        setAuthorized(true);
        
      } catch (error) {
        // console.error('❌ Error de autorización:', error);
        router.push('/login');
      } finally {
        setLoading(false);
      }
    };
    
    getUser();
  }, [router]);

  const handleFileUpload = async (event) => {
    const file = event.target.files[0];
    if (!file) return;

    if (!file.type.startsWith('image/')) {
      setMessage("❌ Solo se permiten archivos de imagen");
      return;
    }

    if (file.size > 2 * 1024 * 1024) {
      setMessage("❌ La imagen debe ser menor a 2MB");
      return;
    }

    setUploadingFoto(true);
    setMessage("");

    try {
      const fileExt = file.name.split('.').pop();
      const fileName = `${user.id}/${Date.now()}.${fileExt}`;

      const { error } = await supabase.storage
        .from('perfiles')
        .upload(fileName, file, { cacheControl: '3600', upsert: true });

      if (error) throw error;

      const { data: { publicUrl } } = supabase.storage
        .from('perfiles')
        .getPublicUrl(fileName);

      setFotoPerfil(publicUrl);
      setMessage("✅ Foto subida correctamente");
      setTimeout(() => setMessage(""), 3000);
    } catch (error) {
      setMessage("❌ Error al subir foto: " + error.message);
    } finally {
      setUploadingFoto(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setUpdating(true);
    setMessage("");
    
    try {
      // Verificar si el perfil existe
      const { data: perfilExistente } = await supabase
        .from("perfiles")
        .select("id")
        .eq("id", user.id)
        .maybeSingle();
      
      const datosActualizar = {
        nombre: nombre.trim(),
        nit_ci: nitCi.trim(),
        telefono: telefono.trim(),
        foto_perfil: fotoPerfil || null,
        bio: bio.trim()
      };
      
      let result;
      if (perfilExistente) {
        // ACTUALIZAR perfil existente
        result = await supabase
          .from("perfiles")
          .update(datosActualizar)
          .eq("id", user.id)
          .select();
      } else {
        // CREAR nuevo perfil
        result = await supabase
          .from("perfiles")
          .insert({
            id: user.id,
            ...datosActualizar,
            rol: 'cliente'
          })
          .select();
      }
      
      if (result.error) {
        setMessage("❌ Error: " + result.error.message);
      } else {
        setMessage("✅ Perfil guardado correctamente");
        // Actualizar el estado del perfil
        setPerfil(prev => ({ ...prev, ...datosActualizar }));
        setEditando(false);
        setTimeout(() => setMessage(""), 3000);
      }
    } catch (error) {
      setMessage("❌ Error inesperado: " + error.message);
    }
    
    setUpdating(false);
  };

  // SEGURIDAD: Loading state
  if (loading) {
    return (
      <div className="flex justify-center items-center min-h-[60vh]">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto mb-4"></div>
          <p className="text-gray-600">Cargando perfil...</p>
        </div>
      </div>
    );
  }

  // SEGURIDAD: Bloquear acceso no autorizado
  if (!user || !authorized) {
    return (
      <div className="flex justify-center items-center min-h-[60vh]">
        <div className="text-center p-8">
          <div className="text-red-600 text-6xl mb-4">🔒</div>
          <h2 className="text-2xl font-bold text-gray-800 mb-2">Acceso Denegado</h2>
          <p className="text-gray-600 mb-4">No tienes permisos para acceder a esta página.</p>
          <button 
            onClick={() => router.push('/login')}
            className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg"
          >
            Iniciar Sesión
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto p-6">
      {/* Header */}
      <div className="bg-gradient-to-r from-blue-600 to-purple-600 text-white rounded-lg p-6 mb-6">
        <div className="flex items-center gap-4">
          <div className="bg-white/20 rounded-full p-3">
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
            </svg>
          </div>
          <div>
            <h1 className="text-2xl font-bold">Mi Perfil</h1>
            <p className="text-blue-100">
              {editando ? "Editando información personal" : "Información personal"}
            </p>
          </div>
        </div>
      </div>

      {message && (
        <div className={`mb-6 p-4 rounded-lg text-center font-medium ${
          message.includes('❌') 
            ? 'bg-red-50 border border-red-200 text-red-700' 
            : 'bg-green-50 border border-green-200 text-green-700'
        }`}>
          {message}
        </div>
      )}

      <div className="bg-white rounded-lg shadow-sm border p-6">
        {!editando ? (
          // MODO VISUALIZACIÓN
          <div className="space-y-6">
            <div className="flex items-center justify-between">
              <h2 className="text-lg font-semibold text-gray-800 flex items-center gap-2">
                <svg className="w-5 h-5 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
                </svg>
                Mi Información Personal
              </h2>
              <button
                onClick={() => setEditando(true)}
                className="bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded-lg font-medium transition-colors flex items-center gap-2"
              >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" />
                </svg>
                Editar Perfil
              </button>
            </div>

            {/* Información actual del perfil */}
            <div className="grid md:grid-cols-2 gap-8">
              {/* Foto de perfil */}
              <div className="text-center">
                <h3 className="text-sm font-medium text-gray-700 mb-3">Foto de Perfil</h3>
                {perfil?.foto_perfil ? (
                  <Image
                    src={resolveStorageImageUrl(perfil.foto_perfil)}
                    alt="Foto de perfil"
                    width={128}
                    height={128}
                    className="w-32 h-32 rounded-full mx-auto object-cover border-4 border-blue-200 shadow-lg"
                  />
                ) : (
                  <div className="w-32 h-32 rounded-full mx-auto bg-gray-200 flex items-center justify-center border-4 border-gray-300">
                    <svg className="w-16 h-16 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
                    </svg>
                  </div>
                )}
                <p className="text-sm text-gray-500 mt-2">
                  {perfil?.foto_perfil ? "Foto actual" : "Sin foto de perfil"}
                </p>
              </div>

              {/* Información personal */}
              <div className="space-y-6">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Nombre Completo
                  </label>
                  <div className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-lg text-gray-900">
                    {perfil?.nombre || "No especificado"}
                  </div>
                </div>
                
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    NIT/CI
                  </label>
                  <div className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-lg text-gray-900">
                    {perfil?.nit_ci || "No especificado"}
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Email
                  </label>
                  <div className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-lg text-gray-900">
                    {user?.email || "No especificado"}
                  </div>
                  <p className="text-xs text-gray-500 mt-1">
                    El email se gestiona desde la configuración de cuenta
                  </p>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Teléfono
                  </label>
                  <div className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-lg text-gray-900">
                    {perfil?.telefono || "No especificado"}
                  </div>
                </div>
              </div>
            </div>

            {/* Biografía */}
            {perfil?.bio && (
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Biografía
                </label>
                <div className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-lg text-gray-900">
                  {perfil.bio}
                </div>
              </div>
            )}
          </div>
        ) : (
          // MODO EDICIÓN
          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <h2 className="text-lg font-semibold text-gray-800 flex items-center gap-2">
                <svg className="w-5 h-5 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" />
                </svg>
                Editando Mi Perfil
              </h2>
              <button
                onClick={() => setEditando(false)}
                className="bg-gray-500 hover:bg-gray-600 text-white px-4 py-2 rounded-lg font-medium transition-colors flex items-center gap-2"
              >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
                Cancelar
              </button>
            </div>
            
            {/* Formulario de edición */}
            <div className="space-y-6">
              {/* Foto de perfil */}
              <div className="text-center">
                <div className="mb-4">
                  {fotoPerfil ? (
                    <Image
                      src={resolveStorageImageUrl(fotoPerfil)}
                      alt="Foto de perfil"
                      width={128}
                      height={128}
                      className="w-32 h-32 rounded-full mx-auto object-cover border-4 border-blue-200 shadow-lg"
                    />
                  ) : (
                    <div className="w-32 h-32 rounded-full mx-auto bg-gray-200 flex items-center justify-center border-4 border-gray-300">
                      <svg className="w-16 h-16 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
                      </svg>
                    </div>
                  )}
                </div>
                
                <div className="relative inline-block">
                  <input
                    type="file"
                    accept="image/*"
                    onChange={handleFileUpload}
                    className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                    disabled={uploadingFoto}
                  />
                  <button
                    type="button"
                    disabled={uploadingFoto}
                    className="bg-blue-500 hover:bg-blue-600 disabled:bg-gray-400 text-white px-6 py-2 rounded-lg font-medium transition-colors"
                  >
                    {uploadingFoto ? "Subiendo..." : fotoPerfil ? "Cambiar Foto" : "Subir Foto"}
                  </button>
                </div>
                <p className="text-xs text-gray-500 mt-2">Máximo 2MB • JPG, PNG, GIF</p>
              </div>

              <form onSubmit={handleSubmit} className="space-y-6">
                <div className="grid md:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Nombre Completo *
                    </label>
                    <input
                      type="text"
                      placeholder="Escribe tu nombre completo"
                      value={nombre}
                      onChange={e => setNombre(e.target.value)}
                      className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-gray-900 placeholder-gray-500"
                      required
                    />
                  </div>
                  
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Teléfono *
                    </label>
                    <input
                      type="tel"
                      placeholder="Ej: 70123456"
                      value={telefono}
                      onChange={e => setTelefono(e.target.value)}
                      className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-gray-900 placeholder-gray-500"
                      required
                    />
                  </div>
                  
                  <div className="md:col-span-2">
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      NIT/CI *
                    </label>
                    <input
                      type="text"
                      placeholder="Número de identificación"
                      value={nitCi}
                      onChange={e => setNitCi(e.target.value)}
                      className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-gray-900 placeholder-gray-500"
                      required
                    />
                  </div>

                  <div className="md:col-span-2">
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Biografía
                    </label>
                    <textarea
                      placeholder="Cuéntanos algo sobre ti..."
                      value={bio}
                      onChange={e => setBio(e.target.value)}
                      rows="4"
                      className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-gray-900 placeholder-gray-500"
                    />
                  </div>
                </div>
                
                <div className="text-center">
                  <button
                    type="submit"
                    disabled={updating || !nombre.trim() || !nitCi.trim() || !telefono.trim()}
                    className="bg-green-600 hover:bg-green-700 disabled:bg-gray-400 text-white font-bold py-3 px-8 rounded-lg transition-colors text-lg"
                  >
                    {updating ? "Guardando..." : "💾 Editar Perfil"}
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import React from "react";
import ProductThumbnail from "./ProductThumbnail";
import { calcularPrecioConPromocion } from "@/lib/promociones";
import type { Pack, Producto } from "@/hooks/useCarrito";

interface Props {
  busqueda: string;
  onChange: (v: string) => void;
  onSubmit: () => void;
  searchResults: Producto[];
  searchLoading: boolean;
  imagenes: Record<string, string[]>;
  onAdd: (prod: Producto) => void;
  showSuggestions: boolean;
  setShowSuggestions: (b: boolean) => void;
  packResults?: Pack[];
  onAddPack?: (pack: Pack) => void;
  promociones?: any[];
}

export default function BuscadorProductos({
  busqueda,
  onChange,
  onSubmit,
  searchResults,
  searchLoading,
  imagenes,
  onAdd,
  showSuggestions,
  setShowSuggestions,
  packResults = [],
  onAddPack,
  promociones = [],
}: Props) {
  const getEffectiveVariantStock = (v: { stock?: number; stock_decimal?: number }) => {
    const decimal = Number(v.stock_decimal);
    const legacy = Number(v.stock);
    return Math.max(0, Number.isFinite(decimal) && decimal > 0 ? decimal : legacy || 0);
  };

  const formatQuantity = (value: number) => {
    const num = Number(value);
    if (!Number.isFinite(num)) return "0";
    return Number(num.toFixed(3)).toString();
  };

  const getConversionInfo = (p: Producto) => {
    const stockBase = Math.max(0, Number((p as any).stock ?? 0));
    const factor = Number((p as any).factor_conversion || 0);
    const base = String((p as any).unidad_base || "unidad");
    const alternativas = Array.isArray((p as any).unidades_alternativas)
      ? (p as any).unidades_alternativas.filter((u: string) => u && u !== base)
      : [];
    const alt = alternativas[0];
    const hasConversion = Boolean(alt && Number.isFinite(factor) && factor > 0);
    return { stockBase, factor, base, alternativas, alt, hasConversion };
  };

  const handleAddClick = (p: Producto) => {
    const { stockBase, factor, base, alternativas, alt: unidadAlternativa, hasConversion } = getConversionInfo(p);
    const unidadesBase = Array.isArray((p as any).unidades_disponibles)
      ? (p as any).unidades_disponibles
      : (p as any).unidad_base && (p as any).unidades_alternativas
        ? [
            (p as any).unidad_base,
            ...alternativas,
          ]
        : [(p as any).unidad_base || "unidad"];
    const unidades =
      hasConversion
        ? [
            ...(stockBase >= 1 ? [base] : []),
            ...(stockBase * factor > 0 ? [unidadAlternativa] : []),
          ]
        : unidadesBase;

    const unidadSeleccionada = unidades[0] || base;
    const cantidadBase = unidadSeleccionada === base || !factor || factor <= 0
      ? 1
      : 1 / factor;

    onAdd({
      ...p,
      cantidad: 1,
      cantidad_base: cantidadBase,
      cantidad_display: 1,
      unidad: unidadSeleccionada,
      unidad_base: base,
      unidades_disponibles: unidades,
    });
    setShowSuggestions(false);
    onChange("");
  };

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        onSubmit();
      }}
      className="mb-4 mt-8 flex flex-col gap-2 sm:flex-row"
    >
      <div className="relative flex-1">
        <input
          className="w-full rounded border border-gray-900 bg-white px-3 py-2 text-gray-900 placeholder-gray-700 focus:border-gray-900 focus:ring focus:ring-gray-900/30"
          placeholder="Escanea o ingresa código de barra / nombre / categoría (Ctrl+B/cmd+B)"
          value={busqueda}
          onChange={(e) => {
            onChange(e.target.value);
            setShowSuggestions(true);
          }}
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              e.preventDefault();
              onSubmit();
            }
          }}
          onFocus={() => {
            setShowSuggestions(true);
            if (!busqueda.trim()) onSubmit();
          }}
          onBlur={() => {
            setTimeout(() => setShowSuggestions(false), 150);
          }}
        />

        {showSuggestions && (
          <ul className="absolute left-0 right-0 z-50 mt-2 max-h-80 overflow-auto rounded border border-gray-200 bg-white shadow">
            {searchLoading && <li className="px-3 py-2 text-sm text-gray-500">Buscando...</li>}

            {!searchLoading &&
              packResults.length > 0 &&
              packResults.slice(0, 10).map((pack) => (
                <li
                  key={`pack-${pack.id}`}
                  className="flex items-center justify-between gap-3 border-b border-purple-100 px-3 py-2 hover:bg-purple-50"
                >
                  <div className="flex items-center gap-3 truncate">
                    <div className="flex h-10 w-10 items-center justify-center rounded bg-purple-100 text-2xl">
                      📦
                    </div>
                    <div className="truncate">
                      <div className="truncate text-sm font-bold text-purple-800">{pack.nombre}</div>
                      <div className="text-xs text-purple-700">
                        Incluye:{" "}
                        {(pack.pack_productos ?? [])
                          .map((item) => `${item.cantidad}x ${item.productos.nombre}`)
                          .join(", ")}
                      </div>
                      <div className="text-xs text-purple-600">
                        Bs {Number(pack.precio_pack).toFixed(2)}
                        <span className="ml-2 text-xs text-purple-500">Pack especial</span>
                      </div>
                    </div>
                  </div>
                  <button
                    type="button"
                    onMouseDown={(e) => {
                      e.preventDefault();
                      onAddPack && onAddPack(pack);
                    }}
                    className="rounded bg-purple-700 px-2 py-1 text-sm font-semibold text-white hover:bg-purple-800"
                    title="Agregar pack al carrito"
                  >
                    Agregar pack
                  </button>
                </li>
              ))}

            {!searchLoading &&
              searchResults.slice(0, 20).map((p) => {
                const precioInfo = calcularPrecioConPromocion(p, promociones);
                return (
                  <li
                    key={String(p.user_id ?? `tmp-${p.nombre}`)}
                    className="flex items-center justify-between gap-3 px-3 py-2 hover:bg-gray-100"
                  >
                  <div className="flex items-center gap-3 truncate">
                    <div className="flex h-10 w-10 flex-shrink-0 items-center justify-center overflow-hidden rounded bg-gray-50">
                      <ProductThumbnail name={p.nombre} size={40} sources={[
                        p.variantes?.find(v => String(v.id ?? v.variante_id) === String(p.variante_id))?.imagen_url,
                        p.imagen_url, ...(imagenes[String(p.user_id)] || [])
                      ]} />
                    </div>
                    <div className="truncate">
                      <div className="truncate text-sm font-medium">{p.nombre}</div>
                      <div className="text-xs text-gray-400">
                        {p.categorias?.categori || "Sin categoría"}
                      </div>
                      <div className="text-xs text-gray-500">
                        {(() => {
                          const stockBase = Number(p.stock || 0);
                          if (
                            Array.isArray((p as any).unidades_alternativas) &&
                            (p as any).unidades_alternativas.length > 0 &&
                            Number((p as any).factor_conversion) > 0 &&
                            (p as Producto).unidad_base
                          ) {
                            const alt = (p as any).unidades_alternativas[0];
                            const stockAlt = stockBase * Number((p as any).factor_conversion);
                            if (stockBase === 0 && stockAlt > 0) {
                              return <span>Stock: {formatQuantity(stockAlt)} {alt}</span>;
                            }
                            if (stockBase > 0) {
                              return (
                                <span>
                                  Stock: {formatQuantity(stockBase)} {(p as Producto).unidad_base} ({formatQuantity(stockAlt)} {alt})
                                </span>
                              );
                            }
                            return <span>Stock: 0</span>;
                          }
                          return <span>Stock: {formatQuantity(stockBase)}</span>;
                        })()}
                      </div>
                      {p.color && (
                        <div className="text-xs font-semibold text-green-600">
                          Color preseleccionado: {p.color}
                        </div>
                      )}
                    </div>
                  </div>

                  <div className="flex flex-col items-end gap-1">
                    <div className="text-right text-sm">
                      {precioInfo.tienePromocion && (
                        <div className="text-xs text-gray-800 line-through decoration-gray-800">
                          Bs {precioInfo.precioOriginal.toFixed(2)}
                        </div>
                      )}
                      <div className={`font-bold ${precioInfo.tienePromocion ? 'text-green-600' : 'text-blue-700'}`}>
                        Bs {precioInfo.precioFinal.toFixed(2)}
                      </div>
                      {precioInfo.tienePromocion && (
                        <div className="mt-1 flex items-center justify-end gap-1.5">
                          <span className="rounded-full bg-red-500 px-2 py-1 text-[11px] font-bold leading-none text-gray-950">
                            -{precioInfo.porcentajeDescuento}%
                          </span>
                        </div>
                      )}
                    </div>
                    {p.variante_id ? (
                      <button
                        type="button"
                        onMouseDown={(e) => {
                          e.preventDefault();
                          handleAddClick({
                            ...p,
                            variante_id: p.variante_id,
                            color: p.color || "Sin color",
                            precio: Number(p.precio ?? 0),
                            stock: Number(p.stock || 0),
                          });
                        }}
                        className="rounded bg-green-600 px-2 py-1 text-sm font-semibold text-white hover:bg-green-700"
                        title="Agregar producto con color preseleccionado"
                      >
                        Agregar
                      </button>
                    ) : Array.isArray(p.variantes) && p.variantes.length > 0 ? (
                      <div className="flex max-w-56 flex-wrap justify-end gap-1">
                        {p.variantes
                          .filter((v) => {
                            const { stockBase, hasConversion } = getConversionInfo(p);
                            return hasConversion ? stockBase > 0 : getEffectiveVariantStock(v) > 0;
                          })
                          .slice(0, 6)
                          .map((v, idx) => {
                            const variantId = v.variante_id ?? v.id;
                            const variantStock = getEffectiveVariantStock(v);
                            const { stockBase, factor, alt, hasConversion } = getConversionInfo(p);
                            const displayStock = hasConversion
                              ? `${formatQuantity(stockBase * factor)} ${alt}`
                              : formatQuantity(variantStock);
                            return (
                              <button
                                key={`${p.user_id}-${String(variantId)}-${idx}`}
                                type="button"
                                onMouseDown={(e) => {
                                  e.preventDefault();
                                  handleAddClick({
                                    ...p,
                                    variante_id: variantId,
                                    color: v.color || "Sin color",
                                    precio: Number(v.precio ?? p.precio ?? 0),
                                    stock: hasConversion ? stockBase : variantStock,
                                  });
                                }}
                                className="rounded bg-green-600 px-2 py-1 text-xs text-white hover:bg-green-700"
                                title={`Agregar color ${v.color || "Sin color"}`}
                              >
                                {v.color || "Color"} ({displayStock})
                              </button>
                            );
                          })}
                      </div>
                    ) : (
                      <button
                        type="button"
                        onMouseDown={(e) => {
                          e.preventDefault();
                          handleAddClick(p);
                        }}
                        className="rounded bg-green-600 px-2 py-1 text-sm text-white hover:bg-green-700"
                      >
                        Agregar
                      </button>
                    )}
                  </div>
                </li>
                );
              })}

            {!searchLoading && searchResults.length === 0 && packResults.length === 0 && (
              <li className="px-3 py-2 text-sm text-gray-500">No hay coincidencias</li>
            )}
          </ul>
        )}
      </div>
      <button
        type="submit"
        className="rounded bg-gray-900 px-4 py-2 font-bold text-white shadow hover:bg-gray-800"
      >
        Agregar
      </button>
    </form>
  );
}

"use client";
import { calcularLineaVenta } from '../../lib/cartPricing';
import React from 'react';
import ProductThumbnail from './ProductThumbnail';
import { PrecioConPromocion, calcularPrecioConPromocion } from '../../lib/promociones';
import { calcularDescuentoPack } from '../../lib/packs';
import { CartItem, Pack, PackProduct } from '../../hooks/useCarrito';
import CantidadConUnidadInput from '../CantidadConUnidadInput';

interface Props {
  carrito: CartItem[];
  imagenes: Record<string, string[]>;
  quitar: (user_id: string | number) => void;
  cambiarCantidad: (user_id: string | number, cant: number) => void;
  cambiarUnidadYCantidad: (user_id: string | number, cantBase: number, unidad?: string, cantidadDisplay?: number) => void;
  cambiarDescuento: (key: string | number, valor: number) => void;
  subtotal: number;
  totalDescuento: number;
  total: number;
  envio?: number;
  comision?: number;
  publicidad?: number;
  rebajas?: number;
  impuestos?: number;
  totalCobrar?: number;
  modoPago: string;
  pago: number;
  cambio: number;
  packs: Pack[];
  promociones: any[];
}


export default function CarritoPanel({
  carrito,
  imagenes,
  quitar,
  cambiarCantidad,
  cambiarUnidadYCantidad,
  cambiarDescuento,
  subtotal,
  totalDescuento,
  total,
  envio = 0,
  comision = 0,
  publicidad = 0,
  rebajas = 0,
  impuestos = 0,
  totalCobrar = total,
  packs,
  promociones
}: Props) {
  const getBaseQuantity = (item: CartItem) => Number(item.cantidad_base ?? item.cantidad ?? 0);
  const getDisplayQuantity = (item: CartItem) => Number(item.cantidad_display ?? item.cantidad ?? 0);

  return (
    <div>
      {carrito.length === 0 ? (
        <div className="text-gray-900">No hay productos en el carrito.</div>
      ) : (
        <div className="overflow-x-auto">
          <table className="w-full text-sm md:text-base bg-white rounded-xl shadow-xl border border-gray-900 text-center">
            <thead>
              <tr className="bg-gray-200 text-gray-900">
                <th className="p-2">Imagen</th>
                <th className="p-2">Nombre</th>
                <th className="p-2">Cantidad</th>
                <th className="p-2">Precio</th>
                <th className="p-2">Descuento</th>
                <th className="p-2">Subtotal</th>
                <th className="p-2">Quitar</th>
              </tr>
            </thead>
            <tbody>
              {carrito.map(item => {
                if (item.tipo === 'pack') {
                  const pack = item.pack_data || packs.find((p) => p.id === item.pack_id);
                  if (!pack) return null;
                  const packKey = item.cart_key || `pack:${String(item.pack_id ?? item.user_id)}`;
                  const { descuentoPorcentaje, descuentoAbsoluto } = calcularDescuentoPack(pack);
                  return (
                    <tr key={packKey} className="bg-purple-50 border-2 border-purple-200">
                      <td className="p-2 text-center align-middle">
                        <div className="h-14 w-14 mx-auto bg-purple-100 rounded-lg border-2 border-purple-300 flex items-center justify-center shadow-sm">
                          <span className="text-2xl">📦</span>
                        </div>
                      </td>
                      <td className="p-2 text-left font-bold text-gray-900">
                        <div className="font-bold text-purple-800">📦 {pack.nombre}</div>
                        <div className="text-xs text-purple-600">{pack.descripcion || 'Pack especial'}</div>
                        <div className="text-xs text-gray-600 mt-1">
                          Incluye: {pack.pack_productos?.map((packItem: PackProduct) => 
                            `${packItem.cantidad}x ${packItem.productos.nombre}`
                          ).join(', ') || 'Productos del pack'}
                        </div>
                        <button onClick={() => quitar(packKey)} className="mt-2 bg-red-700 hover:bg-red-800 text-white px-3 py-1 rounded font-bold text-xs">Quitar</button>
                      </td>
                      <td className="p-2">
                        <input
                          type="number"
                          min={1}
                          value={item.cantidad}
                          onChange={e => cambiarCantidad(packKey, Number(e.target.value))}
                          className="w-16 border border-gray-900 rounded px-2 py-1 text-gray-900"
                        />
                      </td>
                      <td className="p-2">
                        <div className="text-center">
                          <div className="line-through text-gray-500 text-sm">Bs {pack.precio_individual?.toFixed(2)}</div>
                          <div className="text-purple-700 font-bold text-lg">Bs {pack.precio_pack?.toFixed(2)}</div>
                        </div>
                      </td>
                      <td className="p-2">
                        <div className="text-center">
                          <div className="text-red-600 font-bold">-Bs {(descuentoAbsoluto * item.cantidad).toFixed(2)}</div>
                          <div className="text-red-600 text-sm font-bold">-{descuentoPorcentaje.toFixed(0)}% PACK</div>
                        </div>
                      </td>
                      <td className="p-2 text-purple-700 font-bold text-lg">
                        Bs {(pack.precio_pack * item.cantidad).toFixed(2)}
                      </td>
                      <td className="p-2">
                        <button onClick={() => quitar(packKey)} className="bg-red-700 hover:bg-red-800 text-white px-3 py-1 rounded font-bold">Quitar</button>
                      </td>
                    </tr>
                  );
                }
                const precioInfo = calcularPrecioConPromocion(item, promociones);
                const linea = calcularLineaVenta(item, promociones, packs);
                const itemKey = item.cart_key || `prod:${String(item.user_id)}:${String(item.variante_id ?? 'default')}`;
                // Lógica para imagen: variante > item.imagen_url > imagenes[1] > imagenes[0]
                let imagenUrl = null;
                if (item.variante_id && item.variantes) {
                  const variante = item.variantes.find(v => String(v.id || v.variante_id) === String(item.variante_id));
                  if (variante && variante.imagen_url) imagenUrl = variante.imagen_url;
                }
                if (!imagenUrl && item.imagen_url) imagenUrl = item.imagen_url;
                if (!imagenUrl && imagenes[String(item.user_id)]?.[0]) imagenUrl = imagenes[String(item.user_id)][0];
                const unidadesDisponibles = Array.isArray(item.unidades_disponibles) && item.unidades_disponibles.length > 0
                  ? item.unidades_disponibles
                  : (item.unidad_base && item.unidades_alternativas)
                    ? [item.unidad_base, ...(item.unidades_alternativas || []).filter((u) => u !== item.unidad_base)]
                    : [item.unidad_base].filter(Boolean);
                const hasUnitConversion = unidadesDisponibles.length > 0 && item.factor_conversion && Number(item.factor_conversion) > 0;
                return (
                  <tr key={itemKey}>
                    <td className="p-2 text-center align-middle">
                      <ProductThumbnail name={item.nombre} sources={[
                        imagenUrl, item.imagen_url, ...(imagenes[String(item.user_id)] || [])
                      ]} />
                    </td>
                    <td className="p-2 text-left font-bold text-gray-900">
                      <div>{item.nombre}</div>
                      {item.color && <div className="text-xs font-semibold text-blue-700">Color: {item.color}</div>}
                      <button
                        onClick={() => quitar(itemKey)}
                        className="mt-2 bg-red-700 hover:bg-red-800 text-white px-3 py-1 rounded font-bold text-xs"
                      >
                        Quitar
                      </button>
                    </td>
                    <td className="p-2">
                      {hasUnitConversion ? (
                        <CantidadConUnidadInput
                          unidadBase={item.unidad_base}
                          factorConversion={Number(item.factor_conversion) || 1}
                          initialUnidad={item.unidad || item.unidad_base}
                          initialCantidad={getDisplayQuantity(item)}
                          unidadesDisponibles={unidadesDisponibles}
                          stockBase={Number(item.stock) || 0}
                          onChange={(valorBase: number, unidad: string, cantidad: number) => {
                            cambiarUnidadYCantidad(itemKey, valorBase, unidad, cantidad);
                          }}
                          min={0.01}
                          precision={3}
                        />
                      ) : (
                        <input
                          type="number"
                          min={1}
                          max={Number.isFinite(Number(item.stock)) ? Math.max(1, Number(item.stock)) : undefined}
                          value={getDisplayQuantity(item)}
                          onChange={e => cambiarCantidad(itemKey, Number(e.target.value))}
                          className="w-16 border border-gray-900 rounded px-2 py-1 text-gray-900"
                        />
                      )}
                    </td>
                    <td className="p-2">
                      <PrecioConPromocion 
                        producto={item} 
                        promociones={promociones}
                        compact={true}
                        className="text-gray-900 font-bold"
                      />
                    </td>
                    <td className="p-2">
                      <label className="block text-xs text-gray-700">
                        Rebaja Bs por unidad
                        <input type="number" min={0} max={linea.maxManual} step="0.01"
                          aria-label={`Descuento en Bs de ${item.nombre}`}
                          value={linea.manualUnitario}
                          disabled={linea.maxManual <= 0}
                          title={linea.motivoLimite}
                          onChange={e => cambiarDescuento(itemKey, Number(e.target.value))}
                          className="mt-1 w-24 border border-gray-900 rounded px-2 py-2 text-base text-gray-900" />
                      </label>
                      <p className="mt-1 text-xs text-gray-600">
                        {linea.maxManual > 0 ? `Max. Bs ${linea.maxManual.toFixed(2)} por unidad (25% / costo)` : linea.motivoLimite}
                      </p>
                      {linea.manual > 0 && <p className="text-xs text-blue-700">Rebaja total: Bs {linea.manual.toFixed(2)}</p>}
                      {precioInfo.tienePromocion ? (
                        <div className="text-center">
                          <div className="text-red-600 font-bold">-Bs {((precioInfo?.descuento||0) * getBaseQuantity(item)).toFixed(2)}</div>
                          
                          <div className="text-red-600 text-sm">-{precioInfo.porcentajeDescuento}%</div>
                        </div>
                      ) : (
                        <span className="text-gray-500 text-xs">Sin promocion</span>
                      )}
                    </td>
                    <td className="p-2 text-gray-900 font-bold">
                      Bs {linea.total.toFixed(2)}
                    </td>
                    <td className="p-2">
                      <button 
                        onClick={() => quitar(itemKey)} 
                        className="bg-red-700 hover:bg-red-800 text-white px-3 py-1 rounded font-bold"
                      >
                        Quitar
                      </button>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
          <div className="mt-4 text-right text-xl font-bold text-gray-900">
            <div>Subtotal: Bs {subtotal.toFixed(2)}</div>
            {totalDescuento > 0 && <div className="text-blue-700">Descuentos: -Bs {totalDescuento.toFixed(2)}</div>}
            {Number(envio) > 0 && <div className="text-blue-700">Envio: +Bs {Number(envio).toFixed(2)}</div>}
            {Number(comision) > 0 && <div className="text-blue-700">Comision: +Bs {Number(comision).toFixed(2)}</div>}
            {Number(impuestos) > 0 && <div className="text-blue-700">Impuestos: +Bs {Number(impuestos).toFixed(2)}</div>}
            {Number(publicidad) > 0 && <div className="text-blue-700">Publicidad: -Bs {Number(publicidad).toFixed(2)}</div>}
            {Number(rebajas) > 0 && <div className="text-blue-700">Rebajas: -Bs {Number(rebajas).toFixed(2)}</div>}
            <div className="text-2xl">Total a cobrar: Bs {Number(totalCobrar).toFixed(2)}</div>
          </div>
          {!carrito.length && null}
        </div>
      )}
    </div>
  );
}

