import { calcularLineaVenta } from '../lib/cartPricing';
import { useState, useEffect, useCallback, useMemo } from 'react';
import { calcularPrecioConPromocion } from '../lib/promociones';
import { usePacks, calcularDescuentoPack } from '../lib/packs';
import { priceCatalogItem } from '../lib/catalogCartPricing.mjs';
import { getBrowserItem, setBrowserItem, removeBrowserItem } from '../lib/browserStorage';

export interface Producto {
  user_id: string | number | null; // For packs, this should be null
  variante_id?: string | number;
  stock?: number;
  color?: string;
  cart_key?: string;
  variantes?: Array<{
    variante_id?: string | number;
    id?: string | number;
    color?: string;
    stock?: number;
    stock_decimal?: number;
    precio?: number;
    imagen_url?: string;
  }>;
  codigo_barra?: string;
  codigo?: string;
  nombre: string;
  precio: number;
  precio_compra?: number;
  imagen_url?: string;
  precio_pack?: number;
  precio_individual?: number;
  precio_original?: number;
  descuento?: number;
  productos?: PackProduct[];
  cantidad?: number;
  cantidad_base?: number;
  cantidad_display?: number;
  unidad?: string;
  unidad_base?: string;
  unidades_alternativas?: string[];
  unidades_disponibles?: string[];
  factor_conversion?: number;
  tipo?: 'pack' | 'producto';
  pack_id?: string | number;
  pack_data?: Pack;
  categorias?: { categori?: string };
}

export interface PackProduct {
  cantidad: number;
  variante_id?: string | number;
  productos: {
    user_id: string;
    nombre: string;
    precio: number;
    producto_variantes?: Array<{
      id?: string | number;
      color?: string;
      precio?: number;
      stock?: number;
      stock_decimal?: number;
      imagen_url?: string;
      sku?: string;
      codigo_barra?: string;
    }>;
  };
}

export interface Pack {
  id: string | number;
  nombre: string;
  descripcion?: string;
  precio_pack: number;
  precio_individual?: number;
  pack_productos?: PackProduct[];
}

export interface PromocionAplicada {
  tipo?: string;
  valor?: number;
  descripcion?: string;
}

export interface CartItem extends Producto {
  descuento_manual?: number;
  cantidad: number;
  cantidad_base?: number;
  cantidad_display?: number;
  unidad?: string; // unidad seleccionada por el usuario (ej: metro, rollo, litro)
  precio: number;
  precio_original?: number;
  descuento_item?: number;
  promocion_aplicada?: PromocionAplicada | null;
  pack_id?: string | number;
  pack_data?: Pack;
  descuento_pack?: number;
  stock?: number;
  categoria?: string;
  imagen_url?: string;
}

const getBaseQuantity = (item: { cantidad?: number; cantidad_base?: number }) => {
  const parsed = Number(item.cantidad_base ?? item.cantidad ?? 0);
  return Number.isFinite(parsed) ? Math.max(0, parsed) : 0;
};

const getDisplayQuantity = (item: { cantidad?: number; cantidad_display?: number }) => {
  const parsed = Number(item.cantidad_display ?? item.cantidad ?? 0);
  return Number.isFinite(parsed) ? Math.max(0, parsed) : 0;
};

const getDisplayStock = (
  item: {
    stock?: number;
    factor_conversion?: number;
    unidad_base?: string;
  },
  unidad?: string,
) => {
  const baseStock = getAvailableStock(item);
  const factor = Number(item.factor_conversion || 0);
  const unidadBase = String(item.unidad_base || unidad || 'unidad');
  const unidadSeleccionada = String(unidad || unidadBase);
  if (unidadSeleccionada !== unidadBase && Number.isFinite(factor) && factor > 0) {
    return baseStock * factor;
  }
  return baseStock;
};

const getAvailableStock = (item: { tipo?: 'pack' | 'producto'; stock?: number }) => {
  if (item.tipo === 'pack') return Number.POSITIVE_INFINITY;
  const parsedStock = Number(item.stock);
  if (!Number.isFinite(parsedStock)) return Number.POSITIVE_INFINITY;
  return Math.max(0, parsedStock);
};

const getItemKey = (item: { tipo?: 'pack' | 'producto'; user_id?: string | number | null; variante_id?: string | number; cart_key?: string; pack_id?: string | number }) => {
  if (item.cart_key) return item.cart_key;
  if (item.tipo === 'pack') return `pack:${String(item.pack_id ?? item.user_id ?? '')}`;
  return `prod:${String(item.user_id ?? '')}:${String(item.variante_id ?? 'default')}`;
};

// Este hook centraliza todo lo relacionado al carrito: estado, operaciones y totales.
export function useCarrito(promociones: unknown[], sucursalId?: string, catalogo: Producto[] = []) {
  const { packs, loading: loadingPacks } = usePacks(sucursalId) as { packs: Pack[]; loading: boolean; };
  const [storedCarrito, setCarrito] = useState<CartItem[]>([]);
  const [loadedStorageKey, setLoadedStorageKey] = useState<string | null>(null);
  const storageKey = sucursalId ? `carrito_venta_${sucursalId}` : null;
  const carrito = useMemo(() => storedCarrito.map(item => priceCatalogItem(item, promociones, catalogo)) as CartItem[],
    [storedCarrito, promociones, catalogo]);
  const [stockWarning, setStockWarning] = useState('');

  // Cada sucursal conserva su propia cesta. No trasladar la cesta antigua global
  // a otra sucursal; un pedido se recupera desde su detalle y ámbito verificados.
  useEffect(() => {
    if (!storageKey) return;
    const stored = getBrowserItem(storageKey);
    if (stored) {
      try { const parsed = JSON.parse(stored); setCarrito(Array.isArray(parsed) ? parsed : []); }
      catch { setCarrito([]); }
    } else {
      setCarrito([]);
    }
    setLoadedStorageKey(storageKey);
  }, [storageKey]);
  useEffect(() => {
    if (!storageKey || loadedStorageKey !== storageKey) return;
    if (carrito.length) {
      setBrowserItem(storageKey, JSON.stringify(carrito));
    } else {
      removeBrowserItem(storageKey);
    }
  }, [carrito, storageKey, loadedStorageKey]);

  const clearStockWarning = useCallback(() => {
    setStockWarning('');
  }, []);

  const agregar = useCallback((prod: Producto) => {
    const requestedBaseQuantity = Math.max(0.0001, Number(prod.cantidad_base ?? prod.cantidad ?? 1) || 1);
    const requestedDisplayQuantity = Math.max(0.0001, Number(prod.cantidad_display ?? prod.cantidad ?? 1) || 1);
    const basePrice = Number(prod.precio_original ?? prod.precio ?? 0);
    const prodBase = {
      ...prod,
      precio: basePrice,
      precio_original: basePrice,
      unidad: prod.unidad ?? prod.unidad_base ?? 'unidad',
      cantidad_base: requestedBaseQuantity,
      cantidad_display: requestedDisplayQuantity
    };
    const precioInfo = calcularPrecioConPromocion(prodBase, promociones);
    const precioFinal = precioInfo.precioFinal;
    const availableStock = getAvailableStock(prodBase);

    if (availableStock <= 0 || requestedBaseQuantity > availableStock) {
      setStockWarning(`${prod.nombre}${prod.color ? ` (${prod.color})` : ''} ya no tiene stock disponible.`);
      return false;
    }

    setCarrito(prev => {
      const cartKey = getItemKey(prod);
      const existe = prev.find(p => getItemKey(p) === cartKey);
      if (existe) {
        if (getBaseQuantity(existe) + requestedBaseQuantity > availableStock) {
          setStockWarning(`${prod.nombre}${prod.color ? ` (${prod.color})` : ''} solo tiene ${availableStock} unidad${availableStock === 1 ? '' : 'es'} disponible${availableStock === 1 ? '' : 's'}.`);
          return prev;
        }
        return prev.map(p => getItemKey(p) === cartKey ? {
          ...p,
          precio_compra: prodBase.precio_compra ?? p.precio_compra,
          imagen_url: prodBase.imagen_url ?? p.imagen_url,
          unidad_base: prodBase.unidad_base ?? p.unidad_base,
          unidades_alternativas: prodBase.unidades_alternativas ?? p.unidades_alternativas,
          unidades_disponibles: prodBase.unidades_disponibles ?? p.unidades_disponibles,
          factor_conversion: prodBase.factor_conversion ?? p.factor_conversion,
          cantidad: Math.min(getBaseQuantity(p) + requestedBaseQuantity, availableStock),
          cantidad_base: Math.min(getBaseQuantity(p) + requestedBaseQuantity, availableStock),
          cantidad_display: getDisplayQuantity(p) + requestedDisplayQuantity,
          stock: Number.isFinite(availableStock) ? availableStock : p.stock,
          precio: precioFinal,
          precio_original: precioInfo.precioOriginal,
          descuento_item: precioInfo.descuento,
          promocion_aplicada: precioInfo.promocion,
          unidad: prodBase.unidad
        } : p);
      }
      return [...prev, {
        ...prodBase,
        cart_key: cartKey,
        cantidad: requestedBaseQuantity,
        cantidad_base: requestedBaseQuantity,
        cantidad_display: requestedDisplayQuantity,
        stock: Number.isFinite(availableStock) ? availableStock : Number(prod.stock ?? 0),
        precio: precioFinal,
        descuento_item: precioInfo.descuento,
        promocion_aplicada: precioInfo.promocion
      }];
    });
    setStockWarning('');
    return true;
  }, [promociones]);

  const agregarPack = useCallback((pack: Pack) => {
    const { descuentoAbsoluto } = calcularDescuentoPack(pack);
    const itemPack: CartItem = {
      user_id: null, // never use 'pack-<id>' as user_id
      cart_key: `pack:${String(pack.id)}`,
      nombre: `📦 ${pack.nombre}`,
      precio: pack.precio_pack,
      stock: 999,
      categoria: 'Pack Especial',
      cantidad: 1,
      tipo: 'pack',
      pack_id: pack.id,
      pack_data: pack,
      descuento_pack: descuentoAbsoluto
    };
    setCarrito(prev => {
      const existe = prev.find(p => getItemKey(p) === itemPack.cart_key);
      if (existe) {
        return prev.map(p => getItemKey(p) === itemPack.cart_key ? { ...p, cantidad: p.cantidad + 1 } : p);
      }
      return [...prev, itemPack];
    });
  }, []);

  const quitar = useCallback((itemKey: string | number) => {
    const normalized = String(itemKey);
    setCarrito(prev => prev.filter(i => getItemKey(i) !== normalized));
  }, []);


  // Cambiar cantidad y unidad (para productos con conversión)
  const cambiarUnidadYCantidad = useCallback((itemKey: string | number, cantidad: number, unidad?: string, cantidadDisplay?: number) => {
    const normalized = String(itemKey);
    setCarrito(prev => prev.map(i => {
      if (getItemKey(i) !== normalized) return i;
      const availableStock = getAvailableStock(i);
      const requested = Math.max(0.0001, Number(cantidad) || 1);
      const nextUnidad = unidad || i.unidad || i.unidad_base || 'unidad';
      const nextCantidad = Math.min(requested, availableStock);
      const factor = Number(i.factor_conversion || 0);
      const unidadBase = i.unidad_base || nextUnidad;
      const availableDisplayStock = getDisplayStock(i, nextUnidad);
      if (requested > availableStock && Number.isFinite(availableStock)) {
        setStockWarning(
          `${i.nombre}${i.color ? ` (${i.color})` : ''} solo tiene ${availableDisplayStock} ${nextUnidad} disponible${availableDisplayStock === 1 ? '' : 's'}.`
        );
      } else {
        setStockWarning('');
      }
      const derivedDisplayQuantity = nextUnidad && nextUnidad !== unidadBase && factor > 0
        ? nextCantidad * factor
        : nextCantidad;
      const nextDisplayQuantity = Number.isFinite(Number(cantidadDisplay))
        ? Math.max(0.0001, Number(cantidadDisplay))
        : derivedDisplayQuantity;
      return {
        ...i,
        cantidad: nextCantidad,
        cantidad_base: nextCantidad,
        cantidad_display: nextDisplayQuantity,
        unidad: nextUnidad
      };
    }));
  }, []);

  // Mantener compatibilidad con cambiarCantidad (solo cantidad)
  const cambiarCantidad = useCallback((itemKey: string | number, cantidad: number) => {
    cambiarUnidadYCantidad(itemKey, cantidad);
  }, [cambiarUnidadYCantidad]);

  const subtotal = useMemo(() => {
    return carrito.reduce((acc, item) => {
      if (item.tipo === 'pack') {
        const pack = packs.find(p => p.id === item.pack_id);
        return acc + (pack ? pack.precio_pack * item.cantidad : 0);
      }
      return acc + calcularLineaVenta(item, promociones, packs).total;
    }, 0);
  }, [carrito, packs, promociones]);

  const totalDescuento = useMemo(() => {
    return carrito.reduce((acc, item) => {
      if (item.tipo === 'pack') {
        const pack = packs.find(p => p.id === item.pack_id);
        const packDescuento = pack && pack.precio_individual ? (Number(pack.precio_individual) - pack.precio_pack) * item.cantidad : 0;
        return acc + Math.max(0, packDescuento);
      }
      return acc + calcularLineaVenta(item, promociones, packs).descuento;
    }, 0);
  }, [carrito, packs, promociones]);

  const total = Math.max(0, subtotal);

  return {
    carrito,
    setCarrito,
    agregar,
    agregarPack,
    quitar,
    cambiarCantidad,
    cambiarUnidadYCantidad,
    cambiarDescuento: (itemKey: string | number, valor: number) => {
      setCarrito(prev => prev.map(item => getItemKey(item) === String(itemKey)
        ? { ...item, descuento_manual: Math.round(Math.min(calcularLineaVenta(item, promociones, packs).maxManual, Math.max(0, Number.isFinite(valor) ? valor : 0)) * 100) / 100 } : item));
    },
    subtotal,
    totalDescuento,
    total,
    loadingPacks,
    stockWarning,
    clearStockWarning
  };
}

import { useState, useCallback, useEffect } from 'react';
import { supabase } from '../lib/SupabaseClient';
import { showToast } from '../components/ui/Toast';

interface Cliente {
  nombre: string;
  carnet: string;
  telefono: string;
  email: string;
  nit: string;
  guardado: boolean;
  existente: boolean;
  source: string;
  requiereFactura: boolean;
}

type GuardarAccion = 'add' | 'update';

async function resolverSucursalCliente(paisId?: string | null, sucursalId?: string | null) {
  const cleanPaisId = String(paisId || '').trim();
  const cleanSucursalId = String(sucursalId || '').trim();

  if (cleanPaisId && cleanSucursalId) {
    return { paisId: cleanPaisId, sucursalId: cleanSucursalId };
  }

  if (!cleanPaisId) {
    return { paisId: null, sucursalId: cleanSucursalId || null };
  }

  const { data: fallbackBranch, error: fallbackError } = await supabase
    .from('sucursales')
    .select('id')
    .eq('pais_id', cleanPaisId)
    .eq('activa', true)
    .order('created_at', { ascending: true })
    .limit(1)
    .maybeSingle();

  if (fallbackError || !fallbackBranch?.id) {
    throw new Error(fallbackError?.message || 'No se encontro una sucursal activa para el pais seleccionado');
  }

  return { paisId: cleanPaisId, sucursalId: fallbackBranch.id };
}

export function useCliente(sucursalId?: string | null, paisId?: string | null) {
  const [cliente, setCliente] = useState<Cliente>({
    nombre: '',
    carnet: '',
    telefono: '',
    email: '',
    nit: '',
    guardado: false,
    existente: false,
    source: '',
    requiereFactura: false
  });

  const verificarExistenciaCliente = useCallback(async (carnetRaw: string, telefonoRaw: string) => {
    const carnet = String(carnetRaw || '').trim();
    const telefono = String(telefonoRaw || '').trim();

    if (!carnet && !telefono) {
      setCliente((c: Cliente) => ({ ...c, existente: false, source: c.source === 'clientes' ? '' : c.source }));
      return;
    }

    let query = supabase.from('clientes').select('id, carnet, telefono').limit(1);
    if (paisId) query = query.eq('pais_id', paisId);
    if (sucursalId) query = query.eq('sucursal_id', sucursalId);
    if (carnet && telefono) {
      query = query.or(`carnet.eq.${carnet},telefono.eq.${telefono}`);
    } else if (carnet) {
      query = query.eq('carnet', carnet);
    } else {
      query = query.eq('telefono', telefono);
    }

    const { data, error } = await query;
    if (error) return;

    const exists = Array.isArray(data) && data.length > 0;
    setCliente((c: Cliente) => ({
      ...c,
      existente: exists,
      source: exists ? 'clientes' : (c.source === 'clientes' ? '' : c.source),
    }));
  }, [paisId, sucursalId]);

  useEffect(() => {
    const timer = setTimeout(() => {
      verificarExistenciaCliente(cliente.carnet, cliente.telefono);
    }, 350);

    return () => clearTimeout(timer);
  }, [cliente.carnet, cliente.telefono, verificarExistenciaCliente]);

  const cambiarCampo = useCallback((campo: keyof Cliente, valor: string | boolean) => {
    setCliente((c: Cliente) => ({ ...c, [campo]: valor } as Cliente));
  }, []);

  const buscarPorCarnet = useCallback(async () => {
    const q = cliente.carnet.trim();
    if (!q) {
      showToast('Ingresa numero de carnet', 'info');
      return;
    }

    // 1) perfiles
    try {
      const { data: perfil, error: perfilErr } = await supabase
        .from('perfiles')
        .select('id, nombre, nit_ci, ci_nit, telefono, email')
        .or(`nit_ci.ilike.%${q}%,ci_nit.ilike.%${q}%`)
        .limit(1)
        .maybeSingle();
      if (!perfilErr && perfil) {
        cambiarCampo('nombre', perfil.nombre || '');
        const nitval = perfil.nit_ci || perfil.ci_nit || q;
        cambiarCampo('carnet', nitval);
        cambiarCampo('telefono', perfil.telefono || '');
        if (perfil.email) {
          cambiarCampo('email', perfil.email);
          cambiarCampo('source', 'perfiles');
        } else {
          let ventasHistQuery = supabase
            .from('ventas')
            .select('cliente_email')
            .eq('cliente_nit', nitval)
            .order('fecha', { ascending: false })
            .limit(1);
          if (paisId) ventasHistQuery = ventasHistQuery.eq('pais_id', paisId);
          if (sucursalId) ventasHistQuery = ventasHistQuery.eq('sucursal_id', sucursalId);
          const { data: ventasHist } = await ventasHistQuery;
          if (ventasHist && ventasHist[0]?.cliente_email) {
            cambiarCampo('email', ventasHist[0].cliente_email);
            cambiarCampo('source', 'ventas (histórico)');
          } else {
            cambiarCampo('source', 'perfiles');
          }
        }
        cambiarCampo('nit', nitval);
        cambiarCampo('guardado', false);
        return;
      }
    } catch (e: unknown) {
      const errorMessage = e instanceof Error ? e.message : String(e);
      // console.warn('Error perfiles', errorMessage);
    }

    // 2) clientes legacy
    try {
      let cliQuery = supabase
        .from('clientes')
        .select('id, nombre, carnet, telefono, email')
        .eq('carnet', q);
      if (paisId) cliQuery = cliQuery.eq('pais_id', paisId);
      if (sucursalId) cliQuery = cliQuery.eq('sucursal_id', sucursalId);
      const { data: cli, error: cliErr } = await cliQuery.maybeSingle();
      if (!cliErr && cli) {
        setCliente({
          nombre: cli.nombre || '',
          carnet: cli.carnet || q,
          telefono: cli.telefono || '',
          email: cli.email || '',
          nit: cli.carnet || '',
          guardado: true,
          existente: true,
          source: 'clientes',
          requiereFactura: false
        });
        return;
      }
    } catch (e: unknown) {
      const errorMessage = e instanceof Error ? e.message : String(e);
      // console.warn('Error clientes', errorMessage);
    }

    // 3) ventas
    try {
      let ventasByNitQuery = supabase
        .from('ventas')
        .select('cliente_nombre, cliente_telefono, cliente_email')
        .eq('cliente_nit', q)
        .order('fecha', { ascending: false })
        .limit(1);
      if (paisId) ventasByNitQuery = ventasByNitQuery.eq('pais_id', paisId);
      if (sucursalId) ventasByNitQuery = ventasByNitQuery.eq('sucursal_id', sucursalId);
      const { data: ventasByNit } = await ventasByNitQuery;
      if (ventasByNit && ventasByNit.length) {
        const v = ventasByNit[0];
        setCliente((c: Cliente) => ({
          ...c,
          nombre: v.cliente_nombre || c.nombre,
          telefono: v.cliente_telefono || c.telefono,
          email: v.cliente_email || c.email,
          source: v.cliente_email ? 'ventas' : c.source,
          guardado: false
        }));
        return;
      }
    } catch (e: unknown) {
      const errorMessage = e instanceof Error ? e.message : String(e);
      // console.warn('Error ventas', errorMessage);
    }

    setCliente((c: Cliente) => ({ ...c, guardado: false, existente: false, source: '' }));
    showToast('Cliente no encontrado. Puedes anadirlo para busquedas futuras.', 'info');
  }, [cliente.carnet, cambiarCampo, paisId, sucursalId]);

  const guardar = useCallback(async (accion: GuardarAccion) => {
    const nombre = cliente.nombre.trim();
    const carnet = cliente.carnet.trim();
    const telefono = cliente.telefono.trim();

    if (!nombre || !telefono) {
      return showToast('Completa al menos nombre y telefono para guardar', 'error');
    }

    if (accion === 'add') {
      try {
        if (cliente.existente) {
          return showToast('Ese cliente ya existe. Usa "Actualizar cliente".', 'info');
        }

        const { data: sessionData } = await supabase.auth.getSession();
        const token = sessionData?.session?.access_token;
        const response = await fetch('/api/admin/clientes', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            ...(token ? { Authorization: `Bearer ${token}` } : {}),
          },
          body: JSON.stringify({
            nombre,
            carnet: carnet || null,
            telefono: telefono || null,
            email: cliente.email || null,
            pais_id: paisId || null,
            sucursal_id: sucursalId || null,
          }),
        });
        const result = await response.json().catch(() => ({}));

        if (!response.ok || !result?.success) {
          return showToast(result?.error || 'Error al anadir cliente', 'error');
        }

        setCliente((c: Cliente) => ({ ...c, guardado: true, existente: true, source: 'clientes' }));
        return showToast('Cliente anadido correctamente');
      } catch (e) {
        const message = e instanceof Error ? e.message : '';
        return showToast(message || 'Error inesperado al anadir cliente', 'error');
      }
    }

    let actualizadoEnPerfiles = false;
    let actualizadoEnClientes = false;
    const scope = await resolverSucursalCliente(paisId, sucursalId);

    try {
      if (carnet) {
        const { data: perfilExistente, error: perfilErr } = await supabase
          .from('perfiles')
          .select('id, nit_ci, ci_nit')
          .or(`nit_ci.ilike.%${carnet}%,ci_nit.ilike.%${carnet}%`)
          .limit(1)
          .maybeSingle();
        if (!perfilErr && perfilExistente) {
          const { error: upErr } = await supabase
            .from('perfiles')
            .update({
              nombre,
              telefono: telefono || null,
              email: cliente.email || null,
              nit_ci: carnet
            })
            .eq('id', perfilExistente.id);
          if (upErr) return showToast('Error al actualizar perfil: ' + upErr.message, 'error');
          actualizadoEnPerfiles = true;
        }
      }
    } catch (e) {
      // console.warn('guardarCliente perfil', e);
    }

    try {
      let updateQuery = supabase
        .from('clientes')
        .update({
          nombre,
          telefono: telefono || null,
          email: cliente.email || null,
          carnet: carnet || null,
        });
      if (scope.paisId) updateQuery = updateQuery.eq('pais_id', scope.paisId);
      if (scope.sucursalId) updateQuery = updateQuery.eq('sucursal_id', scope.sucursalId);

      if (carnet) {
        updateQuery = updateQuery.eq('carnet', carnet);
      } else {
        updateQuery = updateQuery.eq('telefono', telefono);
      }

      const { data: updatedClientes, error: updateError } = await updateQuery.select('id');

      if (updateError) return showToast('Error al actualizar cliente: ' + (updateError.message || ''), 'error');

      actualizadoEnClientes = Array.isArray(updatedClientes) && updatedClientes.length > 0;

      if (!actualizadoEnClientes && !actualizadoEnPerfiles) {
        return showToast('No se encontro cliente para actualizar. Usa "Anadir cliente".', 'info');
      }

      const source = actualizadoEnClientes
        ? (actualizadoEnPerfiles ? 'clientes y perfiles' : 'clientes')
        : 'perfiles';

      setCliente((c: Cliente) => ({ ...c, guardado: true, existente: true, source }));
      showToast(`Cliente actualizado correctamente en ${source}`);
    } catch (e) {
      // console.error(e);
      showToast('Error inesperado al actualizar cliente', 'error');
    }
  }, [cliente, paisId, sucursalId]);

  const buscarEmailHistorico = useCallback(async () => {
    try {
      const q = cliente.carnet.trim() || cliente.nit.trim();
      if (!q) return showToast('Introduce carnet o NIT para buscar email historico', 'info');
      let query = supabase.from('ventas').select('cliente_email').or(`cliente_nit.ilike.%${q}%,cliente_telefono.ilike.%${q}%`).order('fecha', { ascending: false }).limit(1);
      if (paisId) query = query.eq('pais_id', paisId);
      if (sucursalId) query = query.eq('sucursal_id', sucursalId);
      const { data } = await query;
      if (data && data[0]?.cliente_email) {
        setCliente((c: Cliente) => ({ ...c, email: data[0].cliente_email, source: 'ventas (histórico)' }));
        showToast('Email recuperado desde ventas historicas');
      } else {
        showToast('No se encontro email historico', 'info');
      }
    } catch (e) { /* console.warn(e); */ showToast('Error buscando email historico', 'error'); }
  }, [cliente.carnet, cliente.nit, paisId, sucursalId]);

  return { cliente, cambiarCampo, buscarPorCarnet, guardar, buscarEmailHistorico };
}

import { useState, useEffect } from "react";
import { supabase } from "../lib/SupabaseClient";

export function useMetodoStats(metodoKey, metodoLabel, metodoKeys = []) {
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [stats, setStats] = useState(null);
  const [rows, setRows] = useState([]);
  const [chartData, setChartData] = useState([]);
  const [prevChartData, setPrevChartData] = useState([]);
  const [growth, setGrowth] = useState(null);
  const [insight, setInsight] = useState("");
  const [kpis, setKpis] = useState(null);
  const [diasSinVentas, setDiasSinVentas] = useState(0);

  useEffect(() => {
    async function fetchStats() {
      setLoading(true);
      setError(null);
      try {
        // Fechas actuales
        const today = new Date();
        const start = new Date(today);
        start.setDate(today.getDate() - 29);
        const startDate = start.toISOString().slice(0, 10);
        const endDate = today.toISOString().slice(0, 10);

        // Fechas anteriores
        const prevStart = new Date(start);
        prevStart.setDate(prevStart.getDate() - 30);
        const prevStartDate = prevStart.toISOString().slice(0, 10);
        const prevEnd = new Date(start);
        prevEnd.setDate(prevEnd.getDate() - 1);
        const prevEndDate = prevEnd.toISOString().slice(0, 10);

        const { getCashSummary } = await import("../services/cash.service.js");
        // Actual
        const summary = await getCashSummary(supabase, {
          start_date: startDate,
          end_date: endDate,
        });
        // Anterior
        const prevSummary = await getCashSummary(supabase, {
          start_date: prevStartDate,
          end_date: prevEndDate,
        });

        // Actual
        const pagosSistema = (summary.sales || []).filter(s => {
          const key = (s.modo_pago || "other").toLowerCase();
          return metodoKeys.includes(key);
        });
        const pagosManual = (summary.movements || []).filter(m => metodoKeys.includes(m.payment_method) && m.type === "income");
        const totalSistema = pagosSistema.reduce((acc, s) => acc + Number(s.total || 0), 0);
        const totalManual = pagosManual.reduce((acc, m) => acc + Number(m.amount || 0), 0);
        const countSistema = pagosSistema.length;
        const countManual = pagosManual.length;
        const total = totalSistema + totalManual;
        const allPagos = [...pagosSistema, ...pagosManual];
        const totalPagos = countSistema + countManual;
        const promedio = totalPagos > 0 ? total / totalPagos : 0;
        const maximo = allPagos.length > 0 ? Math.max(...allPagos.map(p => Number(p.total || p.amount || 0))) : 0;
        const minimo = allPagos.length > 0 ? Math.min(...allPagos.map(p => Number(p.total || p.amount || 0))) : 0;
        const pctSistema = total > 0 ? (totalSistema / total) * 100 : 0;
        const pctManual = total > 0 ? (totalManual / total) * 100 : 0;

        // Anterior
        const prevPagosSistema = (prevSummary.sales || []).filter(s => {
          const key = (s.modo_pago || "other").toLowerCase();
          return metodoKeys.includes(key);
        });
        const prevPagosManual = (prevSummary.movements || []).filter(m => metodoKeys.includes(m.payment_method) && m.type === "income");
        const prevTotal = prevPagosSistema.reduce((acc, s) => acc + Number(s.total || 0), 0) + prevPagosManual.reduce((acc, m) => acc + Number(m.amount || 0), 0);

        // Crecimiento
        let growth = null;
        if (prevTotal > 0) {
          growth = ((total - prevTotal) / prevTotal) * 100;
        } else if (total > 0) {
          growth = 100;
        } else {
          growth = 0;
        }
        setGrowth(growth);

        // KPIs avanzados
        setKpis({
          total,
          promedio,
          maximo,
          minimo,
          pctSistema,
          pctManual,
          totalSistema,
          totalManual,
          countSistema,
          countManual,
          flujoDiario: total / 30,
        });

        setStats({ totalSistema, totalManual, countSistema, countManual, total });

        // Insight avanzado
        let insightText = "Rendimiento estable";
        if (growth < 0) {
          insightText = `Tus ingresos por ${metodoLabel} están bajando. Revisa promociones o incentivos.`;
        } else if (totalManual > totalSistema) {
          insightText = `La mayoría de pagos son manuales. Considera incentivar ${metodoLabel} automático.`;
        } else if (promedio < 50 && totalPagos > 0) {
          insightText = `Ticket promedio bajo en ${metodoLabel}. Analiza promociones o combos.`;
        } else if (total > 500) {
          insightText = `El sistema ${metodoLabel} está funcionando bien y dominando las ventas.`;
        }
        setInsight(insightText);

        // Tabla avanzada: pagos recientes (ordenados por monto)
        const pagosRecientes = [
          ...pagosSistema.map(s => ({
            id: `venta-${s.id}`,
            fecha: s.fecha,
            tipo: "Sistema",
            monto: Number(s.total),
            ref: s.id,
            descripcion: `Venta #${s.id}`,
          })),
          ...pagosManual.map(m => ({
            id: `manual-${m.id}`,
            fecha: m.date,
            tipo: "Manual",
            monto: Number(m.amount),
            ref: m.id,
            descripcion: m.description || `Ingreso manual ${metodoLabel}`,
          })),
        ].sort((a, b) => b.monto - a.monto).slice(0, 20);
        setRows(pagosRecientes);

        // Gráfico: ingresos por día (actual)
        const ingresosPorDia = {};
        for (let i = 0; i < 30; i++) {
          const d = new Date(start);
          d.setDate(d.getDate() + i);
          const key = d.toISOString().slice(0, 10);
          ingresosPorDia[key] = 0;
        }
        pagosSistema.forEach(s => {
          const key = String(s.fecha).slice(0, 10);
          if (ingresosPorDia[key] !== undefined) ingresosPorDia[key] += Number(s.total || 0);
        });
        pagosManual.forEach(m => {
          const key = String(m.date).slice(0, 10);
          if (ingresosPorDia[key] !== undefined) ingresosPorDia[key] += Number(m.amount || 0);
        });
        const chartArr = Object.entries(ingresosPorDia).map(([date, value]) => ({ date, value }));
        setChartData(chartArr);

        // Gráfico: ingresos por día (periodo anterior)
        const prevIngresosPorDia = {};
        for (let i = 0; i < 30; i++) {
          const d = new Date(prevStart);
          d.setDate(d.getDate() + i);
          const key = d.toISOString().slice(0, 10);
          prevIngresosPorDia[key] = 0;
        }
        prevPagosSistema.forEach(s => {
          const key = String(s.fecha).slice(0, 10);
          if (prevIngresosPorDia[key] !== undefined) prevIngresosPorDia[key] += Number(s.total || 0);
        });
        prevPagosManual.forEach(m => {
          const key = String(m.date).slice(0, 10);
          if (prevIngresosPorDia[key] !== undefined) prevIngresosPorDia[key] += Number(m.amount || 0);
        });
        const prevChartArr = Object.entries(prevIngresosPorDia).map(([date, value]) => ({ date, value }));
        setPrevChartData(prevChartArr);

        // Días sin ventas
        const diasSin = chartArr.filter(d => d.value === 0).length;
        setDiasSinVentas(diasSin);

      } catch (err) {
        console.error(err);
        setError(err.message || "Error cargando datos");
        setInsight("");
      } finally {
        setLoading(false);
      }
    }
    fetchStats();
  }, [metodoKey]);

  return { loading, error, stats, rows, chartData, prevChartData, growth, insight, kpis, diasSinVentas };
}

